['Here's a skeleton code in C which implements the described functionality using pthread library for threading and stdlib for random number generation. It includes basic error checking to handle memory allocation failures and uses simple semaphore for safe multi-threaded operation.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int value;
} record;

sem_t sem;  // declare a global semaphore

void* allocateAndInitialize(long *offsets, int *keys, record **records, int maxRecords) {
    srand(time(0));  // seed the random number generator with current time

    offsets = malloc(sizeof(long)*maxRecords);
    if (offsets == NULL) return "Error allocating memory for offsets";

    keys = malloc(sizeof(int)*maxRecords);
    if (keys == NULL) return "Error allocating memory for keys";

    records = calloc(maxRecords, sizeof(record*));
    if (records == NULL) return "Error allocating memory for records";

    for (long i = 0; i < maxRecords; i++){
        sem_wait(&sem);  // acquire the semaphore before entering critical section

        offsets[i] = rand();
        keys[i] = rand();

        record *newRecord = malloc(sizeof(record));
        if (newRecord == NULL) return "Error allocating memory for new record";

        records[keys[i]] = newRecord;

        sem_post(&sem);  // release the semaphore after exiting critical section
    }

    return NULL;  
}

void* deallocateMemory(long *offsets, int *keys, record **records, int maxRecords) {
    for (int i = 0; i < maxRecords; i++){
        free(records[i]);  // deallocate each record
    }

    free(records);  // deallocate records array
    free(offsets);  // deallocate offsets array
    free(keys);  // deallocate keys array

    sem_destroy(&sem);  // destroy the semaphore at end of operation

    return NULL;
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;
    int maxRecords = 1000;

    sem_init(&sem, 0, 1);  // initialize the semaphore with initial value 1

    char* errMsg = allocateAndInitialize(offsets, keys, records, maxRecords);
    if (errMsg != NULL) {
        printf("%s\n", errMsg);
        return -1;
    }

    // Use the allocated memory here.

    deallocateMemory(offsets, keys, records, maxRecords);

    return 0;
}
```
This example uses the `sem_wait()` and `sem_post()` functions to safely enter and exit the critical section of code that modifies shared memory. Note: This is a simplistic approach for managing concurrency and doesn't actually handle multiple threads or errors related to them, you need more advanced techniques like mutexes (`pthread_mutex_lock()`/`unlock()`) etc. in real world scenarios.
']

