#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int find_largest(int *arr, int size) {
    if (size <= 0 || arr == NULL) return -1; //invalid case

    int maxVal = INT_MIN;
    int maxIndex = -1;

    for (int i = 0; i < size; i++) {
        if(arr[i] > maxVal){
            maxVal = arr[i];
            maxIndex = i;
        } 
    }
    return maxIndex; // returns the index of largest number
}

int main() {

    int *arr = (int *)malloc(1000 * sizeof(int)); 
    if (arr == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        return -1; // gracefully handle memory failure
    }

    int i, num;

    for(i = 0; i < 1000 && scanf("%d", &num) == 1; i++){ 
        if (num > INT_MAX || num < INT_MIN) { //check out of range
            printf("Integer exceeds the range. Exiting...\n");
            return -1;
        }
        arr[i] = num;
    }

    qsort(arr, i, sizeof(int), [](const void *a, const void *b){ // sort array in ascending order
        int arg1 = *(const int*)a;
        int arg2 = *(const int*)b;

        if (arg1 < arg2) return -1;
        if (arg1 > arg2) return 1;
        return 0;
    });

    printf("Sorted array: ");
    for (int j = 0; j<i;j++){ //print sorted array
        printf("%d ", arr[j]);
    }

    int maxIndex = find_largest(arr, i); 

    if(maxIndex >= 0) { //if valid index found print it
        printf("\nLargest integer in the array is: %d", arr[maxIndex]);
        printf("\nIts index is: %d\n", maxIndex);
    } else {
        printf("\nNo integers were entered.\n");
    }

    free(arr);  //free allocated memory

    return 0;
}
```
