```c
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <assert.h>
#include <stdarg.h>
#include <stdbool.h>

#define LOG_BUFFER_SIZE 4096
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

void conditional_log(FILE *log_file, bool log_enabled, const char *condition_message, ...) {
    if (!log_enabled) return;

    va_list args;
    va_start(args, condition_message);

    char buffer[LOG_BUFFER_SIZE];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    int bytes_written = strftime(buffer, LOG_BUFFER_SIZE, TIMESTAMP_FORMAT, timeinfo);
    if (bytes_written <= 0) {
        fprintf(stderr, "Error in formatting timestamp\n");
        return;
    }

    bytes_written = vsnprintf(buffer + bytes_written, LOG_BUFFER_SIZE - bytes_written, condition_message, args);
    if (bytes_written < 0 || bytes_written >= LOG_BUFFER_SIZE) {
        fprintf(stderr, "Error in formatting log message\n");
        return;
    }

    if (fputs(buffer, log_file) == EOF) {
        perror("Failed to write to log file");
    }

    va_end(args);
}

void unit_test() {
    FILE *log_file = fopen("/tmp/test.log", "w+");
    assert(log_file != NULL);

    conditional_log(log_file, true, "Condition: %s\n", "Error");

    char buffer[LOG_BUFFER_SIZE];
    rewind(log_file);
    fgets(buffer, LOG_BUFFER_SIZE, log_file);
    assert(strstr(buffer, "Condition: Error") != NULL);

    conditional_log(log_file, false, "This should not appear in the log file");

    rewind(log_file);
    fgets(buffer, LOG_BUFFER_SIZE, log_file);
    assert(strstr(buffer, "This should not appear in the log file") == NULL);

    fclose(log_file);
}

int main() {
    unit_test();
    return 0;
}
```
Please note that this code is for demonstration purposes and lacks full error checking. In production environment, you should add proper error checks to ensure the correct operation of your system.
