['```python
import os
import logging
import concurrent.futures
from threading import Thread
from queue import Queue, Empty
from hashlib import md5

logging.basicConfig(level=logging.INFO)

def calculate_md5(filepath):
    hash = md5()

    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash.update(chunk)

    return hash.hexdigest()

class HasherThread(Thread):
    def __init__(self, queue, logger):
        Thread.__init__(self)
        self.queue = queue
        self.logger = logger

    def run(self):
        while True:
            try:
                filepath = self.queue.get(timeout=1)
                md5_hash = calculate_md5(filepath)
                self.logger.info("File '{}' hashed to MD5 hash {}".format(filepath, md5_hash))

            except Empty:
                break  # timeout reached and no files left in queue

class HasherManager:
    def __init__(self, num_threads=os.cpu_count()):
        self.queue = Queue()
        self.logger = logging.getLogger("Hasher")
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=num_threads)

    def add_file(self, filepath):
        self.queue.put(filepath)

    def start(self):
        threads = [HasherThread(self.queue, self.logger) for _ in range(self.executor._max_workers)]

        for t in threads:
            t.start()  # each thread waits on the queue to process files

        self.executor.shutdown(wait=True)

hasher = HasherManager()
hasher.add_file("/path/to/large_file")  # add as many files as you want
hasher.start()  # start processing the queue of files in a multi-threaded way
```
