    private static final String TYPE_API = "https://pokeapi.co/api/v2/type/{0}/"; //replace with actual API url
    LoadingCache<String, TypeData> cache;

    public PokemonReport() {
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(100) 
                .expireAfterWrite(24, TimeUnit.HOURS)
                .build(new CacheLoader<String, TypeData>() {
                    public TypeData load(String typeName) throws Exception {
                        return fetchTypeDataFromAPI(typeName);
                    }
                }); 
    }

    private TypeData fetchTypeDataFromAPI(String typeName) {
        String apiUrl = MessageFormat.format(TYPE_API, typeName);
        try {
            URL url = new URL(apiUrl);
            HttpURLConnection conn = (HttpURLConnection)url.openConnection();
            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));

            String inputLine;
            StringBuffer content = new StringBuffer();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
            conn.disconnect();

            return new Gson().fromJson(content.toString(), TypeData.class);
        } catch (Exception e) {
            throw new RuntimeException("Failed to fetch type data from API", e);
        }
    }

