#include <algorithm>
void insertAndUnique(std::vector<int> &vec, int num1, int num2) {
    std::sort(vec.begin(), vec.end());
    vec.erase(std::unique(vec.begin(), vec.end()), vec.end());

    auto it = std::find(vec.begin(), vec.end(), num1);
    if (it != vec.end()) {
        vec.insert(++it, num2);
    } else {
        vec.push_back(num2);
    }
}
