['```C++
#include <iostream>
#include <fstream>
#include <string>
#include <ctime>
#include <cstdlib>

namespace Logging {
    enum Level { DEBUG, INFO, WARNING, ERROR };

    class Logger {
        static Level currentLevel;
        std::ofstream outputFile;

        void writeLog(const std::string& message) {
            outputFile << message << std::endl;
        }

        public:
        Logger() : outputFile("log.txt", std::ios_base::app) {}
        ~Logger() {
            outputFile.close();
        }

        static void setLevel(const Level& level) {
            currentLevel = level;
        }

        static Level getLevel() {
            return currentLevel;
        }

        static std::string getCurrentTime() {
            time_t now = time(0);
            char* dt = ctime(&now);
            // remove newline character
            dt[strlen(dt) - 1] = 0;

            return std::string(dt);
        }

        void logMessage(const Level& level, const std::string& message) {
            if (level < currentLevel) {
                return;
            }

            std::cout << getCurrentTime() << " [" << level << "]: " << message << std::endl;
            writeLog(getCurrentTime() + " [" + std::to_string(level) + "]: " + message);
        }
    };

    Level Logger::currentLevel = INFO;
}

int main() {
    const char* logEnv = getenv("LOG_LEVEL");
    if (logEnv != nullptr && strlen(logEnv) > 0) {
        Logging::Logger::setLevel((Logging::Level)std::stoi(logEnv));
    }

    Logging::Logger logger;

    logger.logMessage(Logging::DEBUG, "Debug message");
    logger.logMessage(Logging::INFO, "Info message");
    logger.logMessage(Logging::WARNING, "Warning message");
    logger.logMessage(Logging::ERROR, "Error message");

    return 0;
}
```
