```javascript
async function copyBuffer(dataChunks, limit, checksumAlgorithm) {
    let totalBytes = 0;
    const buffers = [];

    for (const chunk of dataChunks) {
        if (!(chunk instanceof Buffer)) {
            throw new Error('Invalid data format');
        }

        const bytesInChunk = chunk.length;
        if (totalBytes + bytesInChunk > limit) {
            throw new Error('Exceeded the specified limit');
        }

        buffers.push(chunk);
        totalBytes += bytesInChunk;
    }

    const result = Buffer.concat(buffers, totalBytes);
    const checksum = await checksumAlgorithm(result);

    return { buffer: result, checksum };
}
```
