import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class TransactionGroup {
    private final ConcurrentHashMap<List<Transaction>, Integer> cache = new ConcurrentHashMap<>();

    public int getDisjointGroups(List<Transaction> transactions) {
        List<Set<String>> disjointSets = new ArrayList<>();

        if (cache.containsKey(transactions)) {
            return cache.get(transactions);
        }

        long startTime = System.currentTimeMillis();

        for (Transaction transaction : transactions) {
            Set<String> disjointSet = new HashSet<>(transaction.productIds);

            ListIterator<Set<String>> itr = disjointSets.listIterator();
            while (itr.hasNext()) {
                if (!Collections.disjoint(itr.next(), disjointSet)) {
                    disjointSet.addAll(disjointSet);
                    itr.remove();
                }
            }

            disjointSets.add(disjointSet);
        }

        int groupCount = disjointSets.size();

        cache.put(transactions, groupCount);

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken to process transaction groups: " + (endTime - startTime) + "ms");

        return groupCount;
    }

    public static class Transaction {
