['Here is a basic skeleton for such a method in Java using NIO2 (Non-blocking I/O):

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;

public class SecureServerConnection {
    private Selector selector;
    private SocketChannel clientChannel;

    public void connectToServers(String[] servers) throws IOException {
        this.selector = Selector.open();

        for (String server : servers) {
            InetSocketAddress address = new InetSocketAddress(server, 80); // Port number should be correct.

            clientChannel = SocketChannel.open(address);
            clientChannel.configureBlocking(false);

            clientChannel.register(this.selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ | SelectionKey.OP_WRITE);
        }

        int numConnectedServers = 0;
        while (numConnectedServers < servers.length) {
            if (this.selector.select(1000) == 0) { // 1 second timeout for connect operation
                System.out.println("Connection timed out.");
                continue;
            }

            Iterator<SelectionKey> keys = this.selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();

                if (!key.isValid()) {
                    continue;
                }

                if (key.isConnectable()) {
                    finishConnection(key);
                    ++numConnectedServers;
                } else if (key.isReadable() || key.isWritable()) {
                    handleIO(key);
                }

                keys.remove(); // Remove the key so we don't process it again
            }
        }
    }

    private void finishConnection(SelectionKey key) throws IOException {
        SocketChannel server = (SocketChannel) key.channel();

        if (server.isConnectionPending()) {
            server.finishConnect();
        }

        server.register(this.selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
    }

    private void handleIO(SelectionKey key) throws IOException {
        if (key.isReadable()) {
            readFromChannel((SocketChannel) key.channel());
        } else if (key.isWritable()) {
            writeToChannel((SocketChannel) key.channel(), "PUT YOUR MESSAGE HERE");
        }
    }

    private void readFromChannel(SocketChannel server) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int numRead;

        if ((numRead = server.read(buffer)) == -1) { // If EOF reached
            System.out.println("Server closed connection.");
            key.cancel();
            server.close();
            return;
        }

        byte[] data = new byte[numRead];
        System.arraycopy(buffer.array(), 0, data, 0, numRead);

        // TODO: Process incoming message here.
    }

    private void writeToChannel(SocketChannel server, String msg) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(msg.getBytes());
        server.write(buffer);
    }
}
```
This is a basic example and does not include all the bells and whistles of secure connections (like certificate handling), or advanced load balancing strategies, but it provides an outline for how you might structure such a method. You would need to fill in your own message handling logic as well as replace "PUT YOUR MESSAGE HERE" with whatever data needs sending.
']

