use std::time::{Duration, Instant};
use libc::getrusage;
use rustc_driver::catch_with_exit_code;
use icehook::SyncLazy;
use early_error::early_error;
use distlogs::client::Client as DistLogsClient;

const COMPILE_TIMEOUT: Duration = Duration::from_secs(30);
const MEMORY_PROFILING_INTERVAL: Duration = Duration::from_millis(100);

fn get_resident_set_size() -> usize {
    let mut usage = unsafe { std::mem::MaybeUninit::<libc::rusage>::uninit() };
    assert_eql(getrusage(libc::RUSAGE_SELF, usage.as_mut_ptr()), 0);
    unsafe { (*usage.assume_init()).ru_maxrss as usize }
}

fn compile_rust() -> i32 {
    let mut distlogs = DistLogsClient::new("distributed-logging-url");

    let start_time = Instant::now();
    let start_memory_usage = get_resident_set_size();

    let hook = SyncLazy::new(move || {
        catch_with_exit_code(|| {
            // Code to compile Rust here...
            0
        }, |e| {
            early_error(&format_args![
                "Compilation error: {}", e
            ]);
            distlogs.send(&format_args![
                "Compilation Error: {}", e
            ])?;
            1
        })
    });

    let end_memory_usage = get_resident_set_size();
    let elapsed = start_time.elapsed();

    distlogs.send(&format_args![
        "Compilation metrics: Elapsed time - {}, Memory usage - {}", 
        elapsed.as_secs(), end_memory_usage - start_memory_usage
    ])?;

    hook()
}
