['Here is a basic example of how you could implement this in PHP. This does not cover all possible edge cases or error handling for brevity, but it should give you an idea of what your function might look like. Please note that to use the OAuth2 server, you need to have a registered app there with client id and secret.

```php
<?php
function authenticateUser($clientId, $clientSecret) {
    session_start();

    $cache = new Memcached('memcached_pool');

    if (isset($_SESSION['accessToken'])) {
        $token = $_SESSION['accessToken'];
        if (!$cache->get('userInfo')) {
            $apiClient = new GuzzleHttp\Client();
            try {
                $res = $apiClient->request('GET', 'https://oauth.server/api/users/me', [
                    'headers' => [
                        'Authorization' => "Bearer $token"
                    ]
                ]);

                $userInfo = json_decode($res->getBody(), true);
                $cache->set('userInfo', $userInfo, time() + 3600); // Cache for 1 hour
            } catch (GuzzleHttp\Exception\ClientException $e) {
                if ($e->getResponse()->getStatusCode() === '401') {
                    $token = refreshToken($clientId, $clientSecret);
                    authenticateUser($clientId, $clientSecret); // Recursively call the function with new token
                } else {
                    throw $e;
                }
            }
        } else {
            $userInfo = $cache->get('userInfo');
        }
    } else {
        $token = getToken($clientId, $clientSecret);
        $_SESSION['accessToken'] = $token;

        authenticateUser($clientId, $clientSecret); // Recursively call the function with new token
    }

    return $userInfo;
}

function getToken($clientId, $clientSecret) {
    $apiClient = new GuzzleHttp\Client();

    $res = $apiClient->request('POST', 'https://oauth.server/token', [
        'form_params' => [
            'grant_type' => 'client_credentials',
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
        ],
    ]);

    $response = json_decode($res->getBody(), true);
    $token = $response['access_token'];

    return $token;
}

function refreshToken($clientId, $clientSecret) {
    $apiClient = new GuzzleHttp\Client();

    $res = $apiClient->request('POST', 'https://oauth.server/token', [
        'form_params' => [
            'grant_type' => 'refresh_token',
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'refresh_token' => $_SESSION['refreshToken'],
        ],
    ]);

    $response = json_decode($res->getBody(), true);
    $token = $response['access_token'];

    return $token;
}
?>
```
']

