class UserService {
    private $userDao;
    private $messageQueue;
    private $identityService;
    private $cache;

    public function __construct(UserDao $userDao, MessageQueue $messageQueue, IdentityService $identityService, Cache $cache) {
        $this->userDao = $userDao;
        $this->messageQueue = $messageQueue;
        $this->identityService = $identityService;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword) {
        try{
            $cachedUser = $this->cache->get("user:$userId");
            if ($cachedUser){
                $user = unserialize($cachedUser);
            } else {
                $user = $this->userDao->findById($userId);
                // set cache after fetching user from db 
                // so that if we get a request for the same user within our timeout window,
                // we don't need to re-fetch it from DB
                $this->cache->set("user:$userId", serialize($user), 100);
            }

            $valid = $this->identityService->validatePasswordComplexity($newPassword);
            if (!$valid) {
                throw new InvalidArgumentException('Invalid password complexity');
            }

            $hashedNewPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $user->setPassword($hashedNewPassword);

            $this->messageQueue->publish("passwordUpdated", serialize([
                'userId' => $userId, 
                'hashedNewPassword' => $hashedNewPassword]));
        } catch (DatabaseException $e) {
            // Retry logic goes here.
        } catch (NetworkException | ServiceUnavailableException $e) {
            // Handle network issue or service unavailability gracefully.
        } catch (Throwable $t) {
            // Log the error for debugging and re-throw it.
            throw $t;
        }
    }
}
?>
