['Below is an example of how you could approach this task using a C program with pthreads and a linked list as the primary data structure. This solution does not guarantee optimal performance as there are many factors involved in efficient real-time transaction handling, but it should provide a reasonable starting point.

```c
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct Transaction {
    unsigned int id;
    time_t timestamp;
    double weight;
    struct Transaction* next;
} Transaction;

typedef struct TransactionList {
    pthread_mutex_t lock;
    Transaction *head, *tail;
} TransactionList;

TransactionList list = { PTHREAD_MUTEX_INITIALIZER, NULL, NULL };
double runningTotal = 0.0;

void addTransaction(unsigned int id, time_t timestamp, double weight) {
    pthread_mutex_lock(&list.lock);

    Transaction* newTx = malloc(sizeof(Transaction));
    newTx->id = id;
    newTx->timestamp = timestamp;
    newTx->weight = weight;
    newTx->next = NULL;

    if (list.tail == NULL) {
        list.head = list.tail = newTx;
    } else {
        list.tail->next = newTx;
        list.tail = newTx;
    }

    pthread_mutex_unlock(&list.lock);
}

void removeOldTransactions() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t currentTime = tv.tv_sec;

    pthread_mutex_lock(&list.lock);

    while (list.head && list.head->timestamp < currentTime - 5) {
        Transaction* oldHead = list.head;
        list.head = list.head->next;

        if (list.head == NULL) {
            list.tail = NULL;
        }

        free(oldHead);
    }

    pthread_mutex_unlock(&list.lock);
}

void processTransactions() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t currentTime = tv.tv_sec;

    Transaction* tx = list.head;
    double highestWeightedSum = 0.0;
    unsigned int idWithHighestWeightedSum = 0;
    int txCountInLast3Seconds = 0;

    while (tx) {
        if (currentTime - tx->timestamp <= 5 && currentTime - tx->timestamp > 2) {
            txCountInLast3Seconds++;
        }

        if (currentTime - tx->timestamp <= 5) {
            runningTotal += tx->weight;

            double weightedSum = runningTotal - (txCountInLast3Seconds * tx->weight);

            if (weightedSum > highestWeightedSum) {
                highestWeightedSum = weightedSum;
                idWithHighestWeightedSum = tx->id;
            }
        }

        tx = tx->next;
    }

    printf("Transaction ID with the highest weighted sum: %u\n", idWithHighestWeightedSum);
}

void reset() {
    pthread_mutex_lock(&list.lock);

    while (list.head) {
        Transaction* oldHead = list.head;
        list.head = list.head->next;

        free(oldHead);
    }

    runningTotal = 0.0;

    pthread_mutex_unlock(&list.lock);
}
``` 

This code is not a complete solution as it lacks handling of concurrent updates to the transaction list without data corruption, but it provides a starting point for managing dynamic transactions and applying certain filtering criteria based on timestamp and weight.
']

['```C++
#include <chrono>
#include <thread>

// Predefined attack patterns A and B
void AttackPatternA();
void AttackPatternB();

class CooldownTimer {
public:
    explicit CooldownTimer(std::chrono::milliseconds cooldown) : cooldown_(cooldown), lastExecutionTime_(0) {}

    bool isReady() const {
        auto now = std::chrono::system_clock::now();
        return std::chrono::duration_cast<std::chrono::milliseconds>(now - lastExecutionTime_) >= cooldown_;
    }

    void resetCooldown() {
        lastExecutionTime_ = std::chrono::system_clock::now();
    }

private:
    std::chrono::milliseconds cooldown_;
    std::chrono::time_point<std::chrono::system_clock> lastExecutionTime_;
};

class AttackManager {
public:
    explicit AttackManager(int playerId) : playerId_(playerId), attackPatternATimer_(4000), attackPatternBTimer_(5000) {}

    void selectAndExecuteAttack() {
        if (isAttackingA_) {
            if (attackPatternATimer_.isReady()) {
                AttackPatternB();
                isAttackingA_ = false;
                attackPatternBTimer_.resetCooldown();
            }
        } else {
            if (attackPatternBTimer_.isReady()) {
                AttackPatternA();
                isAttackingA_ = true;
                attackPatternATimer_.resetCooldown();
            }
        }
    }

private:
    int playerId_;
    bool isAttackingA_ = false; // Assumes the initial pattern is B for fairness
    CooldownTimer attackPatternATimer_, attackPatternBTimer_;
};
```
In this code, we define a class `CooldownTimer` to manage cooldowns for each attack pattern. The function `isReady()` checks if the specified cooldown has passed since the last execution of the attack pattern. `AttackManager` class manages the attack sequences for each player. It uses two `CooldownTimers` for tracking cooldowns and executing corresponding attack patterns in an alternating manner.
