```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public abstract class RandomValueGenerator<T> where T : IComparable<T>
{
    protected readonly Random _random;
    public T Min { get; }
    public T Max { get; }

    private T _lastGeneratedValue;

    protected RandomValueGenerator(int seed, T min, T max)
    {
        if (min.CompareTo(max) > 0) throw new ArgumentOutOfRangeException("Min cannot be greater than max.");

        Min = min;
        Max = max;
        _random = new Random(seed);
    }

    public T Generate()
    {
        return (_lastGeneratedValue = NextRandom());
    }

    protected abstract T NextRandom();

    public void ResetToInitialState()
    {
        var seed = _random.Next(); // Get a new seed
        _random.Reseed(seed); // Re-initialize the random number generator with the new seed

        _lastGeneratedValue = default;
    }

    public override string ToString()
    {
        return $"Seed: {_random.Next()}, Min: {Min}, Max: {Max}, Last Generated Value: {_lastGeneratedValue}";
    }
}
```

