    strcpy(extension, &path[strlen(path) - 4]);
    if (strcmp(extension, ".json") == 0) {
        bundle = loadResourceFromJson(path);
    } else if (strcmp(extension, ".xml") == 0) {
        bundle = loadResourceFromXml(path);
    } else {
        logError("Unsupported file type.");
