using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public interface IConfigurationService
{
    void UpdateWebConfig(string directoryPath);
}

public class WebSiteManager
{
    private readonly ILogger<WebSiteManager> _logger;
    private readonly IConfigurationService _configurationService;

    public WebSiteManager(ILogger<WebSiteManager> logger, IConfigurationService configurationService)
    {
        _logger = logger;
        _configurationService = configurationService;
    }

    // Async Task to avoid blocking the main thread.
    public async Task AddAndStartWebSiteAsync(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new ArgumentException("Directory not found.");
        }

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
        {
            _logger.LogWarning($"{siteName} has no web.config file.");
            return;
        }

        try
        {
            // Ensure all subdirectories are created with the correct permissions.
            Directory.CreateDirectory(Path.Combine(directoryPath, "bin"));
            Directory.CreateDirectory(Path.Combine(directoryPath, "app_data"));
            Directory.CreateDirectory(Path.Combine(directoryPath, "logs"));

            // Update web.config settings using a configuration service.
            _configurationService.UpdateWebConfig(webConfigFile);
        }
        catch (UnauthorizedAccessException ex)
        {
            _logger.LogError(ex, $"Permission denied while trying to access or create directories for {siteName}.");
        }
        catch (IOException ex)
        {
            _logger.LogError(ex, $"IO error occurred while trying to access or create directories for {siteName}.");
        }

        // TODO: Code to start the website goes here.
    }
}
```

