['Here's a basic implementation in C using the cJSON library for JSON processing and regex matching for refresh_token field:

```C
#include <stdbool.h>
#include "cJSON.h"
#include <regex.h>

// Function to check if a string is alphanumeric using regex
bool isAlphaNumeric(char* str) {
    regex_t regex;
    int reti = regcomp(&regex, "^[a-zA-Z0-9]+$", REG_EXTENDED);
    if (reti) return false;  // Could not compile the regular expression

    reti = regexec(&regex, str, 0, NULL, 0);
    regfree(&regex);
    return !reti;  // If it's non-zero then the string doesn't match
}

bool checkTokenResponse(const char* jsonString) {
    cJSON *json = cJSON_Parse(jsonString);
    if (json == NULL) {
        printf("Malformed JSON\n");
        return false;
    }

    cJSON *access_token = cJSON_GetObjectItemCaseSensitive(json, "access_token");
    cJSON *expires_in = cJSON_GetObjectItemCaseSensitive(json, "expires_in");
    cJSON *token_type = cJSON_GetObjectItemCaseSensitive(json, "token_type");

    if (!(access_token && expires_in && token_type 
          && cJSON_IsString(access_token) 
          && (cJSON_IsNumber(expires_in) && cJSON_GetNumberValue(expires_in) >= 0))) {
        printf("Required fields missing or have invalid values\n");
        cJSON_Delete(json);
        return false;
    }

    if (strcmp(cJSON_GetStringValue(token_type), "Bearer") != 0){
        printf("Token type is not 'Bearer'\n");
        cJSON_Delete(json);
        return false;
    }

    // Check refresh token only if it exists
    cJSON *refresh_token = cJSON_GetObjectItemCaseSensitive(json, "refresh_token");
    if (refresh_token && (!cJSON_IsString(refresh_token) || !isAlphaNumeric(cJSON_GetStringValue(refresh_token)))){
        printf("Refresh token is not alphanumeric\n");
        cJSON_Delete(json);
        return false;
    }

    cJSON_Delete(json);
    return true;  // All checks passed, the token response is valid
}
```
Please ensure you have installed and included the necessary header files for cJSON library and regex.h. For a large JSON string, this implementation can be optimized by using an iterative approach instead of recursive one. But it requires more complex code to handle nested objects or arrays as well. Also consider improving error handling mechanism depending on use-case.
