import java.io.*;

public void convertVideoToGIF(String videoFileName, int targetFrameRate, String outputFileName, long maxFileSize) {
    try {
        ProcessBuilder processBuilder = new ProcessBuilder("ffmpeg", "-i", videoFileName, 
            "-r", Integer.toString(targetFrameRate), 
            "-vf", "scale=" + (int)(Math.sqrt(maxFileSize / targetFrameRate) * 0.75), // scale the video to approximately match max file size
            outputFileName);
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.err.println(line); // print the output of ffmpeg to the console
