['```rust
use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use crossbeam_channel::unbounded;
use std::sync::Arc;
use std::thread;
use std::process;
use std::time::Duration;

// Global settings file simulation
struct Settings {
    env_var: String,
}

impl Settings {
    fn new() -> Self {
        Settings {
            env_var: "DEFAULT".to_string(),
        }
    }
}

static SETTINGS: Arc<Settings> = Arc::new(Settings::new());

struct CleanupManager {
    channel: unbounded::Sender<PathBuf>,
    cleanups: Vec<thread::JoinHandle<()>>,
}

impl CleanupManager {
    fn new() -> Self {
        let (sx, rx) = unbounded();
        let manager = Self {
            channel: sx,
            cleanups: vec![],
        };

        manager.cleanups.push(thread::spawn(move || manager.run_cleanup_processes(rx)));
        manager
    }

    fn run_cleanup_processes(&mut self, rx: unbounded::Receiver<PathBuf>) {
        for dir in rx {
            match dir {
                Err(_e) => (), // log error?
                Ok(dir) => {
                    if let Ok(_entry) = fs::remove_dir_all(&dir) {
                        env::set_var("DIR", "").unwrap(); // Reset environment variable to its previous value
                    } else {
                        println_error(&format_err(&e)); 
                    }
                },
            }
        }
    }

    fn add_cleanup(&mut self, path: PathBuf) {
        if let Err(e) = self.channel.send(path) {
            println_error(&format_err(&e)); // log error?
        }
    }
}

static CLEANUP_MANAGER: Arc<CleanupManager> = Arc::new(CleanupManager::new());

fn manage_directory(dir: &PathBuf, env_var: Option<String>) {
    let dir_str = dir.to_string_lossy();

    match fs::metadata(&dir_str) {
        Err(_e) => {  // log error?
            if let Ok(_entry) = fs::create_dir(dir) {
                env::set_var("DIR", &dir_str).unwrap(); 
                CLEANUP_MANAGER.add_cleanup(dir.clone()); 
            } else {
                println_error(&format_err(&e)); // log error?
            }
        },
        Ok(_meta) => (), // Directory already exists, do nothing
    }
}
```
