typedef struct memoryManager {
    long* offsets;
    Record** records;
    pthread_mutex_t lock;
    size_t numRecords;
    size_t maxRecords;
} MemoryManager;

void initMemoryManager(MemoryManager *mm, size_t maxRecords) {
    mm->offsets = (long*) calloc(maxRecords, sizeof(long));
    mm->records = (Record**) calloc(maxRecords, sizeof(Record*));
    pthread_mutex_init(&mm->lock, NULL);
    mm->numRecords = 0;
    mm->maxRecords = maxRecords;
}

void destroyMemoryManager(MemoryManager *mm) {
    for (size_t i = 0; i < mm->numRecords; ++i) {
        free(mm->records[i]);
    }
    free(mm->offsets);
    free(mm->records);
    pthread_mutex_destroy(&mm->lock);
}

Record* allocateAndInitRecord(MemoryManager *mm, int key) {
    if (mm->numRecords >= mm->maxRecords) return NULL;

    Record* newRecord = (Record*) malloc(sizeof(Record));
    newRecord->value = 0; // replace with your initialization logic

    pthread_mutex_lock(&mm->lock);
    mm->offsets[mm->numRecords] = key;
    mm->records[mm->numRecords] = newRecord;
    mm->numRecords++;
    pthread_mutex_unlock(&mm->lock);

    return newRecord;
}
