typedef struct {
    EVP_CIPHER_CTX *ctx;
} CipherContext;

// Function to initialize cipher with password and salt
CipherContext* init_cipher(const char *password, const unsigned char *salt, const char *mode) {
    if (!password || !salt) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        return NULL;
    }

    CipherContext* cipherCtx = malloc(sizeof(CipherContext));
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    if (!ctx) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        free(cipherCtx);
        return NULL;
    }

    cipherCtx->ctx = ctx;

    const EVP_CIPHER *cipher = EVP_get_cipherbyname(mode);
    if (!cipher) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    unsigned char key[32];
    unsigned char iv[16];

    if (!PKCS5_PBKDF2_HMAC((const char *)password, -1, salt, 16, 10000, EVP_sha256(), 32, key) &&
        !PKCS5_PBKDF2_HMAC((const char *)password, -1, salt, 16, 10000, EVP_sha1(), 32, key)) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    int keyLen = EVP_CIPHER_CTX_set_key_length(ctx, sizeof(key));
    if (keyLen != 1) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    int ivLen = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, sizeof(iv), NULL);
    if (ivLen != 1) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    int init = EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
    if (init != 1) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        cleanup_cipher(cipherCtx);
        return NULL;
    }

    EVP_CIPHER_CTX_set_padding(ctx, 1);

    return cipherCtx;
}

// Function to disable and free the cipher context
void cleanup_cipher(CipherContext* cipher) {
    if (!cipher || !cipher->ctx) {
        ERR_error_string(ERR_get_error(), NULL); // Handle error appropriately
        return;
    }

    EVP_CIPHER_CTX *ctx = cipher->ctx;
    EVP_CIPHER_CTX_cleanup(ctx);
    free(cipher);
}
```

