        return -1;
    }

    // Read integers from standard input
    for (int i = 0; i < maxNum; ++i) {
        int num;
        scanf("%d", &num);

        // Skip invalid numbers and log a warning message instead of exiting
        if (num > INT32_MAX || num < INT32_MIN) {
            logMessage("Invalid number detected. Ignoring.");
            continue;
