#include <openssl/ssl.h>
#include <openssl/err.h>

typedef struct {
    SSL_CTX *ctx;
    BIO *rbio;
} tls_context;

tls_context* configure_tls(char *cert_path, char *chain_path, 
                           char *ca_path, char *private_key_file, 
                           char *passphrase, int mode, 
                           char *cipher_suites[], 
                           void (*error_handler)(int err)) {
    SSL_CTX *ctx;
    BIO *rbio = NULL;

    // Initialize the OpenSSL library
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    ctx = SSL_CTX_new(mode == SSL_SERVER ? TLS_server_method() : 
                                         (mode == SSL_CLIENT ? TLS_client_method():
                                          TLS_method()));

    // Load the private key and certificate chain
    if (!SSL_CTX_use_PrivateKey_file(ctx, private_key_file, SSL_FILETYPE_PEM)) {
        error_handler(ERR_get_error());
        goto error;
    }

    // Load the certificate and CA certificates
    if (!SSL_CTX_use_certificate_chain_file(ctx, chain_path) ||
        !SSL_CTX_load_verify_locations(ctx, ca_path, NULL)) {
        error_handler(ERR_get_error());
        goto error;
    }

    // Set the cipher suite list
    if (SSL_CTX_set_ciphersuites(ctx, cipher_suites) != 1) {
        error_handler(ERR_get_error());
        goto error;
    }

    rbio = BIO_new_socket(0, BIO_NOCLOSE);
    SSL_CTX_set_info_callback(ctx, error_handler);

    tls_context *tls = malloc(sizeof(tls_context));
    if (tls == NULL) {
        goto error;
    }
    tls->ctx = ctx;
    tls->rbio = rbio;

    return tls;

error:
    SSL_CTX_free(ctx);
    BIO_free(rbio);

    return NULL;
}

void close_tls(tls_context *tls) {
    if (tls == NULL) {
        return;
    }

    SSL_CTX_free(tls->ctx);
    BIO_free(tls->rbio);

    free(tls);
}
```
