int LoadResourceBundle(const char *path, int **numItems) {
    FILE *fp = fopen(path, "rb"); // Open the file in binary mode
    if (fp == NULL) {
        perror("Failed to open file");
        return -1; // Return appropriate error code for file opening failure
    }

    pthread_mutex_lock(&mutex); // Lock mutex before entering critical section

    int count = 0;
    while (!feof(fp)) {
        ItemHeader header;
        if (fread(&header, sizeof(ItemHeader), 1, fp) != 1) {
            break;
        }

        // Handle different data types based on the type in the header
        DataType data;
        switch (header.type) {
            case /* Integer */:
                if (fread(&data.integer, sizeof(int), 1, fp) != 1) break;
                break;
            case /* String */:
                if (fread(&data.string, sizeof(char), 256, fp) != 256) break;
                break;
        }
        ++count;
    }

    pthread_mutex_unlock(&mutex); // Unlock mutex after exiting critical section

    if (ferror(fp)) {
        perror("File reading error");
        fclose(fp);
        return -1; // Return appropriate error code for file reading failure
    }

    *numItems = malloc(sizeof(int));
    **numItems = count;

    fclose(fp);
    return 0; // Return successful completion status
}
