```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

void renameFiles(char* dirPath, char** filenames) {
    struct stat st = {0};
    if (stat(dirPath, &st) == -1) mkdir(dirPath, 0700); // Create directory if it does not exist

    time_t t = time(NULL);
    struct tm* currentTime = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", currentTime);

    for (int i = 0; filenames[i] != NULL; ++i) {
        if (strlen(filenames[i]) > 100) continue; // Skip filenames that exceed 100 characters

        char newFilename[256];
        sprintf(newFilename, "%s/%s", dirPath, filenames[i]);
        struct stat stFile = {0};
        if (stat(newFilename, &stFile) != -1 && S_ISREG(stFile.st_mode)) {
            char tag[5];
            if (isalpha(filenames[i][0])) sprintf(tag, "_%.*s", 3, filenames[i] + strlen(filenames[i]) - 3);
            else if (isdigit(filenames[i][0])) sprintf(tag, "_%ldKB", stFile.st_size / 1024);
            else {
                char dateTag[9];
                strftime(dateTag, sizeof(dateTag), "%Y%m%d", currentTime);
                sprintf(tag, "_%s", dateTag);
            }

            if (strlen(filenames[i]) + strlen(timestamp) + strlen(tag) <= 256) {
                char fullTag[30];
                sprintf(fullTag, "%s_%lu", timestamp, time(NULL)); // Add unique identifier within the same millisecond

                strcat(filenames[i], tag);
                strcat(filenames[i], fullTag);
                char renamedFilename[256];
                sprintf(renamedFilename, "%s/%s", dirPath, filenames[i]);

                if (rename(newFilename, renamedFilename) != -1) printf("File '%s' successfully renamed to '%s'\n", filenames[i], fullTag);
            } else {
                printf("New filename exceeds 255 characters limit.\n");
            }
        }
    }
}
```
This function first checks if the directory exists and creates it if it doesn't. Then, for each file in `filenames` array, it generates a new name based on the conditions specified: appending timestamp-based identifier, metadata tag (either last three characters of filename, size in kilobytes or current date), unique identifier within the same millisecond and checks if the resulting filenames exceed 255 characters. If they do not, it renames the file using `rename` function from sys/stat library.
