```javascript
const { exec } = require('child_process');
const fetch = require('node-fetch'); // Assuming you're using 'node-fetch', but can be replaced with other http clients like axios

// Mock graph database API, replace with actual library/API calls
class GraphDB {
  constructor() { /* ... */ }
  addVertex(props) { /* ... */ return Promise.resolve({ vertex: props }); }
  addEdge(vertexA, vertexB, props) { /* ... */ return Promise.resolve({ edge: { from: vertexA, to: vertexB, props } }); }
}

class GraphController {
  constructor() {
    this.db = new GraphDB();
  }

  async addVertices(vertices) {
    const results = await Promise.allSettled(vertices.map((props) => this.db.addVertex(props)));
    return results;
  }

  async addEdges(edges) {
    const results = await Promise.allSettled(edges.map(({ from, to, props }) => this.db.addEdge(from, to, props)));
    return results;
  }

  fetchMetadata(url) {
    // Returns a promise that resolves with the metadata fetched from external API
    return fetch(url).then((response) => response.json());
  }

  executeShellCommand(command, callback) {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        console.warn(error);
      }
      return callback(stdout ? 'success' : 'error', stdout || stderr);
    });
  }

  async runProcesses(commands){
    const promises = commands.map((command) => new Promise((resolve, reject) => {
        this.executeShellCommand(command, (status, message) => {
          if (status === 'success') resolve(message);
          else reject(new Error(message));
        });
      })
    );

    return Promise.allSettled(promises);
  }

  async addGraphData({ vertices, edges, metadataURLs, commands }) {
    const vertexResults = await this.addVertices(vertices);
    const edgeResults = await this.addEdges(edges);

    // Fetch metadata for each URL in parallel
    const metadataPromises = Promise.allSettled(metadataURLs.map((url) => this.fetchMetadata(url)));

    const commandResults = await this.runProcesses(commands);

    return { vertexResults, edgeResults, metadata: (await metadataPromises).map((result) => result.value), commandResults };
  }
}
```

This code uses a Promise to manage the asynchronous operations of adding vertices and edges to the graph database, fetching metadata from an external API, and executing shell commands. It also leverages Promises for handling these operations in parallel, which can improve performance. The GraphController class could then be used in other parts of your application by instantiating a new instance of this class and calling its methods as needed.
