import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

public class FileProcessor {
    public static String processDirectoryContent(String directoryPath, String extension) throws IOException, NoSuchAlgorithmException {
        Path path = Paths.get(directoryPath);
        if (!Files.isDirectory(path)) throw new IllegalArgumentException("Not a directory");

        ArrayList<String> lines = new ArrayList<>();
        int maxLineLength = 0;
        String longestLine = "";
        long totalSize = 0;
        Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (Files.isHidden(file)) return FileVisitResult.CONTINUE;

                totalSize += Files.size(file);
                String filename = file.getFileName().toString();
                if (!filename.endsWith(extension)) return FileVisitResult.CONTINUE;

                try (BufferedReader reader = new BufferedReader(new FileReader(file.toFile()))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        lines.add(line);

                        if (line.length() > maxLineLength) {
                            maxLineLength = line.length();
                            longestLine = line;
                        }

                        if (lines.size() >= 1000) break;
                    }
                } catch (IOException e) {
                    System.err.println("Error reading file: " + file);
                    e.printStackTrace();
                }

                Collections.sort(lines);

                return FileVisitResult.CONTINUE;
            }
        });

        int longestLineIndex = lines.indexOf(longestLine);
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        for (String line : lines) {
            md5.update(line.getBytes());
        }
        byte[] digest = md5.digest();

        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }
        return "Total files processed: " + lines.size() + "\n" +
               "Longest line found: " + longestLine + "\n" +
               "Index of longest line: " + longestLineIndex + "\n" +
               "Total directory size: " + totalSize + "\n" +
               "MD5 hash: " + sb.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(processDirectoryContent("/path/to/directory", ".txt"));
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
```
Please replace `"/path/to/directory"` with your directory path, and also ensure the correct extension you want to process. This code can read up to 1000 lines from each file, sort them lexicographically, find the longest line in all files, find total size of all files and subdirectories excluding hidden files and directories. It handles exceptions for incorrect directory path, reading file error, MD5 hash creation failure etc. This code also uses the Java NIO API for better performance and efficiency when traversing a directory structure.
']

