['Here's a basic implementation of how you might accomplish this task in C#. This is not intended to be a full-fledged solution, but rather a starting point for developing the required functionality.

```CSharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Data;
using MySql.Data.MySqlClient;

public class FileProcessor
{
    private const string DATABASE_CONNECTION = "Server=myServerAddress;Database=myDataBase;Uid=myUsername;Pwd=myPassword;";

    public string ProcessDirectoryContent(string directoryPath, byte[] byteArray)
    {
        List<FileInfo> filesToProcess = new List<FileInfo>();

        try 
        {
            DirectoryInfo di = new DirectoryInfo(directoryPath);

            foreach (var fi in di.EnumerateFiles()) 
            {
                if (!fi.Attributes.HasFlag(FileAttributes.Hidden))
                    filesToProcess.Add(fi);
            }
        } 
        catch (DirectoryNotFoundException ex) 
        {
            Console.WriteLine("Failed to process directory content: " + ex.Message);
            return null;
        }

        int totalFiles = filesToProcess.Count();
        long totalSize = 0;
        string longestLine = "";
        int longestIndex = -1;

        foreach (var file in filesToProcess) 
        {
            using (StreamReader sr = new StreamReader(file.FullName)) 
            {
                string line;
                for (int i = 0; ((line = sr.ReadLine()) != null && i < 1000); ++i) 
                {
                    if (line.Length > longestLine.Length) 
                    {
                        longestLine = line;
                        longestIndex = filesToProcess.IndexOf(file);
                    }
                }
            }

            totalSize += file.Length;
        }

        string summary = $"Total number of files processed: {totalFiles}\nLongest line found: {longestLine}, index within the file: {longestIndex}\nTotal directory size: {totalSize}";
        byte[] bytes = Encoding.UTF8.GetBytes(summary);

        using (MD5 md5Hash = MD5.Create()) 
        {
            string hexadecimalRepresentation = BitConverter.ToString(md5Hash.ComputeHash(bytes)).Replace("-", "").ToLower();
            Console.WriteLine(hexadecimalRepresentation);
        }

        // Send byte array to database server
        using (MySqlConnection connection = new MySqlConnection(DATABASE_CONNECTION)) 
        {
            try 
            {
                connection.Open();

                string sql = $"INSERT INTO myTable(myColumn) VALUES(@byteArray)";

                using (MySqlCommand cmd = new MySqlCommand(sql, connection)) 
                {
                    cmd.Parameters.AddWithValue("@byteArray", byteArray);

                    cmd.ExecuteNonQuery();

                    Console.WriteLine("Data inserted successfully");
                }
            } 
            catch (MySqlException ex) 
            {
                Console.WriteLine($"Failed to execute query: {ex.Message}");
            }
        }

        return summary;
    }
}
```
