['Below is a simple example of how you might create a Java method that calculates SHA-256 hash efficiently, taking advantage of Java's built-in MessageDigest class. This implementation uses NIO to minimize memory usage when handling large files. It also makes use of ExecutorService for concurrency to ensure optimal performance under heavy load conditions.

```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.concurrent.*;

public class HashCalculator {
    private static final int BUFFER_SIZE = 8192; // A commonly used buffer size for I/O operations
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public String calculateSHA256(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");

        try (InputStream is = Files.newInputStream(Paths.get(filePath));
             DigestInputStream dis = new DigestInputStream(is, md)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            while (dis.read(buffer) != -1); // Consume the entire input stream to compute the hash
        }

        return bytesToHexString(md.digest());
    }

    public Future<String> calculateSHA256Async(String filePath) {
        return executorService.submit(() -> {
            try {
                return calculateSHA256(filePath);
            } catch (IOException | NoSuchAlgorithmException e) {
                throw new RuntimeException("Failed to calculate SHA-256 hash", e);
            }
        });
    }

    private String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

