['Here's how you might implement this in C. The complexity is high, so be sure to thoroughly test your code. Also note that it doesn't handle race conditions, which would require a locking mechanism (such as pthread mutex) for the operation on file size variable. 

```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

void process_directory_content(const char *dir_path, const char **allowed_extensions) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_info;
    FILE *file;
    char path[1024];
    int i = 0, j = 0;
    char **lines = NULL;
    long size = 0;
    int line_count = 0;
    time_t start_time, end_time;
    double elapsed_secs;

    if ((dir = opendir(dir_path)) == NULL) {
        printf("Could not open directory %s\n", dir_path);
        return;
    }

    start_time = time(NULL);

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.') continue;  // Skip hidden files and directories

        sprintf(path, "%s/%s", dir_path, entry->d_name);

        if (stat(path, &file_info) == 0) {
            size += file_info.st_size;  // Update directory size

            if (S_ISDIR(file_info.st_mode)) {
                process_directory_content(path, allowed_extensions);  // Recurse into subdirectories
            } else if ((file = fopen(path, "r")) != NULL) {
                char *line = NULL;
                size_t len = 0;
                ssize_t read;

                for (i = 0; i < sizeof(allowed_extensions)/sizeof(char*); ++i){  // Check file extension
                    if (!strcmp(&path[strlen(path) - strlen(allowed_extensions[i])], allowed_extensions[i])){
                        line_count = 0;  // Reset line count for each file

                        while ((read = getline(&line, &len, file)) != -1) {
                            if (++line_count > MAX_LINE || strnlen(line, len) > MAX_CHAR){  
                                printf("Exceeded limits.\n");
                                break;
                             }

                             lines = realloc(lines, line_count * sizeof(char*));  // Dynamic allocation of memory for lines
                             if (lines == NULL){
                                 perror("Memory allocation failed\n");
                                 exit(EXIT_FAILURE);
                             }

                             lines[line_count - 1] = malloc(strlen(line) + 1);   // Allocate memory for line
                             if (lines[line_count - 1] == NULL){
                                 perror("Memory allocation failed\n");
                                 exit(EXIT_FAILURE);
                             }

                             strcpy(lines[line_count - 1], line);   // Copy line content to allocated memory
                        }

                        qsort(lines, line_count, sizeof(char*), compare);  // Sort lines lexicographically
                    }
                }

                fclose(file);
            }
        }
    }

    end_time = time(NULL);
    elapsed_secs = difftime(end_time, start_time);

    printf("Total number of files processed: %d\n", line_count);
    printf("Longest line found: %s\n", lines[0]);
    printf("Total directory size: %ld bytes\n", size);
    printf("Time taken to process each file: %.f ms\n", elapsed_secs*1000/line_count);  // Avg time per file

    for (i = 0; i < line_count; ++i){
        free(lines[i]);  // Free allocated memory
    }

    closedir(dir);
}

// Comparison function for qsort
int compare(const void *a, const void *b) {
    return strcmp(*(char **)a, *(char **)b);
}
```

Please note that this is a basic implementation and might need further refinements to meet your specific requirements. It doesn't handle all edge cases you mentioned like empty directories or files containing only whitespace, and it doesn't use a built-in sorting function for large datasets due to potential performance bottlenecks. You may want to consider implementing a custom sorting algorithm (like quicksort) that performs well for large data sets.
']

