typedef struct {
    char* dir_path;
    int file_count;
    size_t total_size;
    // add other metrics you want to track
} DirectoryMetrics;

void process_directory_content(char* dir_path, const char** allowed_extensions) {
    DIR *dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Could not open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        struct stat sb;
        if (stat(path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
            process_directory_content(path, allowed_extensions); // recursion into subdirectories
        } else if (stat(path, &sb) == 0 && S_ISREG(sb.st_mode)) {
            char *ext = strrchr(entry->d_name, '.');
            if (!allowed_extension || (ext && (strcmp(ext+1, allowed_extensions[0]) == 0))) { // check extension
                process_file(path); // non recursive file processing function
            }
        } else {
            perror("Could not get stat");
        }
    }

    closedir(dir);
}
```
