ProcessorNode* processors = NULL; // The head of our processor linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutual exclusion lock for thread safety

// Function to register a log processor with a given priority
void registerProcessor(LogProcessor processor, int priority) {
    pthread_mutex_lock(&lock);

    ProcessorNode* newNode = malloc(sizeof(ProcessorNode));
    newNode->processor = processor;
    newNode->priority = priority;
    newNode->next = processors; // Add to the front of the list for simplicity
    processors = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to log a message with a given level
void logMessage(int level, char* message) {
    LogEntry entry = {level, message};

    int index = atomic_fetch_add(&currentLogIndex, 1) % maxLogEntries; // Use an atomic operation for thread safety
