#include <unistd.h>

#define MAX_LOG_ENTRIES 1024
#define MAX_MSG_LENGTH 512

typedef struct {
    time_t timestamp;
    int logLevel;
    char message[MAX_MSG_LENGTH];
    char sourceFilePath[FILENAME_MAX];
    int lineNumber;
} LogEntry;

LogEntry* logQueue[MAX_LOG_ENTRIES];
int front = 0, rear = -1, itemCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef void (*logHandler)(LogEntry *entry);
logHandler customFormattingFunctions[5];

void enqueue(LogEntry* entry) {
    pthread_mutex_lock(&mutex);
    if (itemCount == MAX_LOG_ENTRIES) {
        printf("Overflow detected, unable to log.\n");
        return;
    }
    if (rear == MAX_LOG_ENTRIES - 1)
        rear = -1;
    logQueue[++rear] = entry;
    itemCount++;
    pthread_mutex_unlock(&mutex);
}

LogEntry* dequeue() {
    LogEntry* entry = NULL;
    pthread_mutex_lock(&mutex);
    if (itemCount > 0) {
        entry = logQueue[front++];
        if(front == MAX_LOG_ENTRIES)
            front = 0;
        itemCount--;
    }
    pthread_mutex_unlock(&mutex);
    return entry;
} 

void addLogEntry(int level, const char* message, const char* sourceFilePath, int lineNumber) {
    if (level < 0 || level > 4) {
        printf("Invalid log level.\n");
        return;
    }
    LogEntry* entry = (LogEntry*) malloc(sizeof(LogEntry));
    time(&entry->timestamp);
    entry->logLevel = level;
    strncpy(entry->message, message, MAX_MSG_LENGTH - 1);
    strncpy(entry->sourceFilePath, sourceFilePath, FILENAME_MAX - 1);
    entry->lineNumber = lineNumber;
    enqueue(entry);
}

void* logHandlerThread(void* arg) {
    while (1) {
        LogEntry* entry = dequeue();
        if (entry != NULL) {
            customFormattingFunctions[entry->logLevel](entry);
            free(entry);
        }
    }
    return NULL;
}

void registerLogHandler(int level, logHandler handler) {
    if (level < 0 || level > 4) {
        printf("Invalid log level.\n");
        return;
    }
    customFormattingFunctions[level] = handler;
}
