    pthread_mutex_t lock;

    // Read integers into array
    for(int i = 0; i < max_ints; i++) {
        int num;

        // Get seeds from external data source, if available
        int seed = config.externalDataSource ? *(int*)config.externalDataSource : 0;
        numbers[i] = seed + rand();

        // Check for invalid seed values
        if (numbers[i] < INT32_MIN || numbers[i] > INT32_MAX) {
            printf("Invalid seed value detected. Ignoring...\n");
            i--;  // Redo this iteration
            continue;
        }

        // If strict validation is enabled, check for duplicates
        if (strictValidation && i > 0) {
            for(int j = 0; j < i; j++) {
                if (numbers[j] == numbers[i]) {
                    printf("Duplicate integer detected. Ignoring...\n");
                    i--;  // Redo this iteration
                    break;
                }
            }
        }
    }

    // If array contains fewer than five integers, log a warning message to a file with a timestamp instead of performing the processing operation
    if (max_ints < 5) {
