typedef void (*AlertHandler)(Metric m);

struct Node {
    Metric metric;
    AlertHandler handler;
    struct Node *next;
};

pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queueConditional = PTHREAD_COND_INITIALIZER;
struct Node *head = NULL, *tail = NULL; // Queue for metrics to monitor

void enqueue(Metric m, AlertHandler handler) {
    pthread_mutex_lock(&queueMutex);
    struct Node* tempNode = (struct Node*)malloc(sizeof(struct Node));
    tempNode->metric = m;
    tempNode->handler = handler;
    tempNode->next = NULL;
    if (tail == NULL) {
        head = tail = tempNode;
    } else {
        tail->next = tempNode;
        tail = tempNode;
    }
    pthread_cond_signal(&queueConditional);
    pthread_mutex_unlock(&queueMutex);
}

struct Node* dequeue() {
    struct Node *tempHead;
    pthread_mutex_lock(&queueMutex);
    while (head == NULL) { 
        pthread_cond_wait(&queueConditional, &queueMutex);
    }
    tempHead = head;
    head = head->next;
    if (head == NULL) tail = NULL;
    pthread_mutex_unlock(&queueMutex);
    return tempHead;
}

void* monitor(void* arg) {
    while(1) {  // Infinite monitoring loop
        struct Node *n = dequeue();
        float value = 0.0f; // This should be replaced with a function to get the metric value
        if (value > n->metric.threshold) {
