#include <atomic>
#include <vector>
#include <condition_variable>
// other necessary includes

class ProfileManager {
private:
    struct UserProfile {
        int id;
        std::string name, email;
        // more profile data here...
    };

    const size_t maxSize; 
    std::unordered_map<int, UserProfile> profiles;  // Concurrent hash map for storing profiles
    std::atomic<size_t> size{0};   // Atomic counter to manage the number of profiles.
    mutable std::mutex mtx;  // A mutex for ensuring thread safety

public:
    ProfileManager(const size_t maxSize) : maxSize(maxSize){}
    ~ProfileManager() { /* clean up any resources here */ }

    void addProfile(UserProfile profile) {
        std::lock_guard<std::mutex> lock(mtx);
        if (size >= maxSize) throw std::runtime_error("Maximum size reached");
        ++size;
        profiles.insert({profile.id, profile});  // add the profile to the map
    }

    void updateProfile(int id, UserProfile newProfile) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = profiles.find(id);
        if (it != profiles.end()) it->second = newProfile;  // Update the profile in place
    }

    UserProfile getProfile(int id) const {
        std::lock_guard<std::mutex> lock(mtx);  // Lock the mutex before accessing data
        auto it = profiles.find(id);
        if (it != profiles.end()) return it->second;   // Return a copy of the profile
    }

    std::vector<UserProfile> getAllProfiles() const {
        std::lock_guard<std::mutex> lock(mtx); 
        std::vector<UserProfile> allProfiles;
        for (const auto& [id, profile] : profiles) {
            allProfiles.push_back(profile);   // Copy each profile into the vector
        }
        return allProfiles;  // Return a copy of the vector
    }
};
