int validate_json(const char* json, const char* schema) {
    struct json_object *jobj = json_tokener_parse(json), *tmp;

    // Parse the schema JSON string to a JSON object
    tmp = json_tokener_parse(schema);
    if (is_error(tmp))
        return 0;

