        // Check if the field exists in the JSON object
        if (!json_object_object_get_ex(jobj, json_object_get_string(field), &tmp)) 
            return 0;

        // Validate that the value is of the correct type for this field
        if (strcmp(json_object_get_type(tmp) != json_object_get_type(field))) 
            return 0;

        // Check special conditions for some fields, e.g., user_id, username, email, address...
    }

    json_object_put(jobj);
    json_object_put(tmp);

    return 1;
}

