from concurrent.futures import ThreadPoolExecutor, wait
from functools import lru_cache

class CacheSystem:
    def __init__(self, api):
        self._api = api
        self._cache = {}
        self._metadata = {}
        self._executor = ThreadPoolExecutor(max_workers=5)

    @lru_cache()
    def _fetch_from_api(self, key):
        # Here we use requests.get for simplicity, replace with your API request
        response = requests.get(f'{self._api}/metadata?key={key}')
        return response.json()

    @lru_cache()
    def get(self, key):
        self._executor.submit(self._invalidate)  # Start invalidation task in the background
        if key not in self._cache:
            try:
                value = self._fetch_from_api(key)
                self._metadata[key] = value['metadata']
                self._cache[key] = {'value': value, 'expiration': time.time() + value['expires_in']}
                return f'Added {key} to cache', 201
            except Exception as e:
                return str(e), 500
        else:
            return self._cache[key]['value'], 200

    def set(self, key, value, expires_in):
        self._cache[key] = {'value': value, 'expiration': time.time() + expires_in}
        return f'Added {key} to cache', 201

    def delete(self, key):
        if key in self._cache:
            del self._cache[key]
            return f'Deleted {key} from cache', 204
        else:
            return 'Key not found in cache', 404

    def _invalidate(self):
        for key, value in list(self._cache.items()):
            if time.time() > value['expiration']:
                del self._cache[key]
                print(f'Invalidated {key} from cache')  # Replace with your logger
```
This is a simplified version of a caching system and does not support distributed data consistency or fault tolerance across multiple nodes. Implementing these features would require additional complexity, such as implementing consensus algorithms for ensuring the state of all nodes matches, and handling network partitions and other failures. 

To run this code, replace `'{self._api}/metadata?key={key}'` with your actual API endpoint for fetching metadata and `requests.get` with your own API request method.
