                // Checking image dimension limits
                if (image.Width > 4096 || image.Height > 4096) continue;

                images.Add(new ImageMetadata{ Width=image.Width, Height=image.Height, Size = info.Length });
            }
        }

        // Calculating average width and height
        int totalWidth = 0, totalHeight = 0;
        long totalSize = 0;

        foreach (var image in images)
        {
            totalWidth += image.Width;
            totalHeight += image.Height;
            totalSize += image.Size;
        }

        int averageWidth = totalWidth / images.Count;
        int averageHeight = totalHeight / images.Count;

        // Finding image with highest resolution
        var largestImage = images.OrderByDescending(i => i.Width * i.Height).First();

        // Creating summary report
