#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <resolv.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Define DNS resolution function structure
typedef struct {
    char* hostname;
    u_char ip[INET6_ADDRSTRLEN];
} ResolutionRequest;

sem_t semaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int concurrentQueries = 0;

u_char* resolveDNS(ResolutionRequest *request) {
    // Initialize resources and configuration settings
    struct __res_state res;
    if (res_ninit(&res) < 0) {
        // handle error
    }

    // Query DNS for IP address using a blocking function call to prevent concurrency issues.
    int queryResult = res_query(request->hostname, C_INET, T_A, request->ip, sizeof(request->ip));
    if (queryResult < 0) {
        // handle error
    }

    // Return IP address
    return request->ip;
}

void* threadFunction(void *arg) {
    ResolutionRequest *req = (ResolutionRequest*) arg;

    pthread_mutex_lock(&mutex);
    if(concurrentQueries >= MAX_CONCURRENT_QUERIES){
        sem_wait(&semaphore);
    }
    ++concurrentQueries;
    pthread_mutex_unlock(&mutex);

    // Perform DNS resolution
    u_char* ip = resolveDNS(req);

    pthread_mutex_lock(&mutex);
    --concurrentQueries;
    if (concurrentQueries < MAX_CONCURRENT_QUERIES) {
        sem_post(&semaphore);
    }
    pthread_mutex_unlock(&mutex);

    return ip;
}
```
