void conditional_log(FILE *fp, int enableLogging, char *conditionMsg, ...) {
    if (totalLoggedData >= maxTotalLoggedData) return; // Check if the total logged data limit has been reached.

    char buffer[MAX_LOG_MSG_LEN]; 
    va_list args;
    va_start(args, conditionMsg);

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(buffer, MAX_LOG_MSG_LEN, "%Y-%m-%d %H:%M:%S", timeinfo); // Add the timestamp to buffer.

    int len = strlen(buffer); 
    snprintf(&buffer[len], MAX_LOG_MSG_LEN - len, " Condition: %s ", conditionMsg);
    len += strlen(" Condition: ") + strlen(conditionMsg);

    vsnprintf(&buffer[len], MAX_LOG_MSG_LEN - len, conditionMsg, args); // Format the message into buffer.
    va_end(args);

    if (enableLogging) {
        int retries = 0;
        while (retries < RETRY_COUNT) { // Retry mechanism for writing to log file.
            if (fwrite(buffer, sizeof(char), strlen(buffer), fp) != strlen(buffer)) {
                sleep(1); // Wait before retrying.
                retries++;
            } else break;
        }
    }

    totalLoggedData += strlen(buffer); // Update the total logged data count.
}
