['```python
import subprocess
import hashlib
import logging
import os
import sys

logging.basicConfig(level=logging.INFO)

def idempotent_file_modification(cmd):
    try:
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        output, error = process.communicate()
        if process.returncode != 0:
            logging.error("Command execution failed with the following error: " + str(error))
            sys.exit(-1)
    except Exception as e:
        logging.error("An unexpected error occurred: " + str(e))
        sys.exit(-2)

def replace_template_variables(config, file):
    for var in config:
        cmd = f'sed -i \'s|{var}|{config[var]}|g\' {file}'
        idempotent_file_modification(cmd)

def append_firewall_rule(rule, checksum, file):
    with open(file, 'a') as f:
        if hashlib.sha256(rule.encode('utf-8')).hexdigest() != checksum:
            logging.error("Checksum mismatch for the firewall rule. Not appending.")
            sys.exit(-3)
        else:
            f.write("\n" + rule)

def main():
    config_file = '/path/to/network/interface'
    template_variables = { '__VAR1__': 'replacement1', '__VAR2__': 'replacement2'}
    firewall_rule = '-A INPUT -p tcp --dport 80 -j ACCEPT'

    replace_template_variables(template_variables, config_file)

    checksum = hashlib.sha256(firewall_rule.encode('utf-8')).hexdigest()

    append_firewall_rule(firewall_rule, checksum, config_file)

if __name__ == "__main__":
    main()
```
