// A simple node type to hold parsed paths
#[derive(Debug)]
enum Node {
    Path(String),
    // More types can be added for other language constructs
}

// The lexer and parser
struct Parser {
    regex: Regex,
}
impl Parser {
    fn new() -> Self {
        let re = Regex::new(r"[a-zA-Z0-9\/\.\~]+").unwrap();
        Self { regex: re }
    }

    fn parse(&self, input: &str) -> Result<Vec<Node>, IoError> {
        let matches = self.regex.find_iter(input);
        let mut nodes: Vec<Node> = vec![];

        for mat in matches {
            nodes.push(Node::Path(mat.as_str().to_string()));
        }

        Ok(nodes)
    }
}

// The cache type that holds a parsed version of the file and a timestamp
#[derive(Debug)]
struct CacheEntry {
    nodes: Vec<Node>,
    time: Instant,
}
type Cache = Arc<Mutex<HashMap<String, CacheEntry>>>;

fn parse_file(cache: &Cache, size_limit: usize, parser: &Parser, path: String) -> Result<Vec<Node>, IoError> {
    // Check if the file is already in cache and not too old
    let mut entry = match cache.lock().unwrap().get(&path) {
        Some(entry) if entry.time.elapsed().as_secs() < 60 => return Ok(entry.nodes),
        _ => None,
    };

    // If the file is not in cache or too old, read and parse it
    let content = read_to_string(&path)?;
    if content.len() > size_limit {
        let nodes = parser.parse(&content)?;
        entry = Some(CacheEntry {
            nodes: nodes.clone(),
            time: Instant::now(),
        });

        // Update the cache
        *cache.lock().unwrap() = HashMap::from([(path, entry.unwrap())]);
    } else {
        return Ok(vec![Node::Path(content)]);
    }

