["Here's a simple implementation of your request using Mersenne Twister in C++11. This is just an example and it doesn't include the cryptographic hash function integration. 

```cpp
#include <random>
#include <mutex>

namespace RandomUtilities {

    class MTGenerator {
        private:
            // The Mersenne Twister PRNG engine
            std::mt19937 mt;

            // Mutex for thread-safety
            std::mutex mtx;

            // Singleton instance
            static MTGenerator* instance_;

        public:
            // Constructor that accepts a seed value 
            MTGenerator(unsigned int seed) : mt(seed) {}

            // Destructor to clean up if needed
            ~MTGenerator() { delete instance_; }

            // Singleton access method
            static MTGenerator* instance() {
                if (!instance_) {
                    std::lock_guard<std::mutex> lock(mtx);  // Lock mutex to prevent race condition
                    if (!instance_) {  
                        instance_ = new MTGenerator();
                    }
                }
                return instance_;
            }

            // Method for generating random integers within specified ranges
            int nextInt(int low, int high) {
                std::lock_guard<std::mutex> lock(mtx);  // Lock mutex to prevent race condition
                std::uniform_int_distribution<> distr(low, high);
                return distr(mt);
            }

            // Method for generating random doubles within specified ranges
            double nextDouble(double low, double high) {
                std::lock_guard<std::mutex> lock(mtx);  // Lock mutex to prevent race condition
                std::uniform_real_distribution<> distr(low, high);
                return distr(mt);
            }
    };
}
```

This is a simplified example and does not include the cryptographic hash function integration. However, integrating it with an external library will require more complex design considerations. Please check the specific library's documentation for integration details. 

