```csharp
using System;
using System.Data.Entity;
using System.Data.SqlClient;
using Polly;
using Serilog;

public class DatabaseContext : DbContext
{
    // Define your entities here, e.g.: public DbSet<User> Users { get; set; }
}

public interface IDatabaseService
{
    Task ExecuteSqlCommandAsync(FormattableString command);
}

public class DatabaseService : IDatabaseService
{
    private readonly ILogger _logger = Log.Logger.ForContext<DatabaseService>();
    private readonly DbContext _context;

    public DatabaseService(DbContext context)
    {
        _context = context ?? throw new ArgumentNullException(nameof(context));
    }

    public async Task ExecuteSqlCommandAsync(FormattableString command)
    {
        if (command == null) 
            throw new ArgumentNullException(nameof(command));

        var policy = Policy
            .Handle<SqlException>()
            .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));

        try
        {
            await policy.ExecuteAsync(async () => 
            {
                using (var transaction = _context.Database.BeginTransaction())
                {
                    var result = await _context.Database.ExecuteSqlCommandAsync(command.Format, command.GetArguments());

                    // If result is greater than zero, commit the transaction else rollback
                    if (result > 0) 
                        transaction.Commit();
                    else 
                        transaction.Rollback();
                }
            });

            _logger.Information("Executed SQL command successfully: {Command}", command);
        }
        catch(Exception e)
        {
            _logger.Error(e, "Failed to execute SQL command: {Command}", command);
            throw;
        }
    }
}
```
