using System;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.RateLimiting;

[ApiController]
public class UpdateElementController : ControllerBase {
    private readonly ApplicationDbContext _dbContext;
    private readonly HtmlSanitizer _htmlSanitizer;
    private readonly ILogger<UpdateElementController> _logger;

    public UpdateElementController(ApplicationDbContext dbContext, 
                                    HtmlSanitizer htmlSanitizer, 
                                    ILogger<UpdateElementController> logger) {
        _dbContext = dbContext;
        _htmlSanitizer = htmlSanitizer;
        _logger = logger;
    }

    [EnableRateLimiting("fixed")]
    [HttpPost]
    public async Task<IActionResult> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent) {
        try {
            var sanitizedHtmlContent = _htmlSanitizer.Sanitize(htmlContent);

            // Assume you have a Element model with a History property representing the historical changes
            var element = await _dbContext.Elements
                .Include(e => e.History)
                .FirstOrDefaultAsync(e => e.Id == elementId && e.PageSectionId == pageSectionId);

            if (element is null) {
                return NotFound("Element not found");
            }

            element.HtmlContent = sanitizedHtmlContent;
            var history = new ElementHistory {
                HtmlContent = htmlContent,  // non-sanitized content for tracking
                UpdatedAt = DateTime.UtcNow
            };

            element.History.Add(history);
            await _dbContext.SaveChangesAsync();
        } catch (Exception ex) {
            _logger.LogError(ex, "An error occurred while updating the element");
            return StatusCode(500, "Internal Server Error");
        }

        return Ok("Element updated successfully");
    }
}
```
