#include <time.h>

#define MAX_SIZE 1024 // Define your own max size

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    float MEASUREMENT_REPORT; // Assuming it's a timestamp and signal strength pair.
} NR_UE_CONTEXT;

// Global variables
NR_UE_CONTEXT *array = NULL;
int size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
time_t ageThreshold; // Define your own age threshold.

void addEntry(NR_UE_CONTEXT entry) {
    pthread_mutex_lock(&mutex);

    if (size == MAX_SIZE) {
        size = MAX_SIZE / 2; // If full, halve the array.
        array = realloc(array, size * sizeof(NR_UE_CONTEXT));

        if (array == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }

    // Add entry to the array.
    array[size] = entry;
    size++;

    pthread_mutex_unlock(&mutex);
}

void pruneOldEntries() {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < size; i++) {
        if (difftime(currentTime, array[i].MEASUREMENT_REPORT.timestamp) > ageThreshold) {
            // Shift all subsequent elements one position back.
            for (int j = i; j < size - 1; j++) {
                array[j] = array[j + 1];
            }

            size--;
            i--; // Stay at the current index after shifting
        }
    }

    pthread_mutex_unlock(&mutex);
}
```
