const neo4j = require('neo4j-driver');
let driver;

class StreamProcessor {
    constructor(databaseUrl, username, password) {
        this.graphDB = neo4j.driver(databaseUrl, neo4j.auth.basic(username, password));
        this.isPaused = false;
        // Other setup like stream source and graph structure
    }

    async processData() {
        let session = driver.session();

        for await (let data of this.streamSource) {
            while(this.isPaused){
              await new Promise((resolve, reject) => setTimeout(resolve, 100)); // Pause execution in event loop until stream resumes
            }

            try{
                let vertex = createVertex(data);
                let edge = createEdge(vertex, data);

                await session.run("CREATE (a:Node $props)", { props: vertex })
                            .then(() => session.run("MATCH (a:Node),(b:Node) CREATE (a)-[r:RELATION]->(b)"), { props: edge });
            } catch(err){
                // Handle errors gracefully, such as retrying or writing to error log file
                console.error('Error processing data', err);
            }
        }
    }

    pauseProcessing() {
       this.isPaused = true;
    }

    resumeProcessing() {
      if(this.isPaused){
         this.processData();  // Resume processing after a pause
      }
    }
}
```

