import org.springframework.stereotype.Service;

@Service
public class LoggingService {
    private static final Logger logger = LogManager.getLogger(LoggingService.class);

    @Value("${log4j.configurationFile}")
    private String logConfigPath;

    public void logEvent(String message, Level level) {
        try {
            if (Level.ERROR.equals(level)) {
                logger.error(message);
            } else if (Level.INFO.equals(level)) {
                logger.info(message);
            } else if (Level.DEBUG.equals(level)) {
                logger.debug(message);
            } // and so on for other log levels...
        } catch (Exception e) {
            handleError("Failed to log event", e);
        }
    }

    public void updateLogConfig() {
        try {
            System.setProperty("log4j.configurationFile", logConfigPath);
        } catch (Exception e) {
            handleError("Failed to update logging configuration", e);
        }
    }

    private void handleError(String message, Exception e) {
        logger.error(message, e);
        // Implement error handling logic here... 
        // This might include sending an alert email or triggering some automated recovery mechanism.
    }
}
