```python
import json
from PIL import ImageFilter, Image
import logging
from threading import Lock

class Filter:
    def __init__(self, name, params):
        self.name = name
        self.params = params

    def apply(self, image):
        if isinstance(image, Image.Image):
            return getattr(ImageFilter, self.name)(*self.params)(image)
        else:
            logging.error("Expected an instance of PIL Image")

class FilterPipeline:
    def __init__(self, filters=None):
        if filters is None or not isinstance(filters, list):
            self.load_default()
        else:
            self.filters = [Filter(*f) for f in filters]

    def load_default(self):
        # predefined default filter config
        self.filters = [Filter('BLUR', None), Filter('CONTOUR', None)]

    def save(self, filename):
        with open(filename, 'w') as f:
            json.dump([f.__dict__ for f in self.filters], f)

    def load(self, filename):
        try:
            with open(filename, 'r') as f:
                filters = json.load(f)
                self.filters = [Filter(*f) for f in filters]
        except FileNotFoundError:
            logging.error("File not found")

    def process_image(self, image):
        lock = Lock()
        with lock:
            if isinstance(image, Image.Image):
                for filter in self.filters:
                    try:
                        start = time.time()
                        logging.info("Applying " + filter.name)
                        image = filter.apply(image)
                        end = time.time()
                        logging.info("Filter " + filter.name + f" applied in {end-start}s")
                    except Exception as e:
                        # Handle errors and revert to original if needed here
                        logging.error(str(e))
                        image = None
            else:
                logging.error("Expected an instance of PIL Image")
        return image
```
