pub async fn monitor(config_path: &str, interval: Duration) -> anyhow::Result<()> {
    let system = System::new_all();
    let sysinfo = match system {
        Ok(sys) => sys,
        Err(_e) => return Err(anyhow::anyhow::<&str>::Error),
    };
    let config: String = fs::read_to_string(&config_path)?;
    let endpoint: &str = serde_json::from_str(&config)?;

    let service = Arc::new(MonitoringService::new(endpoint));
    tokio::spawn(async move {
        loop {
            if let Some(metrics) = Metrics::new(&sysinfo) {
                let mut metrics = service.metrics.write().await;
                metrics.push(metrics);
                service.send_metrics(sysinfo).await.unwrap();
            }
            tokio::time::sleep(interval).await;
        }
    });

    Ok(())
}
```

