public class EmployeeService {
    private static final String DB_URL = "jdbc:mysql://localhost/mydatabase";
    private static final String USERNAME = "username";
    private static final String PASSWORD = "password";

    // A simple cache for frequently accessed supervisor IDs.
    private List<Integer> cachedSupervisors = new ArrayList<>();

    public List<Employee> getEmployeeDetailsWithCache(Integer supervisorId) {
        try {
            if (supervisorId == null) {
                throw new IllegalArgumentException("Supervisor ID cannot be null");
            }

            // If the supervisor is cached, return its details. Otherwise, fetch them from the DB and cache them.
            if (cachedSupervisors.contains(supervisorId)) {
                System.out.println("Returning from cache...");
                // This will need to be implemented based on your actual database schema.
                return getEmployeesBySupervisorFromDB(supervisorId); 
            } else {
                List<Employee> employees = getEmployeesBySupervisorFromDB(supervisorId);

                // Store the supervisor in the cache for future retrieval.
                cachedSupervisors.add(supervisorId);

                return employees;
            }
        } catch (SQLException e) {
            System.out.println("Failed to retrieve employee details: " + e.getMessage());
            return new ArrayList<>();
        }
    }

    private List<Employee> getEmployeesBySupervisorFromDB(int supervisorId) throws SQLException {
        // Use a connection pool for efficient resource management.
        Connection conn = DriverManager.getConnection(DB_URL, USERNAME, PASSWORD);

        String query = "SELECT name, city, address FROM Employees WHERE SupervisorID = ?";

        PreparedStatement stmt = conn.prepareStatement(query);
        stmt.setInt(1, supervisorId);

        ResultSet rs = stmt.executeQuery();

        List<Employee> employees = new ArrayList<>();

        while (rs.next()) {
            Employee employee = new Employee();
            employee.setName(rs.getString("name"));
            employee.setCity(rs.getString("city"));
            employee.setAddress(rs.getString("address"));

            employees.add(employee);
        }

        // Close the database resources.
        rs.close();
        stmt.close();
        conn.close();

        return employees;
    }

    public String calculateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5"); 

            byte[] messageDigest = md.digest(input.getBytes()); 

            BigInteger no = new BigInteger(1, messageDigest); 

            String hashtext = no.toString(16); 
            while (hashtext.length() < 32) { 
                hashtext = "0" + hashtext; 
            } 

            return hashtext; 
        } catch (Exception e) { 
            System.out.println("Failed to calculate MD5 hash: " + e); 
            return null; 
        } 
    }
}
```
This code block assumes you have an `Employee` class with getters and setters for the properties, a `DB_URL` constant representing your database URL, and `USERNAME` and `PASSWORD` constants for your database credentials. You'll need to replace these values with actual details specific to your application.
