        } catch (Exception $e) {
            // Handle authentication error, log failure event with detailed info
            $this->logger->error('Failed to authenticate user', ['reason' => $e->getMessage(), 'ip' => $_SERVER['REMOTE_ADDR'], 'timestamp' => time()]);
        }
    }

    public function getUserProfile($userId) {
        $cachedData = $this->cache->get('profile'.$userId); // Try to fetch user profile from cache first

        if ($cachedData) {
            $this->logger->info('Fetched user profile data from cache', ['ip' => $_SERVER['REMOTE_ADDR'], 'timestamp' => time()]);
            return $cachedData; // Return cached data if available
        } else {
            try {
                // Fetch user profile using the Identity Provider and access token stored in session variable 
                $profile = $this->idp->getUserProfile($userId, $_SESSION['accessToken']);

                // Store profile data in cache for future use
                $this->cache->set('profile'.$userId, $profile); 

                return $profile;
            } catch (Exception $e) {
                // Handle error, log failure event with detailed info
                $this->logger->error('Failed to fetch user profile', ['reason' => $e->getMessage(), 'ip' => $_SERVER['REMOTE_ADDR'], 'timestamp' => time()]);
            }
        }
    }
}
```
