import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;

@Service
public class UserProfileUpdateService {
    private final IdentityService identityService;
    private final MessageQueue messageQueue;
    private final UserDAO userDAO;

    @Autowired
    public UserProfileUpdateService(IdentityService identityService, MessageQueue messageQueue, UserDAO userDAO) {
        this.identityService = identityService;
        this.messageQueue = messageQueue;
        this.userDAO = userDAO;
    }

    @Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(delay = 5000))
    public void updateUserProfile(String userId, UserProfile profile) {
        // Validate using the identity service
        validateUserData(profile);

        // Enqueue the update operation for asynchronous processing
        messageQueue.enqueue(() -> performUpdate(userId, profile));
    }

    private void validateUserData(UserProfile profile) {
        try {
            identityService.validateUserData(profile);
        } catch (Exception e) {
            // Handle exceptions here, possibly retrying or providing a fallback value
            throw new RuntimeException("Error validating user data", e);
        }
    }

    private void performUpdate(String userId, UserProfile profile) {
        try {
            // Perform the actual update in the database (this would be done in an atomic transaction for ACID compliance)
            userDAO.updateUserProfile(userId, profile);

        } catch (Exception e) {
            // Handle exceptions here, possibly retrying or providing a fallback value
            throw new RuntimeException("Error updating user data", e);
        }
    }
}
