#include <atomic>
#include <mutex>
#include <vector>
#include <memory>
#include <stdexcept>

// A single node in the octree. This can be a non-leaf or leaf node.
class OctreeNode {
public:
    // Constructor and destructor for a leaf or non-leaf node respectively. 
    explicit OctreeNode(int capacity) : is_leaf_(true), data_(capacity, nullptr) {}
    explicit OctreeNode() : children_(8, nullptr) {}

    std::vector<std::shared_ptr<OctreeNode>> children_;

private:
    bool is_leaf_;
    std::vector<std::unique_ptr<DataType>> data_;  // DataType needs to be defined.
};

// The main octree class.
class Octree {
public:
    explicit Octree(int capacity) : root_(capacity), size_(0), max_size_(1000), mutex_() {}

    void insert(std::unique_ptr<DataType> data) {  // DataType needs to be defined.
        std::lock_guard<std::mutex> lock(mutex_);

        if (size_.load() == max_size_) {
            throw std::runtime_error("Octree is full.");
        }

        size_++;  // Increment the size.
    }

    void remove() {
        std::lock_guard<std::mutex> lock(mutex_);

        if (size_.load() == 0) {
            throw std::runtime_error("Octree is empty.");
        }

        size_--;  // Decrement the size.
    }

private:
    OctreeNode root_;
    std::atomic<int> size_;
    int max_size_;
    mutable std::mutex mutex_;
};
```
