['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>

typedef struct Transaction {
    int id;
    time_t timestamp;
    double weight;
} Transaction;

static const size_t MAX_TRANSACTIONS = 20000 * 10; // 10 seconds of transactions
static const double WINDOW = 5.0;
static const int HISTORY_SIZE = (int)(WINDOW) + 1;
static const int TTL = (int)(WINDOW);

typedef struct TransactionHistory {
    size_t count;
    Transaction* transactions[HISTORY_SIZE];
} TransactionHistory;

typedef struct TransactionList {
    pthread_mutex_t lock;
    size_t count;
    size_t lastIndex;
    TransactionHistory history[HISTORY_SIZE];
    double weightedSums[10]; // sum of weights in the past 10 seconds, one for each second
} TransactionList;

static inline time_t getTime(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec;
}

Transaction* transactionCreate(int id, double weight) {
    Transaction* tx = malloc(sizeof(*tx));
    if (tx != NULL) {
        tx->id = id;
        tx->weight = weight;
        tx->timestamp = getTime();
    }
    return tx;
}

void transactionDestroy(Transaction* tx) {
    free(tx);
}

TransactionList* transactionListCreate() {
    TransactionList* list = malloc(sizeof(*list));
    if (list != NULL) {
        pthread_mutex_init(&list->lock, NULL);
        for (int i = 0; i < HISTORY_SIZE; ++i)
            list->history[i].count = 0;
        for (int i = 0; i < 10; ++i)
            list->weightedSums[i] = 0.0;
    }
    return list;
}

void transactionListDestroy(TransactionList* list) {
    pthread_mutex_destroy(&list->lock);
    for (size_t i = list->lastIndex + 1, count = 0; count < HISTORY_SIZE; ++count, ++i, i %= HISTORY_SIZE)
        for (int j = 0; j < list->history[i].count; ++j)
            transactionDestroy(list->history[i].transactions[j]);
    free(list);
}

void transactionListReset(TransactionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < HISTORY_SIZE; ++i)
        for (int j = 0; j < list->history[i].count; ++j)
            transactionDestroy(list->history[i].transactions[j]);
    list->lastIndex = HISTORY_SIZE - 1;
    list->count = 0;
    for (int i = 0; i < HISTORY_SIZE; ++i)
        list->history[i].count = 0;
    for (int i = 0; i < 10; ++i)
        list->weightedSums[i] = 0.0;
    pthread_mutex_unlock(&list->lock);
}

Transaction* transactionListPush(TransactionList* list, Transaction* tx) {
    pthread_mutex_lock(&list->lock);
    size_t index = (++list->lastIndex %= HISTORY_SIZE); // circular history buffer
    if (list->count >= MAX_TRANSACTIONS) { // list is full, remove oldest transaction
        --list->count;
        Transaction* oldTx = list->history[index].transactions[0];
        for (int i = 1; i < HISTORY_SIZE; ++i)
            if (list->history[i].count > 0) {
                transactionDestroy(oldTx);
                oldTx = list->history[i].transactions[0];
            } else
                break;
        for (int i = 1; i < HISTORY_SIZE; ++i) // move transactions to the left, keeping oldest at the end
            if (list->history[(index + i) % HISTORY_SIZE].count > 0) {
                list->history[index].transactions[0] = list->history[(index + i) % HISTORY_SIZE].transactions[0];
                --list->history[(index + i) % HISTORY_SIZE].count;
            } else
                break;
    } else { // new transaction fits into list, add space for it
        index = (++list->lastIndex %= HISTORY_SIZE);
        ++list->count;
    }
    time_t now = getTime();
    double* weightedSums = &list->weightedSums[(now - tx->timestamp) % 10]; // sum for current second window only
    TransactionHistory* history = list->history + index;
    *weightedSums += tx->weight;
    ++history->count;
    if (history->count <= HISTORY_SIZE)
        history->transactions[0] = tx; // new transaction fits into window, add it to start of list
    else { // window is full, replace oldest transaction with new one
        Transaction* oldTx = history->transactions[HISTORY_SIZE - 1];
        *weightedSums -= oldTx->weight;
        transactionDestroy(oldTx);
        history->transactions[HISTORY_SIZE - 1] = tx;
    }
    pthread_mutex_unlock(&list->lock);
    return tx; // return the same transaction pointer as input, to indicate success
}

Transaction* transactionListGetMax(const TransactionList* list) {
    pthread_mutex_lock(&list->lock);
    time_t now = getTime();
    double maxWeight = 0.0;
    Transaction* txWithMaxWeight = NULL;
    for (int i = 0; i < 10; ++i) { // check all windows within the last 10 seconds
        size_t index = ((now - i) % HISTORY_SIZE);
        double weightSum = list->weightedSums[index];
        if (weightSum > maxWeight && list->history[index].count > 0) { // check if window is not empty and has higher weight sum
            Transaction* tx = list->history[index].transactions[list->history[index].count - 1];
            if ((now - tx->timestamp) <= TTL && tx->weight > maxWeight) { // check if transaction is in the last 5 seconds and has higher weight than previous highest
                maxWeight = tx->weight;
                txWithMaxWeight = tx;
            }
        }
    }
    pthread_mutex_unlock(&list->lock);
    return txWithMaxWeight; // return the transaction with the maximum weighted sum, or NULL if no such transaction exists
}
```
