#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define BLOCK_SIZE 4096
static unsigned char block[BLOCK_SIZE];
static size_t offset = 0;

void* custom_malloc(size_t size) {
    if (offset + size > BLOCK_SIZE) return NULL;
    void* ptr = &block[offset];
    offset += size;
    return ptr;
}

int secureTrimOrAppendSlash(const char* input, unsigned int limit, char** output) {
    if (input == NULL || output == NULL) return -1;

    size_t length = strlen(input);

    *output = custom_malloc(limit + 2);  // plus one for the slash and one for null terminator
    if (*output == NULL) return -1;

    if (length <= limit) {
        memcpy(*output, input, length);
        (*output)[length] = '/';
        (*output)[length + 1] = '\0';
    } else {
        memcpy(*output, input, limit);
        (*output)[limit] = '\0';
    }

    return 0;
}
```

