function authenticateUserWithOAuth2($provider, $options) {
    // Create a new GenericProvider object with the given options
    $oauth = new GenericProvider($options);

    try {
        if (!isset($_GET['code'])) {
            // If we don't have an authorization code yet, get one
            $authorizationUrl = $oauth->getAuthorizationUrl();
            $_SESSION['oauth2state'] = $oauth->getState();
            header('Location: ' . $authorizationUrl);
            exit;

        } elseif (empty($_GET['state']) || (isset($_SESSION['oauth2state']) && $_GET['state'] !== $_SESSION['oauth2state'])) {
            // Check given state against previously stored one to mitigate CSRF attack
            unset($_SESSION['oauth2state']);
            exit('Invalid state');

        } else {
            // Try to get an access token using the authorization code grant
            $accessToken = $oauth->getAccessToken('authorization_code', [
                'code' => $_GET['code']
            ]);

            // Store the access token in a session variable
            $_SESSION['access_token'] = $accessToken;

            // Use the access token to get user information
            $user = $oauth->getResourceOwner($accessToken);

            return $user->toArray();
        }
    } catch (Exception $e) {
        exit('Caught exception: ' . $e->getMessage());
    }
}
