#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(void) {
    FILE *file = fopen("input.txt", "r");
    char *line = NULL;
    size_t len = 0;

    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while(getline(&line, &len, file) != -1) {
        char *lastField = strrchr(line, ' ');
        if (lastField == NULL) {
            printf("Invalid line format\n");
            continue;
        }
        ++lastField; // Skip the space

        int nums[4], sum = 0;
        for (int i=0; i<4 && lastField != NULL; ++i) {
            if(1==sscanf(lastField, "%d", &nums[i])) {
                sum += nums[i];
            }
            lastField = strchr(lastField, ' '); // Find next space
            ++lastField; // Skip the space
        }

        printf("%.*s,%d\n", (int)(lastField-line-1), line, sum/4);
    }

    free(line);
    fclose(file);
    return 0;
}
```

TIFF Image Parsing:
```C
#include <stdio.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    uint16 bps; // Bits per sample
    uint16 spp; // Samples per pixel
} TIFFInfo;

TIFFInfo parseTiff(const char* filename) {
    TIFFInfo info = {0, 0};

    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Failed to open TIFF file\n");
        return info;
    }

    uint16 bps, spp;
    if (!TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps)) {
        fprintf(stderr, "Failed to read BitsPerSample\n");
        return info;
    }
    info.bps = bps;

    if (!TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &spp)) {
        fprintf(stderr, "Failed to read SamplesPerPixel\n");
        return info;
    }
    info.spp = spp;

    TIFFClose(tif);
    return info;
}
```

