#define MAX_CMDS 100

typedef struct {
    char* cmd;
    int priority;
} Command;

// This is a simple version of the function, it can be improved based on specific needs
int runCommand(const char* command) {
    pid_t pid = fork();

    if (pid == 0) { // child process
        execl("/bin/sh", "sh", "-c", command, (char*) NULL);
        return 0;
    } else if (pid < 0) { // error forking
        perror("fork failed");
        return 0;
    } else { // parent process
        int status = 0;
        wait(&status); // wait for child to complete

        if(WIFEXITED(status)) { // command completed successfully
            printf("%s executed successfully.\n", command);
            return 1;
        } else { // error executing command
            printf("Error executing %s. Exit status: %d\n", command, WEXITSTATUS(status));
            return 0;
        }
    }
}

