                                                       "1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalm|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|" +
                                                       "Haggai|Zechariah|Malachi|Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|" +
                                                       "1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)\b";

    public static Dictionary<string, int> AddWebsiteWithBibleBookCheck(string directoryPath, string siteName)
    {
        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath)) return null;

        var countDictionary = new Dictionary<string, int>();
        var content = File.ReadAllText(siteName); // Assuming site name is the file path of the website's content
        var matches = Regex.Matches(content, BibleBooksPattern);

        foreach (Match match in matches)
        {
            var bookName = match.Value;
            if (!countDictionary.ContainsKey(bookName)) countDictionary[bookName] = 0;
            ++countDictionary[bookName];
        }

        Process.Start(directoryPath, siteName); // Assuming directory path is the website's directory and site name is the file name of the website.

        return countDictionary;
    }
}
