['Here's a basic implementation of such a C function using Jansson library for JSON parsing. For simplicity and clarity, this example only logs errors without categorizing them. 

```c
#include <jansson.h>
#include <ctype.h>
#include <string.h>
#include <stdbool.h>

/* Helper function to check if a string contains non-alphanumeric characters */
static bool isAlphaNumeric(const char *str) {
    while(*str != '\0') {
        if(!isalnum((unsigned char)*str))
            return false;
        str++;
    }
    return true;
}

/* Recursive function to validate a JSON object */
static bool validateJson(json_t *obj, const char *key) {
    json_type type = json_typeof(obj);

    if (type == JSON_OBJECT) {
        size_t index;
        json_t *value;
        json_object_foreach(obj, index, value) {
            const char *name = json_object_iter_key(value);
            if(!validateJson(value, name)) {
                printf("Invalid field: %s\n", key == NULL ? "<root>" : key);
                return false;
            }
        }
    } else if (type == JSON_STRING) {
        const char *str = json_string_value(obj);
        if(key != NULL && strcmp(key, "token_type") == 0 && strcmp(str, "Bearer") != 0) {
            printf("Invalid token type: %s\n", str);
            return false;
        } else if(key != NULL && strcmp(key, "refresh_token") == 0) {
            int len = strlen(str);
            if(len > 100 || len == 0 || !isAlphaNumeric(str)) {
                printf("Invalid refresh token: %s\n", str);
                return false;
            }
        } else if(key != NULL && strcmp(key, "expires_in") == 0) {
            int num = atoi(str);
            if(num <= 0) {
                printf("Invalid expires in: %s\n", str);
                return false;
            }
        }
    } else if (type != JSON_INTEGER && type != JSON_REAL) {
        printf("Unexpected field: %s\n", key == NULL ? "<root>" : key);
        return false;
    }

    return true;
}

bool validateAccessToken(const char *jsonStr) {
    json_error_t error;
    json_t *root = json_loads(jsonStr, 0, &error);

    if(!root) {
        printf("Error parsing JSON: %s\n", error.text);
        return false;
    }

    bool result = validateJson(root, NULL);
    json_decref(root);

    return result;
}
```
This code uses Jansson for JSON parsing and validation. Note that this does not handle thread safety or optimizing for memory usage and execution time as those would require more complex solutions, such as a streaming JSON parser or custom memory allocation strategies. 

