['Here is the Rust code that implements the described functionality:

```rust
extern crate openssl;
extern crate serde_json;
extern crate base64;
extern crate tokio;
use openssl::symm::{Cipher, Crypter};
use serde_json::Value;
use std::str;
use tokio::sync::Mutex;
use std::error::Error;
use futures::future::FutureExt;
use std::panic;

async fn processSecureMessage(json: &str, encrypted: &[u8], key: &[u8], iv: &[u8]) -> Result<String, Box<dyn Error>> {
    let json_value: Value = serde_json::from_str(json)?;
    let access_token = json_value["access_token"].as_str().ok_or("Missing access_token field")?;
    let expires_in = json_value["expires_in"]
        .as_u64()
        .map(|i| i as usize)
        .ok_or("Invalid expires_in field")?;
    let token_type = json_value["token_type"].as_str().ok_or("Missing token_type field")?;

    if token_type != "Bearer" {
        return Err(formatError("Token type must be Bearer", &[]));
    }

    let cipher = Cipher::des_ede3_cbc();
    let mut crypter = Crypter::new(cipher, key.to_vec(), Some(iv.to_vec()), true)?;
    let decrypted = crypter.update(encrypted).unwrap_or_else(|e| {
        panic::catch_unwind()
            .map_err(|_| formatError("Decryption failed", &[&*e]))
            .ok()
            .expect("Shouldn't reach here")
    });

    let decrypted = str::from_utf8(&decrypted)?;
    Ok(decrypted.to_string())
}

fn formatError<E: Error + 'static>(message: &str, errors: &[&dyn Error]) -> Box<dyn Error> {
    let mut message = String::new();
    writeln(&mut message, message)?;

    for error in errors.iter() {
        writeln(&mut message, format_error(error))?;
    }

    ErrBox::new(message)
}
```

Please note that you have to add the necessary dependencies in your Cargo.toml file:

