['```C#
using System;
using System.Security.Cryptography;
using System.Text;
using System.IO;

public class HashAlgorithmFactory {
    public static HashAlgorithm CreateHashAlgorithm(string algorithmName) {
        switch (algorithmName) {
            case "MD5": return MD5.Create();
            case "SHA256": return SHA256.Create();
            case "SHA512": return SHA512.Create();
            default: throw new ArgumentException("Invalid algorithm name");
        }
    }
}

public class HashingService {
    private readonly HashAlgorithm _hashAlgorithm;
    private const int ChunkSize = 4096; // Adjust as per requirement

    public HashingService(string hashAlgorithm) {
        _hashAlgorithm = HashAlgorithmFactory.CreateHashAlgorithm(hashAlgorithm);
    }

    public string CalculateMD5Hash(Stream inputStream) {
        using (_hashAlgorithm) {
            byte[] buffer = new byte[ChunkSize];
            int bytesRead;

            while ((bytesRead = inputStream.Read(buffer, 0, ChunkSize)) > 0) {
                _hashAlgorithm.TransformBlock(buffer, 0, bytesRead, buffer, 0);
            }
        }

        return BitConverter.ToString(_hashAlgorithm.Hash).Replace("-", "").ToLowerInvariant();
    }
}
```
This C# code defines a factory class `HashAlgorithmFactory` that creates and returns an instance of the specified hash algorithm (MD5, SHA256, or SHA512), and a service class `HashingService` which uses this factory to create hash algorithms based on configuration. The hashing is performed in chunks to avoid out-of-memory errors with large inputs.

The code does not include a logging framework integration as it's beyond the scope of this task. Logging frameworks have their own methods for handling log entries and they handle their own memory management, therefore, it's better to leave that job to them. The hashing service calculates the hash based on input stream data in chunks which helps to optimize memory usage for large inputs. 

