['Here is an example of how you might start implementing these requirements in C#:

```CSharp
using System;
using System.Text;
using System.Security.Cryptography;
using System.IO;
using System.Threading.Tasks;
using System.Configuration;
using System.Collections.Concurrent;

public class AesCbcService : IDisposable
{
    private readonly ConcurrentDictionary<string, (Aes aes, ICryptoTransform encryptor, ICryptoTransform decryptor)> _ciphers = new();
    private readonly IAuthService _authService;

    public AesCbcService(IAuthService authService) 
    {
        _authService = authService ?? throw new ArgumentNullException(nameof(authService));
    }

    public async Task<byte[]> EncryptAsync(string user, byte[] key, byte[] iv, byte[] dataToEncrypt)
    {
        if (!_authService.Authenticate(user)) throw new UnauthorizedAccessException("User not authenticated");

        using var aes = Aes.Create();
        aes.KeySize = 256; // replace with your key size
        aes.BlockSize = 128; // replace with your block size
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        aes.Key = key;
        aes.IV = iv;
        ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
        _ciphers[user] = (aes, encryptor, null);

        using var ms = new MemoryStream();
        using var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write);
        await cs.WriteAsync(dataToEncrypt, 0, dataToEncrypt.Length);
        cs.FlushFinalBlock();

        return ms.ToArray();
    }

    public async Task<byte[]> DecryptAsync(string user, byte[] key, byte[] iv, byte[] encryptedData)
    {
        if (!_authService.Authenticate(user)) throw new UnauthorizedAccessException("User not authenticated");

        using var aes = Aes.Create();
        aes.KeySize = 256; // replace with your key size
        aes.BlockSize = 128; // replace with your block size
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        aes.Key = key;
        aes.IV = iv;
        ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        _ciphers[user] = (aes, null, decryptor);

        using var ms = new MemoryStream();
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write);
        await cs.WriteAsync(encryptedData, 0, encryptedData.Length);
        cs.FlushFinalBlock();

        return ms.ToArray();
    }

    public void Dispose()
    {
        foreach (var item in _ciphers)
        {
            item.Value.encryptor?.Dispose();
            item.Value.decryptor?.Dispose();
            item.Value.aes?.Dispose();
        }

        _ciphers.Clear();
    }
}
``` 

