['Here's a sample code snippet that provides an approach to handle such large datasets efficiently. It uses the `System.IO.Compression` namespace to decompress data from a binary file into a memory-efficient custom data structure, handles errors gracefully and shows progress using a ProgressBar. However, please note that you should replace "DataStructure" with your actual data structure type:

```CSharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.IO.Compression;
using System.Windows.Forms; //This is required for the ProgressBar control, consider using your own progress reporting mechanism if you're not in a Windows Forms environment.

public class LargeDatasetLoader<T> where T : class
{
    private readonly string _filePath;
    private readonly BinaryFormatter _formatter = new BinaryFormatter();

    public event Action<string, int> OnProgressUpdate; // You can use this to get notified whenever progress updates.

    public LargeDatasetLoader(string filePath) 
    {
        _filePath = filePath ?? throw new ArgumentNullException(nameof(filePath));
    }

    public T LoadData()
    {
        using (var streamReader = new FileStream(_filePath, FileMode.Open))
        using (var decompressionStream = new GZipStream(streamReader, CompressionMode.Decompress))
        {
            long totalBytesRead = 0; // Use this to track progress
            var formatter = new BinaryFormatter(); 

            try
            {
                while (decompressionStream.Position < decompressionStream.Length)
                {
                    int bytesReadInLastChunk = decompressionStream.Read(buffer, 0, buffer.Length); // Read from the stream into your buffer
                    totalBytesRead += bytesReadInLastChunk;

                    OnProgressUpdate?.Invoke("Loading data...", (int)(totalBytesRead * 100 / decompressionStream.Length)); // Notify about progress
                }

                return (T)_formatter.Deserialize(decompressionStream); // Deserialize the data to your custom type
            }
            catch (Exception ex)
            {
                throw new Exception("An error occurred while loading data.", ex); // Handle exceptions gracefully
            }
        }
    }
}
```
