        AudioConversionSystem system = new AudioConversionSystem();
        String className = ...; // The class name of the object being deserialized.
        Object obj = system.deserializeObject(serializedData, className);

        if (obj instanceof AudioMetadata) {
            AudioMetadata metadata = (AudioMetadata) obj;

            String inputFileName = metadata.getInputFileName();
            int targetSampleRate = metadata.getTargetSampleRate();
            String outputFileName = metadata.getOutputFileName();

