["Here is a simplified example using the JavaScript `axios` library to make HTTP requests, `js-file-upload` for uploading and resuming partial files, and `formidable` to handle form data. This code does not include all functionalities you asked but gives you an idea of how it could be implemented:

```javascript
const axios = require('axios');
const FormData = require('form-data');
const { FileUpload } = require('js-file-upload');

let retries = 0;
let maxRetries = 5; // set your maximum number of retries
let timeoutLimit = 120000;  // set your total timeout limit in milliseconds

// Function to upload file using axios post request
async function uploadFile(filePath, url) {
    const formData = new FormData();
    formData.append('file', fs.createReadStream(filePath));

    let response;
    try {
        response = await axios({
            method: 'post',
            url: url,
            data: formData,
            headers: { 
                ...formData.getHeaders() // set any additional headers if required
            },
            maxContentLength: Infinity,
            maxBodyLength: Infinity,
        });
    } catch (error) {
        console.log(`Error occurred during uploading file ${filePath} - retrying...`);
        return handleRetry(filePath, url);  // handle retry mechanism for failed uploads
    }

    return response;
}

// Function to handle retries with exponential backoff
async function handleRetry(filePath, url) {
    const retryDelay = Math.pow(2, retries) * 1000; // calculate exponential delay

    if (retryDelay < timeoutLimit && retries <= maxRetries) {
        retries++;
        console.log(`Next upload attempt in ${retryDelay/1000} seconds...`);
        await new Promise((resolve) => setTimeout(resolve, retryDelay)); // delay next retry
        return await uploadFile(filePath, url); // try to upload again after a delay
    } else {
        retries = 0;  // reset the counter for next file
        console.log('Maximum number of retries reached or total timeout limit exceeded...');
        throw new Error(`Could not complete upload for ${filePath} after maximum retries`);
    }
}

// Function to validate URL
function isValidURL(url) {
  const a = document.createElement('a');
  a.href = url;
  return (a.host && a.host !== window.location.host);
}

async function main() {
    let filePath = './path/to/file';
    let url = 'http://cloud-storage.url'; // replace with your cloud storage url

    if (!isValidURL(url)) {
        console.log('Invalid URL');
        return;
    }

    const response = await uploadFile(filePath, url);

    let logs = [];  // store progress logs here for each retry
    logs.push({response: response, retries: retries});

    console.log('Upload process completed');
    return {url: url, logs: logs};
}

