```rust
use std::fs;
use std::io;
use std::env;
use std::thread;
use log::{info};
use std::sync::{Arc, RwLock, Mutex};
use std::process;

static DEFAULT_VARIABLE: &str = "DEFAULT_ENVIRONMENT_VARIABLE";
type SharedState = Arc<RwLock<SharedData>>;

#[derive(Clone)]
pub struct Config {
    dir_name: String,
    variable_name: Option<String>,
}

impl Config {
    pub fn new(dir_name: &str, variable_name: Option<&str>) -> Self {
        let env = match variable_name {
            Some(v) => v.to_string(),
            None => DEFAULT_VARIABLE.to_string()
        };
        Config { dir_name: dir_name.to_string(), variable_name: Some(env)}
    }
}

#[derive(Clone)]
struct SharedData {
    config: Option<Config>,
}

pub struct DirectoryManager {
    shared_state: SharedState,
}

impl Default for DirectoryManager {
    fn default() -> Self {
        let shared_data = SharedData {config: None};
        let shared_state = Arc::new(RwLock::new(shared_data));
        DirectoryManager { shared_state }
    }
}

impl DirectoryManager {
    pub fn set_directory(&self, dir_name: &str, variable_name: Option<&str>) {
        let mut guard = self.shared_state.write().unwrap();
        let config = Config::new(dir_name, variable_name);
        guard.config = Some(config);
    }

    pub fn handle(&self) {
        thread::spawn(move || {
            loop {
                thread::sleep(std::time::Duration::from_secs(1));

                let shared_data = self.shared_state.read().unwrap();
                if let Some(config) = &shared_data.config {
                    info![&format![ "Handling directory: {}", config.dir_name]];

                    match fs::create_dir(&config.dir_name) {
                        Ok(_) => {
                            env::set_var(config.variable_name.as_deref().unwrap(), &config.dir_name);
                            info![&format![ "Directory created: {}", config.dir_name]];
                        }

                        Err(err) => match err.kind() {
                            io::ErrorKind::AlreadyExists => {},

                            _ => {
                                error![&format![ "Failed to create directory: {}", err]];
                            }
                        },
                    };
                };
            }
        });
    }
}
```
This code block is a simplified version of what you requested. It's missing features like signal handling, process cleanup, and configuration updates at runtime for simplicity. You may need to handle error cases more robustly in a production environment.
