import json
from abc import ABCMeta, abstractmethod
from typing import Callable, Dict, List

class DataModel(metaclass=ABCMeta):
    @abstractmethod
    def validate(self) -> bool:
        pass

    @abstractmethod
    def transform(self) -> dict:
        pass

class Registry:
    def __init__(self):
        self.factory_functions: Dict[str, Callable] = {}

    def register(self, unique_id: str, factory_function: Callable[[Dict], DataModel]) -> None:
        self.factory_functions[unique_id] = factory_function

    def create_instance(self, unique_id: str, data: dict) -> DataModel:
        if unique_id not in self.factory_functions:
            raise ValueError(f"No factory function registered for {unique_id}")
        return self.factory_functions[unique_id](data)

class JsonSerializerMixin:
    @staticmethod
    def serialize(obj):
        if isinstance(obj, DataModel):
            obj = obj.transform()

        return json.dumps(obj)

    @staticmethod
    def deserialize(json_str, unique_id: str, registry: Registry):
        data = json.loads(json_str)
        instance = registry.create_instance(unique_id, data)

        if not instance.validate():
            raise ValueError("Data is invalid")

        return instance
