['Below is Java code for your problem using Java's ExecutorService for parallel processing and caching mechanism with Guava library to store resized images in cache. It uses a simple ImageIO for loading, saving and creating buffered image objects and it doesn't stream files, but handles large files gracefully by not keeping them in memory:

```java
import javax.imageio.ImageIO;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class ImageProcessor {
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    // Adjust the maximum size according to your needs
    private static final LoadingCache<String, BufferedImage> imageCache = CacheBuilder.newBuilder()
            .maximumSize(100)
            .build(
                    new CacheLoader<String, BufferedImage>() {
                        @Override
                        public BufferedImage load(String filePath) throws Exception {
                            return validateAndResizeImage(filePath, 640, 480);
                        }
                    });

    public static void processImageFiles(List<String> imageFilePaths) {
        for (String filePath : imageFilePaths) {
            executor.submit(() -> {
                try {
                    BufferedImage resizedGrayscaleImage = imageCache.getUnchecked(filePath);
                    // save or process the resized and grayscale image here
                } catch (Exception e) {
                    e.printStackTrace();
                }
            });
        }
    }

    private static BufferedImage validateAndResizeImage(String filePath, int targetWidth, int targetHeight) throws IOException {
        File inputFile = new File(filePath);
        if (!inputFile.exists()) {
            throw new IllegalArgumentException("Input file does not exist: " + filePath);
        }

        BufferedImage originalImage = ImageIO.read(inputFile);

        double scaleX = (double) targetWidth / originalImage.getWidth();
        double scaleY = (double) targetHeight / originalImage.getHeight();
        AffineTransform transform = new AffineTransform();
        transform.scale(scaleX, scaleY);

        BufferedImage resizedImage = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = resizedImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2d.drawImage(originalImage, transform, null);
        g2d.dispose();

        return resizedImage;
    }
}
```
Please note that converting image to grayscale is not implemented in the code snippet above as it depends on how you want to handle the conversion and caching of this step.
