    if (strlen(newFilename) > MAX_LEN) {
        printf("Error: Filename is too long\n");
        pthread_exit(NULL);
    }

    // Ensuring thread safety for circular buffer operations
    pthread_mutex_lock(&lock);
    // Perform the necessary operations with the new filename, such as renaming and extending the file. 
    pthread_mutex_unlock(&lock);
}

void generateMD5(unsigned char* data, size_t len, unsigned char* md5HashValue) {
