    threadSafeInsert(buffer, newName);
    char* oldFilename = threadSafeRemove(buffer);
    pthread_mutex_unlock(&buffer.mutex);

    if (oldFilename != NULL) {
        remove(oldFilename);
        free(oldFilename);
    }
}

void generateMD5Hash(const char* filename, unsigned char* md5Buffer) {
    FILE *inFile = fopen(filename, "rb");

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

