['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PHY_TEST_CONFIG {
    int PHYSICAL_LAYER_TEST_ID;
    int SUBFRAME_INDEX;
    double CHANNEL_FREQUENCY;
    char *TEST_DATA_BUFFER; // dynamically allocated resource
} LTE_PHY_TEST_CONFIG;

typedef struct DynamicList {
    LTE_PHY_TEST_CONFIG **list;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;  // for thread safety
} DynamicList;

DynamicList *createList(size_t N) {
    DynamicList *l = (DynamicList *)malloc(sizeof(DynamicList));
    if (l == NULL) return NULL;

    l->list = (LTE_PHY_TEST_CONFIG **)calloc(N, sizeof(LTE_PHY_TEST_CONFIG *));
    if (l->list == NULL) {
        free(l);
        return NULL;
    }

    l->capacity = N;
    l->size = 0;
    pthread_mutex_init(&l->lock, NULL);  // initialize mutex for thread safety
    return l;
}

int appendList(DynamicList *l, LTE_PHY_TEST_CONFIG *config) {
    if (config == NULL || config->PHYSICAL_LAYER_TEST_ID < 0 || 
        config->SUBFRAME_INDEX < 0 || config->CHANNEL_FREQUENCY < 0.0) return -1;  // validate input

    pthread_mutex_lock(&l->lock);  // lock for thread safety

    if (l->size >= l->capacity) {  // reallocate when full
        size_t newCapacity = l->capacity * 2;
        LTE_PHY_TEST_CONFIG **newList = (LTE_PHY_TEST_CONFIG **)realloc(l->list, newCapacity * sizeof(LTE_PHY_TEST_CONFIG *));
        if (newList == NULL) {  // reallocation failed
            pthread_mutex_unlock(&l->lock);  // unlock before return to avoid deadlock
            return -1;
        }

        l->list = newList;
        l->capacity = newCapacity;
    }

    LTE_PHY_TEST_CONFIG *newConfig = (LTE_PHY_TEST_CONFIG *)malloc(sizeof(LTE_PHY_TEST_CONFIG));  // allocate memory for structure
    if (newConfig == NULL) {
        pthread_mutex_unlock(&l->lock);  // unlock before return to avoid deadlock
        return -1;
    }

    *newConfig = *config;  // copy contents of input to new memory location
    l->list[l->size++] = newConfig;  // add to the list and increment size
    pthread_mutex_unlock(&l->lock);  // unlock after modification is done

    return 0;
}

void freeList(DynamicList *l) {
    if (l == NULL) return;

    for (size_t i = 0; i < l->size; ++i) free(l->list[i]);  // free each structure
    free(l->list);  // free the list of pointers
    pthread_mutex_destroy(&l->lock);  // destroy mutex for thread safety

    free(l);  // free the DynamicList struct itself
}
