['Below is an example of how you could implement this in C using POSIX Threads (pthread) and System V Semaphore API:

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <semaphore.h>
#include <pthread.h>

// Define global semaphore and mutex
sem_t mySemaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int value;

void sigHandler(int signum) {
    printf("Caught signal %d, releasing semaphore\n", signum);

    pthread_mutex_lock(&mutex);
    if (sem_post(&mySemaphore) == -1){
        perror("Error releasing the semaphore");
    }
}

void* threadFunc(void *arg) {
    // Critical section 
    pthread_mutex_lock(&mutex);

    if (sem_wait(&mySemaphore) == -1){
        perror("Error waiting on semaphore");
        return NULL;
    }

    printf("Thread %ld acquired the semaphore\n", pthread_self());

    // Perform some operation here

    if (sem_post(&mySemaphore) == -1){
        perror("Error releasing the semaphore");
        return NULL;
    }

    printf("Thread %ld released the semaphore\n", pthread_self());

    pthread_mutex_unlock(&mutex);
}

void manageSemaphore(int initialValue) {
    value = initialValue; // save initial value globally

    if (sem_init(&mySemaphore, 1, initialValue) == -1){
        perror("Error initializing semaphore");
    }

    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    // Create threads or use the semaphore in a multi-threaded environment here.
}

void reinitializeSemaphore(int newValue) {
    pthread_mutex_lock(&mutex);

    if (sem_destroy(&mySemaphore) == -1){
        perror("Error destroying semaphore");
    }

    value = newValue; // save new initial value globally

    if (sem_init(&mySemaphore, 1, newValue) == -1){
        perror("Error reinitializing semaphore");
    }

    pthread_mutex_unlock(&mutex);
}
```
Note that this is a simple example and doesn't cover all edge cases or error conditions. In a real-world application, you would want to handle these more robustly, perhaps by using additional synchronization mechanisms such as condition variables to wake up threads waiting on the semaphore when it becomes available. 

Also note that signal handlers are not safe for use in multithreaded programs, so this code should only be used with single-threaded processes and threads or where you can guarantee that there will never be a concurrent access to the same memory location across different signals.
