typedef struct ConfigList {
    LTE_PHY_TEST_CONFIG** list;
    int size;
    pthread_mutex_t mutex;
} ConfigList;

ConfigList* createConfigList(int N) {
    ConfigList* configs = malloc(sizeof(ConfigList));
    if (!configs) return NULL;

    configs->list = calloc(N, sizeof(LTE_PHY_TEST_CONFIG*));
    if (!configs->list) {
        free(configs);
        return NULL;
    }

    configs->size = N;
    pthread_mutex_init(&configs->mutex, NULL);

    for (int i = 0; i < N; ++i) {
        configs->list[i] = malloc(sizeof(LTE_PHY_TEST_CONFIG));
        if (!configs->list[i]) {
            freeConfigList(configs);
            return NULL;
        }
    }

    return configs;
}

void updateConfig(ConfigList* configs, int index, LTE_PHY_TEST_CONFIG newConfig) {
    if (index < 0 || index >= configs->size) return;

    pthread_mutex_lock(&configs->mutex);

    *(configs->list[index]) = newConfig;

    pthread_mutex_unlock(&configs->mutex);
}

void freeConfigList(ConfigList* configs) {
    for (int i = 0; i < configs->size; ++i) {
        if (configs->list[i]) {
            free(configs->list[i]->TEST_DATA_BUFFER);
            free(configs->list[i]);
        }
    }

    free(configs->list);
    pthread_mutex_destroy(&configs->mutex);
    free(configs);
}
