void process_directory(char *dir, char *output, char *query, int threshold, int includeCompressed) {
    DIR *dp;
    struct dirent *entry;
    struct stat filestat;

    dp = opendir(dir); 
    if (dp == NULL) {
        perror("opendir: Path does not exist");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        stat(entry->d_name, &filestat);

        // check if the file is a regular file
        if (S_ISREG(filestat.st_mode)) {
            process_file(entry->d_name, query, threshold, includeCompressed);

            // renaming file
            char newName[256];
            getNewFileName(entry->d_name, newName);
            rename(entry->d_name, newName);
        }
