    closedir(dp);
}

void process_file(char *filename, char *query, int threshold, int includeCompressed) {
    FILE *fp;
    fp = fopen(filename, "r");  // open file in read mode

    if (fp == NULL) {
        perror("fopen: File does not exist or can't be opened");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // parse and filter lines based on query and threshold
    } 

    fclose(fp);
}

void getNewFileName(char *oldName, char *newName) {
    struct stat st;
    stat(oldName, &st);
    size_t size = st.st_size / 1024; // converting bytes to kilobytes

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char date[11];
    strftime(date, sizeof(date), "%Y%m%d", tm);  // getting current date

    if (isalpha(oldName[0])) {
        sprintf(newName, "%s_%.*s", oldName, 3, oldName + strlen(oldName) - 3);
    } else if (isdigit(oldName[0])) {
        sprintf(newName, "%s_%zu", oldName, size);
    } else {
        sprintf(newName, "%s_%s", oldName, date);
    }
}
