#include <blueslip/slip-debug.h>
#include <JavaChannel.h>
#include <NFAPI_CRC_INDICATION_PDU_T.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_CONNECTIONS 10
static int current_connections = 0;
static pthread_mutex_t connection_lock = PTHREAD_MUTEX_INITIALIZER;

void connectAndTestNFAPIList(char* label, void (*f)(NFAPI_CRC_INDICATION_PDU_T *)) {
    srand(time(NULL));

    // Lock the connection mutex to ensure thread safety.
    pthread_mutex_lock(&connection_lock);

    // Ensure we are not exceeding the maximum number of connections allowed.
    if (current_connections >= MAX_CONNECTIONS) {
        blueslip("connectAndTestNFAPIList", "Maximum concurrent connections reached, skipping test %s.", label);
        pthread_mutex_unlock(&connection_lock);
        return;
    }

    // Increase the current connection count.
    current_connections++;
    pthread_mutex_unlock(&connection_lock);

    JavaChannel *jc = NULL;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    // Establish a connection with the remote address.
    jc = JavaChannel_establishConnection(NULL, 0);
    if (jc == NULL) {
        blueslip("connectAndTestNFAPIList", "Failed to establish connection for test %s.", label);
        goto cleanup;
    }

    // Generate the list of NFAPI_CRC_INDICATION_PDU_T structures.
    list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
    for (int i = 0; i < 10; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand();
        list[i].CRC_INDICATION_REL8_TAG = rand();
    }

    // Perform the unit tests.
    (*f)(list);

cleanup:
    if (jc != NULL) {
        JavaChannel_disconnect(jc);
    }
    free(list);

    pthread_mutex_lock(&connection_lock);
    current_connections--;
    pthread_mutex_unlock(&connection_lock);
}
```
