public class ConnectionManager
{
    private readonly List<Connection> _connections = new List<Connection>();
    private readonly object _lockObject = new object();

    public void MakeConnection(Action action)
    {
        if (_connections.Count >= 10) // limit to 10 connections
            throw new InvalidOperationException("Maximum number of connections reached");

        var connection = new Connection(this);

        lock (_lockObject)
        {
            _connections.Add(connection);
        }

        try
        {
            action(); // perform the action within the established connection
        }
        finally
        {
            lock (_lockObject)
            {
                _connections.Remove(connection);
            }
        }
    }
}

public class Connection : IDisposable
{
    private readonly ConnectionManager _manager;

    public Connection(ConnectionManager manager)
    {
        _manager = manager;
    }

    public void Dispose()
    {
        // dispose logic here
    }
}

public class TestRunner
{
    private readonly List<TestResult> _testResults = new List<TestResult>();
    private readonly ConnectionManager _connectionManager = new ConnectionManager();

    public void RunTest(string label, Action test)
    {
        var result = new TestResult { Label = label };

        try
        {
            _connectionManager.MakeConnection(() =>
            {
                // perform the actual test within the connection
                test();
                result.IsSuccessful = true;
            });
        }
        catch (Exception ex)
        {
            result.ErrorMessage = ex.Message;
        }

        _testResults.Add(result);
    }

    public class TestResult
    {
        public string Label { get; set; }
        public bool IsSuccessful { get; set; }
