void add_stream(int id, const char* type, int rate) {
    // Reallocate memory
    if (++num_streams > size) {
        if ((streams = realloc(streams, sizeof(*streams) * (size + 10))) == NULL) {
            fprintf(stderr, "Failed to allocate memory.\n");
