        exit(EXIT_FAILURE);  // Or handle it in a different way depending on the context.
    }

    new_stream->DEVICE_ID = id;
    new_stream->STREAM_TYPE = strdup(type);
    if (new_stream->STREAM_TYPE == NULL) {
        fprintf(stderr, "Failed to allocate memory for stream type.\n");
        exit(EXIT_FAILURE);  // Or handle it in a different way depending on the context.
    }

    new_stream->DATA_RATE = rate;
    streams[num_streams - 1] = new_stream;
}
