int addStream(char *deviceID, int streamType, float dataRate) {
    StreamConfig *config = malloc(sizeof(StreamConfig));
    if (config == NULL) return -1; // Error check memory allocation

    config->DEVICE_ID = deviceID;
    config->STREAM_TYPE = streamType;
    config->DATA_RATE = dataRate;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < 10; i++) { // Loop through the array to find an empty slot
        if (streams[i] == NULL) {
            streams[i] = config;

            pthread_create(&config->thread, NULL, streamFunction, config); // Start new thread for this stream

            pthread_mutex_unlock(&lock);
            return i; 
        }
    }
    pthread_mutex_unlock(&lock);

    free(config); // Free memory if no slot was found
    return -1;
}

void *streamFunction(void *arg) {
