    while(1) {
        /* Handle data stream here */

        pthread_mutex_lock(&lock);
        if (/* Check for sudden spike in traffic*/) {
            /* Handle the sudden spike here */
        }
        pthread_mutex_unlock(&lock);
    } 

    return NULL;
}
