```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int* read_integers(size_t *length) {
    int capacity = 1000;
    *length = 0;
    int* array = malloc(capacity * sizeof(*array));

    if (!array) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(EXIT_FAILURE);
    }

    while (*length < capacity && scanf("%d", &array[*length]) == 1) {
        ++(*length);
        if (*length == capacity) {
            int new_capacity = capacity * 2;
            int* tmp = realloc(array, new_capacity * sizeof(*tmp));

            if (!tmp) {
                free(array);
                fprintf(stderr, "Error: Out of memory.\n");
                exit(EXIT_FAILURE);
            }

            array = tmp;
            capacity = new_capacity;
        }
    }

    if (*length == 0) {
        fprintf(stderr, "Error: Input stream is empty.\n");
        exit(EXIT_FAILURE);
    }

    return array;
}

