#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <unistd.h>

typedef struct Stream {
    char* DEVICE_ID;
    char* STREAM_TYPE;
    int DATA_RATE;
    pthread_t thread;
} Stream;

typedef struct Node {
    Stream** streams;
    atomic_int streamCount;
    pthread_mutex_t lock;
} Node;

Node* nodes = NULL;
int nodeCount = 0;
pthread_mutex_t nodesLock = PTHREAD_MUTEX_INITIALIZER;

void* dataProcessing(void* args) {
    Stream* stream = (Stream*)args;

    // Process data here
}

int addStream(char* DEVICE_ID, char* STREAM_TYPE, int DATA_RATE) {
    pthread_mutex_lock(&nodesLock);

    Stream* newStream = (Stream*)malloc(sizeof(Stream));
    if (!newStream) return -1;  // Error handling for memory allocation failure.

    newStream->DEVICE_ID = DEVICE_ID;
    newStream->STREAM_TYPE = STREAM_TYPE;
    newStream->DATA_RATE = DATA_RATE;

    pthread_create(&newStream->thread, NULL, dataProcessing, (void*)newStream);

    Node* nodeWithLeastStreams = NULL;
    int leastCount = 0x7fffffff; // Initialize with maximum value.

    for(int i = 0; i < nodeCount; ++i) {
        int count = atomic_load(&nodes[i].streamCount);
        if (count < leastCount) {
            leastCount = count;
            nodeWithLeastStreams = &nodes[i];
        }
    }

    // Add the new stream to a Node with the minimum number of streams.
    pthread_mutex_lock(&nodeWithLeastStreams->lock);
    nodeWithLeastStreams->streams = realloc(nodeWithLeastStreams->streams, sizeof(Stream*) * (leastCount + 1));
    if (!nodeWithLeastStreams->streams) return -2;  // Error handling for memory allocation failure.

    nodeWithLeastStreams->streams[leastCount] = newStream;
    atomic_fetch_add(&nodeWithLeastStreams->streamCount, 1);

    pthread_mutex_unlock(&nodesLock);
    return 0;
}
```
The above code provides a basic structure for handling streams and dynamically allocating them across available nodes. It does not cover all the requirements specified due to the complexity of the task. For example, automated alerting mechanisms, load balancing, external monitoring services or comprehensive unit tests are complex tasks that would require significant additional code.
