#include <vector>
#include <map>
#include <mutex>
#include <shared_mutex> //For shared mutex in C++17 and later versions

struct Profile {
    std::string id;
    std::string name;
    std::string email;
    int posts, comments, likes;
};

class ProfilesManager {
public:
    void addProfile(const Profile& profile) {
        std::lock_guard<std::shared_mutex> lock(mMutex);
        mProfiles[profile.id] = profile;
    }

    void removeProfile(const std::string& id) {
        std::unique_lock<std::shared_mutex> lock(mMutex);
        auto it = mProfiles.find(id);
        if (it != mProfiles.end()) {
            mProfiles.erase(it);
        } else {
            throw std::invalid_argument("Profile not found");
        }
    }

    Profile getProfile(const std::string& id) const {
        std::shared_lock<std::shared_mutex> lock(mMutex);
        auto it = mProfiles.find(id);
        if (it != mProfiles.end()) {
            return it->second;
        } else {
            throw std::invalid_argument("Profile not found");
        }
    }

private:
    mutable std::shared_mutex mMutex; //For shared mutex in C++17 and later versions
    std::map<std::string, Profile> mProfiles;
};
```
