void InitLogger(Logger* logger) {
    logger->buffer = malloc(1024);
    logger->bufferSize = 1024;
    memset(logger->buffer, 0, logger->bufferSize);
    pthread_mutex_init(&logger->lock, NULL);

    // Assigning a plugin to handle different logging levels
    logger->plugin = LogDebug;
}

void AppendToLog(Logger* logger, char* message) {
    size_t length = strlen(message);

    if (length > logger->bufferSize) {
        // Dynamically resize the buffer to fit the new message
        logger->buffer = realloc(logger->buffer, logger->bufferSize + length);
        logger->bufferSize += length;
    }

    pthread_mutex_lock(&logger->lock);
    strcat(logger->buffer, message);
    pthread_mutex_unlock(&logger->lock);
}

void LogMessage(Logger* logger, char* level, char* message) {
    // Use the plugin to log the message
    logger->plugin(message, level);

    char timestamp[20];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

    // Format the log message with a timestamp and level
    char formattedMessage[strlen(message) + strlen(level) + strlen(timestamp) + 5];
    sprintf(formattedMessage, "[%s] [%s] %s", timestamp, level, message);

    // Asynchronously append the log message to the buffer
    AppendToLog(logger, formattedMessage);
}

void DestroyLogger(Logger* logger) {
    free(logger->buffer);
    pthread_mutex_destroy(&logger->lock);
}
