typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next, *prev;
} Node;

typedef struct DoublyLinkedList {
    pthread_mutex_t mutex;  // Mutual exclusion lock for thread safety
    Node *head;
    uint32_t size;  // Current size of the list
} DoublyLinkedList;

// Initialize an empty list.
void initialize(DoublyLinkedList *list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->size = 0;
}

// Add a new entry to the list.
void addEntry(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);  // Lock for thread safety

    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = list->head;
    newNode->prev = NULL;

    if (list->head != NULL) {
        list->head->prev = newNode;
    }

    list->head = newNode;
    list->size++;

    pthread_mutex_unlock(&list->mutex);  // Unlock after modification is done
}
```
