#include <stdbool.h>
#include <regex.h>
#include <pthread.h>
#include <sys/stat.h>
#include <sqlite3.h>

typedef struct {
    char* server_name;
    int port;
    int max_connections;
    char* log_level;
} Configuration;

bool parse_configuration(const char* config_file, const char* db_conn_string, size_t max_size) {
    // Check file size
    struct stat st;
    if (stat(config_file, &st) != 0 || st.st_size > max_size) {
        return false;
    }

    Configuration* config = malloc(sizeof(Configuration));

    // Validate fields using regex
    regex_t server_name_pattern;
    regcomp(&server_name_pattern, "^[A-Za-z0-9\\.]+$", REG_EXTENDED | REG_NOSUB); 

    if (regexec(&server_name_pattern, config->server_name, 0, NULL, 0) != 0) {
        regfree(&server_name_pattern);
        return false;
    }
    // Similarly validate other fields using regex

    sqlite3* db;
    if (sqlite3_open(db_conn_string, &db) != SQLITE_OK) {
        fprintf(stderr, "Failed to connect to database: %s\n", sqlite3_errmsg(db));
        return false;
    }

    char* err_msg = 0;

    // Build and execute INSERT query
    const char* insert_query = "INSERT INTO Configurations (server_name, port, max_connections, log_level) VALUES (?, ?, ?, ?);";
    sqlite3_exec(db, insert_query, NULL, 0, &err_msg);

    if (err_msg != 0) {
        fprintf(stderr, "Failed to execute INSERT query: %s\n", err_msg);
        sqlite3_free(err_msg);
        return false;
    }

    // Cleanup resources
    regfree(&server_name_pattern);
    sqlite3_close(db);

    free(config);

    return true;
}
```

