['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class NumberCollection<T> where T : struct, IComparable<T>, IConvertible 
{
    private List<T> _numbers = new List<T>();
    private object _lock = new object();

    public void Add(T number)
    {
        lock (_lock)
        {
            _numbers.Add(number);
        }
    }

    public bool Remove(T number)
    {
        lock (_lock)
        {
            return _numbers.Remove(number);
        }
    }

    public T GetValueAt(int index)
    {
        lock (_lock)
        {
            if (index < 0 || index >= _numbers.Count)
                throw new ArgumentOutOfRangeException("Index out of range");

            return _numbers[index];
        }
    }

    public double GetMean()
    {
        lock (_lock)
        {
            return _numbers.Count > 0 ? _numbers.Average(t => Convert.ToDouble(t)) : 0;
        }
    }

    public T GetMedian()
    {
        lock (_lock)
        {
            var numbersCopy = new List<T>(_numbers);
            numbersCopy.Sort();

            if (numbersCopy.Count == 0) return default(T);

            if (numbersCopy.Count % 2 == 1)
                return numbersCopy[numbersCopy.Count / 2];

            dynamic a = numbersCopy[numbersCopy.Count / 2 - 1];
            dynamic b = numbersCopy[numbersCopy.Count / 2];
            return (a + b) / 2;
        }
    }

    public T GetMode()
    {
        lock (_lock)
        {
            return _numbers.GroupBy(v => v)
                .OrderByDescending(g => g.Count())
                .First().Key;
        }
    }

    public void NormalizeRange(T min, T max)
    {
        lock (_lock)
        {
            if (!_numbers.Any()) return;

            var currentMin = _numbers.Min();
            var currentMax = _numbers.Max();
            var currentRange = Convert.ToDouble(currentMax - currentMin);
            var targetRange = Convert.ToDouble(max - min);

            for (var i = 0; i < _numbers.Count; ++i)
            {
                dynamic normalizedValue = (_numbers[i] - currentMin) / currentRange * targetRange + min;
                _numbers[i] = (T)Convert.ChangeType(normalizedValue, typeof(T));
            }
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Count: {_numbers.Count}, Mean: {GetMean():F2}, Median: {GetMedian()}, Mode: {GetMode()}";
        }
    }
}
```
