                time_t t = time(NULL);
                struct tm* current_time = localtime(&t);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", current_time);

                if (isalpha(dir->d_name[0])) { // Append last 3 characters of filename as metadata tag
                    int len = strlen(dir->d_name);
                    snprintf(new_filename + strlen(new_filename), sizeof(new_filename) - strlen(new_filename), "_%s_%.*s", timestamp, (len < 3 ? len : 3), dir->d_name + len - 3);
                } else if (isdigit(dir->d_name[0])) { // Append size in kilobytes as metadata tag
                    snprintf(new_filename + strlen(new_filename), sizeof(new_filename) - strlen(new_filename), "_%s_%ldKB", timestamp, st.st_size / 1024);
                } else { // Append current date as metadata tag
                    char date[9];
                    strftime(date, sizeof(date), "%Y%m%d", current_time);
                    snprintf(new_filename + strlen(new_filename), sizeof(new_filename) - strlen(new_filename), "_%s", date);
                }

                rename(path, new_filename); // Rename file to new filename
            }
        }

        closedir(d);
    } else {
