#include <mutex>
#include <unordered_map>
#include <memory>

class Profile {
    // profile data goes here...
};

// A simple publisher-subscriber pattern implementation. 
class Subject;

struct Observer : public std::enable_shared_from_this<Observer> {
    virtual void Update(Subject* subject) = 0;
};

class Subject {
public:
    void Attach(std::weak_ptr<Observer> observer) { observers_.push_back(observer); }
    void Detach(std::weak_ptr<Observer> observer) { 
        // remove the weak pointer from the list.
    }
    void Notify() {
        for (auto& obs : observers_) {
            if (auto sp = obs.lock()) {
                sp->Update(this);
            } else {
                Detach(obs);  // remove expired pointers from the list.
            }
        }
    }
private:
    std::vector<std::weak_ptr<Observer>> observers_;
};

class ProfileManager : public Subject, public std::enable_shared_from_this<ProfileManager> {
public:
    void Update(Subject* subject) override {
        // Handle profile changes...
    }

    // Thread-safe access to profiles.
    void AddProfile(int id, const Profile& profile) {
        std::lock_guard<std::mutex> lock(m_);
        profiles_.emplace(id, std::make_unique<Profile>(profile));
        Notify();  // Notify all observers about the change.
    }

    Profile* GetProfile(int id) {
        std::lock_guard<std::mutex> lock(m_);
        auto it = profiles_.find(id);
        return it != profiles_.end() ? it->second.get() : nullptr;
    }

private:
    mutable std::mutex m_;  // Protects access to the map.
    std::unordered_map<int, std::unique_ptr<Profile>> profiles_;
};
