```c
#include <stdlib.h>
#include <string.h>

typedef struct Stream {
    char *device_id;
    int stream_type;
    float data_rate;
} Stream;

Stream **streams = NULL;
size_t num_streams = 0;

void add_stream(char *device_id, int stream_type, float data_rate) {
    // Allocate memory for a new stream structure.
    Stream *new_stream = malloc(sizeof(Stream));
    if (new_stream == NULL) {
        // Handle error: Memory allocation failed.
        return;
    }

    // Allocate memory for the device ID string.
    new_stream->device_id = malloc(strlen(device_id) + 1);
    if (new_stream->device_id == NULL) {
        // Handle error: Memory allocation failed.
        free(new_stream);
        return;
    }

    // Copy the device ID string and other parameters into the new stream structure.
    strcpy(new_stream->device_id, device_id);
    new_stream->stream_type = stream_type;
    new_stream->data_rate = data_rate;

    // Resize the streams array to make room for the new stream.
    streams = realloc(streams, sizeof(Stream*) * (num_streams + 1));
    if (streams == NULL) {
        // Handle error: Memory allocation failed.
        free(new_stream->device_id);
        free(new_stream);
        return;
    }

    // Add the new stream to the streams array and update the size counter.
    streams[num_streams] = new_stream;
    num_streams++;
}
```
