// Function to add device info
void addDevice(int DEVICE_ID, char* STREAM_TYPE, double DATA_RATE) {
    // Lock mutex before adding a device
    pthread_mutex_lock(&devicesLock);

    // Reallocate memory for devices array to accommodate new device
    devices = (DeviceInfo**)realloc(devices, sizeof(DeviceInfo*) * (numDevices + 1));
    if (devices == NULL) {
        printf("Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
