    newDevice->STREAM_TYPE = strdup(STREAM_TYPE);
    if (newDevice->STREAM_TYPE == NULL) {
        printf("Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    newDevice->DATA_RATE = DATA_RATE;

    devices[numDevices++] = newDevice;

    // Unlock mutex after adding a device
