def add_firewall_rules(filepath, rules):
    for rule in rules:
        if not execute_bash('grep -q "%s" %s' % (checksum(rule), filepath)):
            with open(filepath, 'a') as f:
                f.write("%s\n%s\n" % (rule, checksum(rule)))
        else:
            logger.info('Rule already present in the file. Skipping...')

def generate_records(count, offset_range, key_range):
    records = []
    for i in range(count):
        record = {'offset': random.randint(*offset_range), 'key': random.randint(*key_range)}
        records.append(record)
    return records

def main():
    replacements = {"interface": "eth0", "ip": "192.168.1.1"}  # example replacement variables
    replace_variables("/etc/network/interfaces", replacements)

    new_rules = ["iptables -A INPUT -p tcp --dport %s -j ACCEPT" % port for port in [22, 80, 443]] # example firewall rules
    add_firewall_rules("/etc/network/interfaces", new_rules)

    records = generate_records(10, (0, 100), (500, 1000)) # example record generation
    logger.info('Generated records: %s', str(records))

if __name__ == "__main__":
    main()
```

This script first replaces the template variables in a file using `sed` command and then adds new firewall rules to the same file if they're not already present. It also generates random records with offsets and keys within specified ranges. If any step fails, it logs an error message and continues execution. 

Please note that you should replace "/etc/network/interfaces" with your own path. Also, you might need to adjust the command based on your system's sed version if it doesn't support -i option.
