    size_t capacity;
    size_t count;
    UE_INFORMATION *list;
} LTE_MONITOR;

LTE_MONITOR* init_monitor(size_t initialCapacity) {
    LTE_MONITOR *monitor = malloc(sizeof(LTE_MONITOR));
    pthread_mutex_init(&monitor->lock, NULL);

    monitor->capacity = initialCapacity;
    monitor->count = 0;
    monitor->list = calloc(initialCapacity, sizeof(UE_INFORMATION));

    return monitor;
}

void add_ue_information(LTE_MONITOR *monitor, UE_INFORMATION info) {
    pthread_mutex_lock(&monitor->lock);

    if (monitor->count == monitor->capacity) {
        // double capacity and reallocate memory
        monitor->capacity *= 2;
        monitor->list = realloc(monitor->list, sizeof(UE_INFORMATION) * monitor->capacity);
    }

    monitor->list[monitor->count] = info;
    monitor->count++;

    pthread_mutex_unlock(&monitor->lock);
}
