int init_manager(PipelineManager* manager, size_t capacity) {
    int result = 0;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        return ENOMEM;
    }
    manager->configs = malloc(capacity * sizeof(EngineConfig));
    if (!manager->configs) {
        result = ENOMEM; 
        goto cleanup;
    }
    manager->num_engines = 0;
cleanup:
    return result;
}

int add_engine(PipelineManager* manager, EngineConfig config) {
    pthread_mutex_lock(&manager->lock);

    if (manager->num_engines >= capacity) {
        pthread_mutex_unlock(&manager->lock);
        return ENOBUFS; //Buffer Overflow
    }

    manager->configs[manager->num_engines] = config; 
    ++manager->num_engines;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}
