#include <pthread.h>
#include <stdlib.h>
#define MAX_SIZE 100

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray{
    NFAPI_CRC_INDICATION_PDU_T *array;
    int size;
    pthread_mutex_t mutex;
} DynamicArray;

void init(DynamicArray *d) {
    d->size = 0;
    d->array = malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&d->mutex, NULL);
}

void addElement(DynamicArray *d, NFAPI_CRC_INDICATION_PDU_T elem) {
    pthread_mutex_lock(&d->mutex);
    if (d->size < MAX_SIZE) {
        d->array[d->size++] = elem;
    }
    else {
        printf("Array is full\n");
    }
    pthread_mutex_unlock(&d->mutex);
}

void updateElement(DynamicArray *d, int index, NFAPI_CRC_INDICATION_PDU_T elem) {
    pthread_mutex_lock(&d->mutex);
    if (index < d->size) {
        d->array[index] = elem;
    } 
    else {
        printf("Index out of bounds\n");
    }
    pthread_mutex_unlock(&d->mutex);
}

void removeElement(DynamicArray *d, int index) {
    pthread_mutex_lock(&d->mutex);
    if (index < d->size) {
        for (int i = index; i < d->size - 1; i++) {
            d->array[i] = d->array[i + 1];
        }
        d->size--;
    } 
    else {
        printf("Index out of bounds\n");
    }
    pthread_mutex_unlock(&d->mutex);
}

NFAPI_CRC_INDICATION_PDU_T getElement(DynamicArray *d, int index) {
    NFAPI_CRC_INDICATION_PDU_T element;
    pthread_mutex_lock(&d->mutex);
    if (index < d->size) {
        element = d->array[index];
    } 
    else {
        printf("Index out of bounds\n");
    }
    pthread_mutex_unlock(&d->mutex);
    return element;
}
```
This is a simplified version and does not handle memory deallocation when removing an element to keep the code clean. In a real world scenario, one would also need to implement memory management (such as resizing the array or reallocating if it gets too full), error handling for out-of-bounds accesses, and thread safety. 

