    Result res{false}; 

    std::set<int> seedValues;
    std::ifstream inFile(filePath);
    if (inFile.is_open()) {
        int num;
        while (inFile >> num) {
            if (isValid(num)) {
                seedValues.insert(num);
            }
        }
    } else {
        std::cerr << "Error opening file: " << filePath << std::endl;
        mtx.unlock(); // Unlock the mutex
        return res; 
    }

    inFile.close();

    for (const auto& seed : seedValues) {
        if (!isValid(seed)) continue;

        vec.push_back(seed);
    }

    std::sort(vec.begin(), vec.end());
    vec.erase(std::unique(vec.begin(), vec.end()), vec.end());

    auto it = std::find(vec.begin(), vec.end(), targetVal1);
    if (it != vec.end()) {
        vec.insert(++it, toInsert);
    } else {
        vec.push_back(toInsert);
    }

    if ((int)vec.size() < minSize) {
        std::time_t now = std::time(nullptr);
        char timestamp[256];
