        std::cerr << "Warning [" << timestamp << "]: Vector size is less than minSize (" 
                  << vec.size() << " < " << minSize << ")" << std::endl;
    } else {
        res.success = true;

        int* array = new (std::nothrow) int[vec.size()]; // Allocate dynamically sized array
        if (!array) {
            mtx.unlock(); // Unlock the mutex
            return res; 
        }

        std::copy(vec.begin(), vec.end(), array);

        int maxElement = *std::max_element(array, array + vec.size());
        auto lastMaxIt = std::find(res.array + vec.size() - 1, res.array - 1, maxElement);

        res.array = array;
        res.size = vec.size();
    }

    mtx.unlock(); // Unlock the mutex

    return res;
}
