# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ConfigHandler:
    def __init__(self, config_file):
        self.config_file = config_file
        self.checksum = None

    @lru_cache(maxsize=None) # Cache the configuration file to speed up access
    def get_configuration(self):
        with open(self.config_file, 'r') as f:
            return f.read()

    def validate_checksum(self):
        checksum = md5(self.get_configuration().encode()).hexdigest()
        if self.checksum is None:  # First time
            self.checksum = checksum
        else:  # Compare with old checksum
            assert self.checksum == checksum, 'Configuration has been modified!'

    def update_config(self, new_config):
        logger.info('Updating configuration...')
        cmd = f'sed -i "/regex_to_replace/c\\{new_config}" {self.config_file}'
        start_time = time.time()

        try:
            subprocess.check_call(cmd, shell=True)
        except subprocess.CalledProcessError as e:
            logger.error('Update failed with sed command: %s', str(e))

        self.validate_checksum()  # Validate the checksum after update to ensure correct updates
        logger.info('Updating took %s seconds', time.time() - start_time)
