// Initialization function
void initializeNode(int NODE_ID, const char* STORAGE_TYPE, size_t CAPACITY) {
    pthread_mutex_lock(&lock);  // Lock to prevent race conditions

    nodes = realloc(nodes, sizeof(*nodes) * (num_nodes + 1)); // Increase array size by one
    if (!nodes) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);  // Unlock on error
        return;
    }

    NodeConfig* newNode = malloc(sizeof(*newNode)); // Allocate new node config
    if (!newNode) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);  // Unlock on error
        return;
    }

    newNode->NODE_ID = NODE_ID;
    newNode->STORAGE_TYPE = strdup(STORAGE_TYPE);
    if (!newNode->STORAGE_TYPE) {
        perror("Failed to allocate memory");
        free(newNode); // Free allocated memory on error
        pthread_mutex_unlock(&lock);  // Unlock on error
        return;
    }

    newNode->CAPACITY = CAPACITY;
    nodes[num_nodes++] = newNode; // Add new node to array and increment count

    pthread_mutex_unlock(&lock);  // Unlock after successful addition
}
