    int trailer;
} MAC_Trailer;

typedef struct {
    MAC_Header mac_header;
    char data[MAX_ARRAY];
    MAC_Trailer mac_trailer;
} MAC_PDU;

unsigned int calculateChecksum(char* data, size_t len) {
    unsigned int checksum = 0;
    for (size_t i=0; i < len; ++i) {
        checksum += CHECKSUM_MULTIPLIER * data[i];
    }
    return checksum;
}

void initializePDUArray(MAC_PDU* pdu_array, int arraySize, char* data, size_t len, int verify) {
    if (pdu_array == NULL || data == NULL) {
        printf("Null pointer error!\n");
        return;
