// Simplified TCP header and flag model
typedef struct {
    unsigned short source_port;
    unsigned short dest_port;
    unsigned int sequence_number;
    unsigned int ack_number;
    // other fields...
} TCP_Header;

typedef struct {
    unsigned char NS : 1;
    unsigned char CWR: 1;
    unsigned char ECE: 1;
    unsigned char URG: 1;
    unsigned char ACK: 1;
    unsigned char PSH: 1;
    unsigned char RST: 1;
    unsigned char SYN: 1;
    unsigned char FIN: 1;
} TCP_Flags;

typedef struct {
    unsigned int checksum; // pseudo-header based checksum
    unsigned short len;   // length of data
    void* data;           // pointer to actual data
} TCP_Data;

typedef struct {
    TCP_Header header;
    TCP_Flags flags;
    TCP_Data data;
} TCP_Packet;

// Custom checksum algorithm implementation (very simplified)
unsigned int checksum(void* buf, size_t len) {
    unsigned short* ptr = buf;
    unsigned long sum = 0;

    while (len > 1) {
        sum += *ptr++;
        len -= 2;
    }

    if (len > 0) {
        sum += *(unsigned char*)ptr;
    }

    while (sum >> 16) {
        sum = (sum & 0xffff) + (sum >> 16);
    }

    return ~sum;
}

// Function to initialize and populate the TCP_Packet array
TCP_Packet* init_packets(int num_packets, int data_len, int verifyMode, unsigned short src_port, 
                        unsigned short dest_port, unsigned int seq_num, unsigned int ack_num, 
                        unsigned char flags) {
    TCP_Packet* packets = malloc(sizeof(TCP_Packet) * num_packets);

    for (int i = 0; i < num_packets; ++i) {
        // Initialize header and data
        packets[i].header.source_port = src_port;
        packets[i].header.dest_port = dest_port;
        packets[i].header.sequence_number = seq_num + i;
        packets[i].header.ack_number = ack_num;

        packets[i].data.len = data_len;
        packets[i].data.data = malloc(data_len);

        // Set flags
        memcpy(&packets[i].flags, &flags, sizeof(TCP_Flags));

        // Calculate checksum (including pseudo-header)
        unsigned char* pkt_buf = malloc(sizeof(TCP_Packet));
        memcpy(pkt_buf, &packets[i], sizeof(TCP_Packet));
        packets[i].data.checksum = checksum(pkt_buf, sizeof(TCP_Header) + data_len);

        if (verifyMode && i > 0) { // Verify integrity of checksums for all but the first packet
            unsigned int expected_sum = packets[i-1].data.checksum;

            if (packets[i].data.checksum != expected_sum) {
                printf("Checksum verification failed at index %d!\n", i);

                // Handle error or take appropriate action here...
            }
        }
    }

    return packets;
}
```
Please note, this is a very simplified model of TCP protocol and checksum algorithm. In reality, the actual checksum calculation requires careful handling of byte order and padding as per RFC 793 (Transmission Control Protocol). Also, in high-throughput scenarios, it would be more efficient to allocate memory for packet data all at once rather than each time a new packet is created.
