    char CRCFLAG; // assuming a character for simplicity
} CRC_INDICATION_REL8_TAG;

NFAPI_CRC_INDICATION_PDU_T* create_structures(int N) {
    srand((unsigned int)time(NULL)); 
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(pdu == NULL) {
        printf("Error: Out of memory\n");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pdu[i].crc = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));

        if(pdu[i].crc == NULL) {
            printf("Error: Out of memory\n");

            // Free already allocated structures in case of insufficient memory error
            for (int j = 0; j < i; ++j) 
                free(pdu[j].crc);

            free(pdu);
            return NULL;
        }

        pdu[i].RX_UE_INFORMATION_TAG = i; // Set any valid value here
        pdu[i].RNTI = i; // Set any valid value here
        pdu[i].crc->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    printf("Memory allocated for %d structures\n", N);
    return pdu;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T *pdu, int N) {
