  unsigned int checksum;
} MAC_Trailer;

typedef struct {
  MAC_Header mac_header;
  MAC_Trailer mac_trailer;
} MAC_PDU;

// Circular buffer definition
#define BUFFER_SIZE 1024 // Adjust according to your needs
MAC_PDU circularBuffer[BUFFER_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int head = 0, tail = 0;
unsigned int count = 0;

// Function prototypes
void push(MAC_PDU pdu);
MAC_PDU pop();
void generateChecksum(MAC_PDU *pdu);
char* getMD5HashOfFilename(const char* filename);
int validateCheckSum(MAC_PDU pdu, unsigned int expectedCheckSum);
void threadSafeInitAndPopulateMacPduArray(const char* filename);

// Main function to initialize and populate the buffer
void threadSafeInitAndPopulateMacPduArray(const char* filename) {
  // Handle errors for NULL pointers or large filenames (>255 chars)
  if (!filename || strlen(filename) > 255) {
    printf("Invalid filename\n");
    return;
  }

  FILE *file = fopen(filename, "r"); // Open the file in read mode

  // Error handling for invalid files or permissions
  if (file == NULL) {
    printf("Error opening file\n");
    return;
  }

  char buffer[1024];
  while (fgets(buffer, sizeof(buffer), file)) {
    MAC_PDU pdu;

    // Populate the pdu with data from the file
    strcpy(pdu.mac_header.header, buffer);
    generateChecksum(&pdu);
    push(pdu);
  }

  fclose(file); // Close the file after use
}

// Push operation with thread safety
void push(MAC_PDU pdu) {
  pthread_mutex_lock(&mutex);
  circularBuffer[head] = pdu;
  head = (head + 1) % BUFFER_SIZE;
  count++;
  pthread_mutex_unlock(&mutex);
}

// Pop operation with thread safety
MAC_PDU pop() {
  MAC_PDU result;

  pthread_mutex_lock(&mutex);
  if(count != 0) {
    result = circularBuffer[tail];
    tail = (tail + 1) % BUFFER_SIZE;
    count--;
  } else {
    printf("Buffer is empty\n");
  }
  pthread_mutex_unlock(&mutex);

  return result;
}

// Generate checksum function - place your custom checksum algorithm here
