['Here is a simplified example for creating such a system in Java using SLF4J and Logback as logging framework and Spring Boot for microservices architecture. 

```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.core.util.StatusPrinter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@SpringBootApplication
public class Application {
     private static final Logger logger = LoggerFactory.getLogger(Application.class);

     @Autowired
     private MyService myService;

     public static void main(String[] args) {
         SpringApplication.run(Application.class, args);
     }

     @Bean
     public CommandLineRunner commandLineRunner() {
          return args -> {
               logger.debug("Debugging log");
               logger.info("Info log");
               logger.warn("Warn log");
               logger.error("Error log");

               myService.doWork();

               // print internal state of logback
               LoggerContext lc = (LoggerContext) LoggerFactory.getILoggerFactory();
               StatusPrinter.print(lc);
          };
     }

     @Bean("taskExecutor")
     public ThreadPoolTaskExecutor taskExecutor() {
         ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
         executor.setCorePoolSize(4);
         executor.setMaxPoolSize(4);
         executor.setQueueCapacity(100);
         executor.setThreadNamePrefix("LoggingThread-");
         executor.initialize();
         return executor;
     }
}

@Service
public class MyService {
    private static final Logger logger = LoggerFactory.getLogger(MyService.class);

    @Autowired
    private ApplicationContext applicationContext;

    public void doWork() {
        for (int i = 0; i < 10; ++i) {
            new Thread(() -> {
                logger.info("This is log from another thread.");
                if (Thread.currentThread().getState() == Thread.State.RUNNABLE) {
                    applicationContext.publishEvent(new LoggingEvent());
                }
            }).start();
        }
    }
}

@Aspect
public class LoggingAspect {
     private static final Logger logger = LoggerFactory.getLogger(LoggingAspect.class);

     @Around("execution(* org.springframework..*.*(..))") // Pointcut expression
     public Object logAroundAllMethods(ProceedingJoinPoint joinPoint) throws Throwable {
          logger.info("Enter: {}.{}() with argument[s] = {}", joinPoint.getSignature().getDeclaringTypeName(),
              joinPoint.getSignature().getName(), Arrays.toString(joinPoint.getArgs()));
          try {
               Object result = joinPoint.proceed();
               logger.info("Exit: {}.{}() with result = {}", joinPoint.getSignature().getDeclaringTypeName(),
                  joinPoint.getSignature().getName(), result);
               return result;
          } catch (IllegalArgumentException e) {
               logger.error("Illegal argument: {} in {}.{}()", Arrays.toString(joinPoint.getArgs()),
                    joinPoint.getSignature().getDeclaringTypeName(), joinPoint.getSignature().getName());
               throw e;
          }
     }
}

@Configuration
public class LoggingConfig {
    @Bean
    public MetricsReporter metricsReporter(MeterRegistry registry) {
        return new MetricsReporter(registry);
    }

    @EventListener
    public void onApplicationEvent(LoggingEvent event) {
         // handle the event and generate metrics or alerts based on the event
    }
}
```
This is a simple representation of how it can be done. There are many aspects that needs to be considered while creating such a system which includes proper management of external dependencies, exception handling, unit testing, code modularity etc., These aspects have not been covered in this example due to the complexity and length of the implementation.
