unsigned char* calcMD5Hash(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL; // Handle error here.

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5_Init(&mdContext);
    while ((bytes = fread(data, 1, 1024, file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }
    MD5_Final(digest, &mdContext);

    unsigned char *hashStr = malloc((MD5_DIGEST_LENGTH*2)+1); 
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hashStr[i*2], "%02x", (unsigned int)digest[i]);
    }

    fclose(file);
    return hashStr;
}
```
This function calculates the MD5 checksum of a file by reading its content in chunks, updating the hash context with each chunk and finally returns a string representation of the digest. 

