        if (regexec(&regexCompiled, text, 1, matchesFound, 0) == 0) {
            int start = matchesFound[0].rm_so;
            int end = matchesFound[0].rm_eo;

            char* matchStr = malloc(end - start + 1);
            strncpy(matchStr, text + start, end - start);
            matchStr[end - start] = '\0';

            matches[i] = matchStr;  // Save the match in array
        } else {
            matches[i] = NULL;  // If no match found save NULL
        }

        regfree(&regexCompiled);
    }

