```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct ACL {
    int userID;
    char permissions[3]; // rwx format (e.g., "rw-")
} ACL;

typedef struct FileAccessManager {
    pthread_mutex_t lock;
    sem_t accessCounterSemaphore;
    int accessCount;  // successful access attempts
    int failCount;     // failed access attempts
    int auditMode;
    FILE* logFile;
} FileAccessManager;

// Initialize a new file access manager
void initializeFAM(FileAccessManager* fam) {
    pthread_mutex_init(&fam->lock, NULL);
    sem_init(&fam->accessCounterSemaphore, 0, 1);
    fam->accessCount = 0;
    fam->failCount = 0;
    fam->auditMode = 0; // default is off
    if (fam->auditMode) {
        fam->logFile = fopen("accessLog.txt", "a");  // open log file in append mode
    }
}

// Dynamically add user permissions to the ACL
void addPermission(ACL* acl, int userID, char permissions[3]) {
    pthread_mutex_lock(&fam.lock);  // acquire lock
    sem_wait(&fam.accessCounterSemaphore);  
    ++fam.accessCount;
    sem_post(&fam.accessCounterSemaphore);
    acl->userID = userID;
    for (int i = 0; i < 3; ++i) {
        acl->permissions[i] = permissions[i];
    }
    pthread_mutex_unlock(&fam.lock); // release lock
}

// Remove existing user's permissions from the ACL
void removePermission(ACL* acl, int userID) {
    pthread_mutex_lock(&fam.lock);  // acquire lock
    sem_wait(&fam.accessCounterSemaphore);  
    ++fam.accessCount;
    sem_post(&fam.accessCounterSemaphore);
    acl->userID = 0;
    for (int i = 0; i < 3; ++i) {
        acl->permissions[i] = '-';
    }
    pthread_mutex_unlock(&fam.lock); // release lock
}
```
This code represents the core of how you might implement a system for managing access permissions and logging information in C. However, it is not meant to be a complete solution to the problem as stated above but rather a starting point with some basic thread-safe operations on an ACL and maintaining audit mode. The actual implementation would be much more complex, involving additional error handling code, more advanced synchronization primitives (such as condition variables), system calls for various file operations, integration of multiple file systems, etc.
