int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s [directory]\n", argv[0]);
        return 1;
    }

    DIR* dir = opendir(argv[1]);
    if (!dir) {
        printf("Error opening directory: %s\n", strerror(errno));
        return 1;
    }

    pthread_t threads[50]; // Up to 50 files can be processed concurrently
    int threadCount = 0;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // If the file is a regular file
            const char* path = entry->d_name;

            // Start a new thread to process this file
            pthread_create(&threads[threadCount++], NULL, &processFile, (void*)path);
