from collections import defaultdict
from cryptography.fernet import Fernet

# Set up logging
logging.basicConfig(filename='app.log', filemode='w', level=logging.DEBUG, format='%(asctime)s - %(message)s')

def replace_placeholders(config_file, json_config):
    try:
        with open(config_file, 'r+') as file:
            config = file.read()

            # Create backup before making changes
            with open('backup.txt', 'w') as backup:
                backup.write(config)

            for placeholder, value in json_config.items():
                if placeholder not in config:
                    logging.error(f"Unprocessed placeholder {placeholder}")
                else:
                    config = config.replace(placeholder, value, 1)

            # Generate encrypted password and store it in an environment variable
            key = Fernet.generate_key()
            cipher_suite = Fernet(key)

            password = os.environ['PASSWORD']
            encrypted_password = cipher_suite.encrypt(bytes(password, 'utf-8'))  # Encryption may fail for certain characters
            config += f"\n{encrypted_password}"

            file.seek(0)
            file.write(config)
    except PermissionError:
        logging.exception("Permission denied while replacing placeholders")
        restore_backup()  # Restore backup if operation fails
    except IOError:
        logging.exception("I/O error while replacing placeholders")
        restore_backup()  # Restore backup if operation fails

def restore_backup():
    try:
        with open('backup.txt', 'r') as backup, open(config_file, 'w') as file:
            file.write(backup.read())
    except FileNotFoundError:
        logging.exception("Backup file not found")

def pokemon_weaknesses():
    weaknesses = defaultdict(lambda: "Unknown type", {
        "Fire": ["Water"], 
        "Grass": ["Fire", "Ice", "Flying"], 
        "Water": ["Grass", "Electric"]})

    try:
        with open('pokemon_weaknesses.json') as file:
            external_config = json.load(file)

            for pokemon_type, weakness in external_config.items():
                if isinstance(weakness, list):  # Check type of value
                    weaknesses[pokemon_type].extend(weakness)
    except json.JSONDecodeError:
        logging.exception("Failed to decode JSON file")

    def get_weaknesses(pokemon_types):
        results = []

        for pokemon_type in pokemon_types:
            try:
                results.extend(weaknesses[pokemon_type])
            except KeyError:
                logging.error(f"No weakness found for {pokemon_type}")

        return ", ".join(results)

    return get_weaknesses
```
