#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for stream configuration
typedef struct {
    int DEVICE_ID;
    char STREAM_TYPE[20];
    double DATA_RATE;
} StreamConfig;

// Global variables to manage streams and locks
StreamConfig **streams = NULL;
int num_streams = 0;
pthread_mutex_t stream_lock = PTHREAD_MUTEX_INITIALIZER;

void* configure_stream(void *arg) {
    StreamConfig *config = (StreamConfig*) arg;

    // Lock the stream and add new configuration
    pthread_mutex_lock(&stream_lock);
    num_streams++;
    streams = realloc(streams, sizeof(*streams) * num_streams);
    if (!streams) {
        perror("Failed to allocate memory for stream");
        exit(EXIT_FAILURE);
    }

    StreamConfig *new_config = malloc(sizeof(*new_config));
    memcpy(new_config, config, sizeof(*config));
    streams[num_streams - 1] = new_config;

    pthread_mutex_unlock(&stream_lock);

    return NULL;
}

void add_stream(int DEVICE_ID, char* STREAM_TYPE, double DATA_RATE) {
    // Create a new stream configuration
    StreamConfig *config = malloc(sizeof(*config));
    config->DEVICE_ID = DEVICE_ID;
    strncpy(config->STREAM_TYPE, STREAM_TYPE, sizeof(config->STREAM_TYPE) - 1);
    config->DATA_RATE = DATA_RATE;

    // Create a new thread to handle stream configuration
    pthread_t thread;
    if (pthread_create(&thread, NULL, configure_stream, config)) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    // Detach the thread as it's no longer needed after completion of work
    pthread_detach(thread);
}
```
This code only handles adding streams and configuring them dynamically. Actual implementation of a complete IoT system with error checking, data aggregation, monitoring mechanisms etc., would be significantly more complex and beyond the scope of this response.
