typedef struct { 
    int RX_UE_INFORMATION_TAG; 
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for passing data to threads
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **arrays;
    int start_index, end_index;
} thread_data_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long max_batch_size = 10000; // Default maximum batch size
int log_level = 2; // 0: none, 1: errors only, 2: info and above

void *populateStructures(void *threadarg) {
    thread_data_t *data = (thread_data_t *) threadarg;

    pthread_mutex_lock(&lock); // Lock to prevent other threads from interfering

    if(log_level >= 2) printf("Started processing batch %d-%d\n", data->start_index, data->end_index);

    for(int i = data->start_index; i < data->end_index; i++) {
        // Allocate memory and populate each structure
        NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (array == NULL) {
            if(log_level >= 1) printf("Failed to allocate memory for structure %d\n", i);
            continue;
        }

        // Populate the structure
        array->RX_UE_INFORMATION_TAG = rand(); 
        data->arrays[i] = array;
    }

    if(log_level >= 2) printf("Finished processing batch %d-%d\n", data->start_index, data->end_index);

    pthread_mutex_unlock(&lock); // Unlock to allow other threads in

    return NULL;
}

void processBatches(size_t total) {
    size_t batches = (total + max_batch_size - 1) / max_batch_size; // Calculate number of batches needed

    for(size_t b = 0; b < batches; b++) {
        size_t start = b * max_batch_size;
        size_t end = (b + 1) * max_batch_size > total ? total : (b + 1) * max_batch_size;

        pthread_t thread; // Create new thread for each batch
        thread_data_t data = {.arrays = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*)*max_batch_size), .start_index = start, .end_index = end};

        if (pthread_create(&thread, NULL, populateStructures, &data)) {
            if(log_level >= 1) printf("Failed to create thread for batch %ld\n", b);
            continue;
        }
    }
}
