#include <dirent.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/md5.h>

typedef struct {
    char** lines;
    int line_count;
    size_t max_line_size;
} FileContent;

void processDirectoryContent(const char *directoryPath, const char *extension) {
    DIR* directory = opendir(directoryPath);
    if (directory == NULL) {
        printf("Could not open directory %s\n", directoryPath);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(directory)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strcmp(entry->d_name + strlen(entry->d_name) - strlen(extension), extension) != 0) {
            continue;
        }

        char filePath[PATH_MAX];
        snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

        // Check if the path is a regular file or a symbolic link to a regular file.
        struct stat st;
        if (stat(filePath, &st) == 0 && S_ISREG(st.st_mode)) {
            processFileContent(&entry->d_name);
        } else if (S_ISLNK(st.st_mode)) {
            char linkedPath[PATH_MAX];
            ssize_t len = readlink(filePath, linkedPath, sizeof(linkedPath) - 1);
            if (len != -1) {
                linkedPath[len] = 0;

                // Check if the linked path is a regular file.
                struct stat stLinked;
                if (stat(linkedPath, &stLinked) == 0 && S_ISREG(stLinked.st_mode)) {
                    processFileContent(&entry->d_name);
                }
            }
        }
    }

    closedir(directory);
