#include <stdio.h>
#include <pthread.h>

// Structure for passing data to threads
typedef struct {
    char *filename;
} thread_data_t;

void* processFile(void *arg) {
   // Cast the void pointer back to the desired type
   thread_data_t *input = (thread_data_t *) arg;

   FILE *file = fopen(input->filename, "r");
   if (file == NULL) {
       printf("Unable to open file %s\n", input->filename);
       pthread_exit(NULL);
   }

   int c;
   while ((c = getc(file)) != EOF) {
        // Process file line by line
   }

   fclose(file);
   pthread_exit(NULL);
}

int main(int argc, char **argv) {
    if (argc < 2) {
       printf("Usage: ./program <file1> <file2> ...\n");
       return 1;
    }

    pthread_t threads[argc - 1]; // Create a thread for each file
    thread_data_t data[argc - 1]; // Data to pass to each thread
    int i, rc;
    for (i = 0; i < argc - 1; ++i) {
        data[i].filename = argv[i + 1];
        rc = pthread_create(&threads[i], NULL, processFile, &data[i]); // Create a thread

        if (rc){
           printf("ERROR: return code from pthread_create() is %d\n", rc);
           exit(-1);
        }
    }

    for(i = 0; i < argc - 1; ++i) { // Wait for all threads to finish
        (void) pthread_join(threads[i], NULL);
    }

    return 0;
}
```
In this sample, the main function creates a separate thread for each file provided as a command line argument. The `processFile` function is executed by each thread and reads the corresponding file line by line.

