    except FileNotFoundError:
        logging.error('File not found: %s', filepath)
        raise
    except json.JSONDecodeError:
        logging.error('Invalid JSON format in file: %s', filepath)
        raise

def replace_placeholders(config_file, placeholders):
    for placeholder, value in placeholders.items():
        try:
            subprocess.run(['sed', '-i.bak', 's|' + placeholder + '|' + str(value) + '|g', config_file], check=True)
        except subprocess.CalledProcessError as e:
            logging.error('Failed to replace placeholders in file %s. Error: %s', config_file, str(e))
    try:
        with open(config_file + '.bak', 'r') as original: data = original.read()
        with open(config_file, 'w') as modified: modified.write(data)
    except Exception as e:
        logging.error('Failed to restore backup file for %s. Error: %s', config_file, str(e))

def encrypt_password():
    password = os.environ['PASSWORD']
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
