struct HashTable {
    pthread_mutex_t lock;
    struct hash_node **nodes;
    int size, count;
};

static unsigned long djb2(unsigned char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

static struct HashTable *HashTable_create(int size) {
    assert(size > 0);

    struct HashTable *table = malloc(sizeof(*table));
    if (!table)
        return NULL;

    table->nodes = calloc(size, sizeof(*table->nodes));
    if (!table->nodes) {
        free(table);
        return NULL;
    }

    table->size = size;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

static void HashTable_insert(struct HashTable *table, int RNTI, NFAPI_CRC_INDICATION_PDU_T *structure) {
    unsigned long index = djb2((unsigned char*)&RNTI) % table->size;

    pthread_mutex_lock(&table->lock);
    ++table->count;
    if (table->nodes[index]) {
        // Handle collision here
    } else {
        struct hash_node *node = malloc(sizeof(*node));

        node->RNTI = RNTI;
        node->structure = structure;
        table->nodes[index] = node;
    }
    pthread_mutex_unlock(&table->lock);
}

static NFAPI_CRC_INDICATION_PDU_T *HashTable_search(struct HashTable *table, int RNTI) {
    unsigned long index = djb2((unsigned char*)&RNTI) % table->size;

    pthread_mutex_lock(&table->lock);
    struct hash_node *node = table->nodes[index];

    while (node && node->RNTI != RNTI) 
        node = node->next;

    pthread_mutex_unlock(&table->lock);

    return node ? node->structure : NULL;
}

static void HashTable_delete(struct HashTable *table, int RNTI) {
    unsigned long index = djb2((unsigned char*)&RNTI) % table->size;

    pthread_mutex_lock(&table->lock);
    struct hash_node *node = table->nodes[index];

    while (node && node->RNTI != RNTI) 
        node = node->next;

    if(node) {
       free(node->structure);
       free(node);
       --table->count;
    }

    pthread_mutex_unlock(&table->lock);
}

static void HashTable_destroy(struct HashTable *table) {
    if (!table)
        return;

    for (int i = 0; i < table->size; ++i) 
        while (table->nodes[i]) 
            HashTable_delete(table, table->nodes[i]->RNTI);

    free(table->nodes);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

