#include <stdlib.h>
#include <time.h>
#include <assert.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* new_node(int data) {
    Node* node = (Node*)malloc(sizeof(Node));
    assert(node != NULL);

    node->data = data;
    node->next = NULL;

    return node;
}

void append_node(Node** head, int data) {
    Node* new_element = new_node(data);

    if (*head == NULL) {
        *head = new_element;
        return;
    }

    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_element;
}
```
