typedef struct {
    void *addr;
    size_t size;
} AllocationLogEntry;

AllocationLogEntry allocationLog[MAX_MEMORY / (NFAPI_CRC_INDICATION_PDU_T_SIZE/2)]; // Each entry uses half of the memory.
int logIndex = 0;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void *allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure.
        exit(1);
    }
    pthread_mutex_lock(&logMutex);
    allocationLog[logIndex].addr = ptr;
    allocationLog[logIndex].size = size;
    logIndex++;
    pthread_mutex_unlock(&logMutex);
    return ptr;
}

void freeMemory(void *ptr) {
    for (int i = 0; i < logIndex; ++i) {
        if (allocationLog[i].addr == ptr) {
            allocationLog[i].size = 0; // Mark as freed.
            break;
        }
    }
    free(ptr);
}

int validateStructure(NFAPI_CRC_INDICATION_PDU_T *pdu, int size){
