['Here is an example of how you might approach this task in C using pthread for thread safety, time.h for tracking age and mallinfo() for checking memory usage. Please note that actual implementation would require a more thorough understanding of your project requirements.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <malloc.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;  // for simplicity, assume this is an integer
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t creationTime;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryLog {
    void *address;
    size_t size;
    struct MemoryLog *next;
} MemoryLog;

MemoryLog *allocatedBlocks = NULL;
pthread_mutex_t lock;

void* allocateMemory(size_t n, size_t size) {
    void *ptr = malloc(n * size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);  // or handle it in another way based on your requirements.
    }

    pthread_mutex_lock(&lock);
    MemoryLog *newBlock = (MemoryLog*) malloc(sizeof(MemoryLog));
    newBlock->address = ptr;
    newBlock->size = n * size;
    newBlock->next = allocatedBlocks;
    allocatedBlocks = newBlock;
    pthread_mutex_unlock(&lock);

    return ptr;
}

void freeMemory(void* ptr) {
    pthread_mutex_lock(&lock);
    MemoryLog *prev = NULL;
    for (MemoryLog *curr = allocatedBlocks; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->address == ptr) {
            if (prev == NULL) {  // block to free is the first in the list.
                allocatedBlocks = curr->next;
            } else {
                prev->next = curr->next;
            }
            free(curr);
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    free(ptr);
}

void* checkMemoryLeaks() {
    struct mallinfo info = mallinfo();
    printf("Total allocated space: %d\n", info.arena);  // Total space allocated from system.
    printf("In use memory space: %d\n", info.uordblks);  // Approximate total allocated space (including overhead).
}

void reclaimMemory(time_t threshold) {
    pthread_mutex_lock(&lock);
    MemoryLog *prev = NULL;
    for (MemoryLog *curr = allocatedBlocks; curr != NULL; ) {
        if (difftime(time(NULL), curr->creationTime) > threshold) {
            // Reclaim memory.
            freeMemory(curr->address);

            MemoryLog *next = curr->next;  // Save the next block before we free the current one.
            if (prev == NULL) {  // If it was first in list.
                allocatedBlocks = next;
            } else {
                prev->next = next;
            }

            free(curr);  // Free current memory log entry as we're done with it.
            curr = next;  // Move to the next one.
        } else {
            prev = curr;  // Remember this block, move to the next one.
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
This code does not validate structure fields or handle allocation failure in a more graceful way as it would require additional information about what you consider to be an invalid `RX_UE_INFORMATION_TAG`, `RNTI`, and `CRC_INDICATION_REL8_TAG`.
