['```python
import json
import subprocess
from concurrent.futures import ThreadPoolExecutor

def replace_template(filepath):
    with open('config.json', 'r') as config_file:
        config = json.load(config_file)

    for key, value in config['variables'].items():
        try:
            subprocess.run(['sed', '-i', f's/{key}/{value}/g', filepath], check=True)
        except subprocess.CalledProcessError as e:
            print(f"Failed to replace template variable in {filepath}: {str(e)}")

def add_dns_server(filepath):
    with open('config.json', 'r') as config_file:
        config = json.load(config_file)

    for server in config['dns_servers']:
        try:
            subprocess.run(['awk', f'1;/DNS_SERVERS/{print $0}END{print \"DNS_SERVERS\",\"{server}\"}/' , filepath], check=True)
        except subprocess.CalledProcessError as e:
            print(f"Failed to add DNS server in {filepath}: {str(e)}")

def validate_network(filepath):
    try:
        subprocess.run(['grep', '-q', '^DNS_SERVERS', filepath], check=True)
    except subprocess.CalledProcessError as e:
        print(f"Failed to validate network settings in {filepath}: {str(e)}")

def configure_network(filepath):
    with ThreadPoolExecutor() as executor:
        executor.submit(replace_template, filepath)
        executor.submit(add_dns_server, filepath)
        executor.submit(validate_network, filepath)
``` 

Please make sure that the 'config.json' contains the variables and DNS servers you want to replace in the files. Also, the `awk` command is not tested because it's a bit complex to use with Python subprocess, you might need to adjust it according to your needs.
