typedef struct Node {
    LTE_RRC_CCO_MSG_T data;
    struct Node* next;
} Node;

Node* head = NULL;  // Head of the linked list.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t lastSyncTime = 0;
int rateLimitInterval = 1000;  // in milliseconds

void insert(LTE_RRC_CCO_MSG_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    newNode->data = data;
    pthread_mutex_lock(&lock);  // Lock the critical section to avoid race conditions.
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);  // Unlock after modification.
}

void syncWithDB() {
    time_t currentTime = clock();
    if ((currentTime - lastSyncTime) >= rateLimitInterval) {
        lastSyncTime = currentTime;
        pthread_mutex_lock(&lock);  // Lock before accessing shared data.
        Node* temp = head;
        while(temp != NULL) {
            /* Synchronize with DB here and update necessary fields */
            temp = temp->next;
        }
        pthread_mutex_unlock(&lock);  // Unlock after accessing shared data.
    }
}
