["Here's an example of how you could implement this using C and POSIX threads (pthread). Please note that this code is simplified for demonstration purposes and doesn't include actual error handling or specific details about the NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG structs.

```c
#include <pthread.h>
#include <stdlib.h>
#define MAX_ENTRIES 1000

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct node* next;
} Node;

typedef struct hash_table {
    pthread_mutex_t lock;
    Node** table;
    int size;
    int entries;
    int removed;
    int added;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* h = malloc(sizeof(HashTable));
    if (!h) return NULL;
    h->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    h->table = calloc(size, sizeof(Node*));
    if (!h->table) {
        free(h);
        return NULL;
    }
    h->size = size;
    h->entries = 0;
    h->removed = 0;
    h->added = 0;
    return h;
}

void destroy_hash_table(HashTable* h) {
    for (int i = 0; i < h->size; ++i) {
        Node* node = h->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&h->lock);
    free(h);
}

unsigned int hash(int key, int size) {
    return (key % size + size) % size;
}

void add_to_hash_table(HashTable* h, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (h->entries >= MAX_ENTRIES) return;
    pthread_mutex_lock(&h->lock);
    int index = hash(data->RNTI, h->size);
    Node** node = &h->table[index];
    while (*node && (*node)->data->RNTI != data->RNTI) {
        node = &(*node)->next;
    }
    if (!*node) {
        ++h->entries;
        ++h->added;
        *node = malloc(sizeof(Node));
        (*node)->data = data;
        (*node)->next = NULL;
    } else {
        free((*node)->data);
        (*node)->data = data;
    }
    pthread_mutex_unlock(&h->lock);
}

void remove_from_hash_table(HashTable* h, int key) {
    int index = hash(key, h->size);
    pthread_mutex_lock(&h->lock);
    Node** node = &h->table[index];
    while (*node && (*node)->data->RNTI != key) {
        node = &(*node)->next;
    }
    if (*node) {
        --h->entries;
        ++h->removed;
        Node* temp = *node;
        *node = (*node)->next;
        free(temp);
    }
    pthread_mutex_unlock(&h->lock);
}
```
This code provides a basic hash table with locking for thread safety. The `hash` function calculates the index into the array based on the key value modulo the size of the array, ensuring that we don't go out of bounds and causing undefined behavior. We use a simple linear probing strategy to handle collisions, meaning if a collision occurs, we check the next bucket until we either find an empty spot or a match.

The `add_to_hash_table` function adds new items to the table. If an item with the same key already exists, it updates the existing item instead of adding a duplicate. This is done by freeing the old data and replacing it with the new one. 

The `remove_from_hash_table` function removes items from the hash table based on their key value. It works similarly to `add_to_hash_table`, checking each bucket for a match until either finding an empty spot (in which case no action is taken) or finding a matching item and removing it. 

The counters `h->entries`, `h->removed`, and `h->added` are incremented in the respective functions to track statistics about the number of entries added, removed, and updated. These can be accessed after the fact to get these stats. The function `destroy_hash_table` is used to clean up memory when the hash table is no longer needed.
