#include <stdio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

void safe_file_writer(FILE *file, char *buffer, size_t length, int append) {
    if (file == NULL || buffer == NULL || length == 0) return;  // null check and early return for invalid inputs

    time_t currentTime = time(NULL);                       // get the current timestamp
    unsigned checksum = 0;                                 // calculate a simple checksum of the data
    for (size_t i=0; i<length; i++) {
        checksum += buffer[i];
    }

    char metadata[1024] = "";                            // format the header with timestamp, length, and checksum
    snprintf(metadata, 1024, "Timestamp: %ld, Length: %zu, Checksum: %u", currentTime, length, checksum);

    if (append) {                                         // write to file depending on append flag
        fwrite(buffer, sizeof(char), length, file); 
    } else {
        fseek(file, 0L, SEEK_END);                         // set the file position indicator to end of the file
        fprintf(file, "%s%.*s", metadata, (int)length, buffer);   // write the header and data
    }
}
```
