['Here is an implementation in C using doubly linked list (DLL). This code doesn't cover everything you asked for but it's a start point. It includes basic structures, DLL operations, error checking and logging mechanism. For the remaining functionalities like thread-safety, real-time data processing, validation mechanism, automatic archiving, logging etc., libraries like pthread (for threading), syslog (for logging) are usually used which are platform dependent.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

typedef struct RX_UE_INFORMATION_TAG {
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    double TIMESTAMP;
    double TRANSMISSION_POWER;
    double RECEPTION_QUALITY;
} RX_UE_INFORMATION_TAG;

typedef struct QNode {
   struct QNode *prev, *next;
   RX_UE_INFORMATION_TAG data; 
}QNode;

typedef struct Queue {
    pthread_mutex_t mutex;
    int count;  
    int limit;    
    QNode *front, *rear; 
}Queue;

static QNode* newNode(RX_UE_INFORMATION_TAG k) {
    QNode* temp = (QNode*)malloc(sizeof(QNode));
    if(!temp){
        syslog(LOG_ERR, "Memory allocation failed\n");
        return NULL; 
    }
    temp->data = k;
    temp->prev = temp->next = NULL;
    return temp;
}

Queue* createQueue(int limit) {
   Queue* q = (Queue*)malloc(sizeof(Queue));
   if(!q){
        syslog(LOG_ERR, "Memory allocation failed\n");
        return NULL; 
   }
    q->limit = limit;
    q->count = 0;
    q->front = q->rear = NULL;

    if (pthread_mutex_init(&q->mutex, NULL) != 0){
        syslog(LOG_ERR, "Mutex init failed\n");
        return NULL; 
    }
   return q;
}

void enQueue(Queue* q, RX_UE_INFORMATION_TAG k) {
    pthread_mutex_lock(&q->mutex);
    QNode* temp = newNode(k);
    if(!temp){
        syslog(LOG_ERR, "Failed to create node\n");
        return; 
    }

    if (q->rear == NULL) {
        q->front = q->rear = temp;
        q->count++;
        pthread_mutex_unlock(&q->mutex);
        return;
    }

    if(q->limit != -1 && q->count >= q->limit){
        syslog(LOG_INFO, "Queue limit exceeded. Discarding oldest entry\n");
        deQueue(q);
    }

    temp->next = q->front;
    if (q->front != NULL)
       q->front->prev = temp;

    q->front = temp;
    q->count++;
    pthread_mutex_unlock(&q->mutex);
}

void deQueue(Queue* q){
    pthread_mutex_lock(&q->mutex);
    if (q->rear == NULL) {
        syslog(LOG_ERR, "Queue is empty\n");
        return; 
    }  

    QNode* temp = q->rear;
    q->rear = q->rear->prev;
    if (q->rear)
       q->rear->next = NULL;

    free(temp);

    q->count--; 
    pthread_mutex_unlock(&q->mutex);
}

```
Please note that it is a basic example and may need to be extended, optimized or adjusted according to your requirements. The provided code might not be directly compilable as it doesn't contain the entire system, but it serves as an illustrative base for your problem.
