void process_file_and_data(const std::string& filename, size_t N, std::fstream* file) {
    srand(time(0)); // Initialize random seed

    int rnd = rand() % 100 + 1; // Generate a number between 1 and 100
    time_t now = time(NULL); // Get current time
    struct tm* ptm = localtime(&now);
    char buffer[32];
    strftime (buffer, 32, "%Y%m%d%H%M%S", ptm); // Format current date and time into a string

    std::string new_filename = filename + "_" + buffer + "_" + std::to_string(rnd) + ".txt";

    if (isalpha(new_filename[0]) || isdigit(new_filename[0])) {
        file->open(new_filename, std::ios::out); // Open the new file for writing

        Data* data = new Data[N];  // Allocate memory for N data structures

        for (size_t i = 0; i < N; ++i) {
            data[i].a = rand() % 10 + 1;   // Populate the structure with random values
            data[i].b = static_cast<double>(rand()) / RAND_MAX;
            data[i].c = "Some string";
