        for (size_t i = 0; i < N; ++i) { // Write to the file
            *file << data[i].a << ',' << data[i].b << ',' << data[i].c << '\n';
        }

        delete[] data; // Deallocate the memory
    } else {
        std::cerr << "The filename must start with an alphabetic character or a digit." << std::endl;
    }
}
