use reqwest::Client;
use std::io::Result;
use openssl::ssl::{SslConnector, SslMethod};
use native_tls::TlsConnector;

pub fn create_http_client(url: &str, disable_certificate_validation: bool) -> Result<Client> {
    let mut ssl = if disable_certificate_validation {
        // Disable certificate validation
        SslConnector::builder(SslMethod::tls()).unwrap()
    } else {
        // Use default settings for SSL connector
        ClientTlsConnector::new().unwrap()
    };

    ssl.set_native_roots();

    let client = reqwest::Client::builder()
        .ssl(ssl)
        .build()?;

    Ok(client)
}
```
