main.rs:
```rust
extern crate reqwest;
extern crate log;
extern crate env_logger;
extern crate lazy_static;
use std::io::Write;
use std::fs::File;
use std::env;
use std::sync::Mutex;

struct Logger(log::LevelFilter);
impl log::Log for Logger {
    fn enabled(&self, metadata: &log::Metadata) -> bool {
        metadata.level() <= self.0
    }

    fn log(&self, record: &log::Record) {
        if self.enabled(record.metadata()) {
            printlnfmt![
                "{} - {}", 
                record.level(), 
                record.args()
            ]
        }
    }

    fn flush(&self) {}
}

lazy_static::lazy_static![
    static ref LOGGER: Mutex<Logger> = Mutex::new(Logger(log::LevelFilter::Info)),
];

pub struct HttpClient {
    client: reqwest::Client,
}

impl HttpClient {
    pub fn new() -> Result<Self, reqwest::Error> {
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert(reqwest::header::CONTENT_TYPE, reqwest::header::HeaderValue::from_static("application/json"));

        let client = reqwest::Client::builder()
            .default_headers(headers)
            .danger_accept_invalid_certs(true) // for disabling certificate validation
            .build()?;

        Ok(HttpClient { client })
    }

    pub fn get(&self, url: &str) -> Result<reqwest::Response, reqwest::Error> {
        let res = self.client.get(url).send()?;

        LOGGER.lock().unwrap().log(LOG_LEVEL_INFO, "GET", format_args!"{} {}", url, res);

        Ok(res)
    }
}
```
