#include <stdlib.h>

typedef struct MAC_RX_CONTEXT {
    uint32_t mac_rx_id;
    void* l2_context;  // Assuming L2_CONTEXT is an opaque type
} MAC_RX_CONTEXT;

struct context_array {
    pthread_rwlock_t lock;
    MAC_RX_CONTEXT *data;
    size_t length, capacity;
};

// Initialize a context array. Returns 1 on success and 0 on failure.
int init_context_array(struct context_array *arr) {
    if (pthread_rwlock_init(&arr->lock, NULL)) return 0;
    arr->data = malloc(sizeof(MAC_RX_CONTEXT));
    if (!arr->data) {
        pthread_rwlock_destroy(&arr->lock);
        return 0;
    }
    arr->length = 0;
    arr->capacity = 1;
    return 1;
}

// Add an element to a context array. Returns 1 on success and 0 on failure.
int add_context(struct context_array *arr, MAC_RX_CONTEXT ctx) {
    pthread_rwlock_wrlock(&arr->lock);

    if (arr->length >= arr->capacity) {
        // Grow the array exponentially to amortize reallocs.
        size_t new_cap = arr->capacity ? 2 * arr->capacity : 1;
        MAC_RX_CONTEXT *new_data = realloc(arr->data, new_cap * sizeof(*new_data));

        if (!new_data) {
            pthread_rwlock_unlock(&arr->lock);
            return 0;
        }
        arr->data = new_data;
        arr->capacity = new_cap;
    }

    // Add the element and increment the length.
    arr->data[arr->length++] = ctx;

    pthread_rwlock_unlock(&arr->lock);
    return 1;
}

// Get an element from a context array by index. Returns a pointer to the element or NULL if the index is out of range.
MAC_RX_CONTEXT *get_context(struct context_array *arr, size_t idx) {
    pthread_rwlock_rdlock(&arr->lock);

    MAC_RX_CONTEXT *res = idx < arr->length ? &arr->data[idx] : NULL;

    pthread_rwlock_unlock(&arr->lock);
    return res;
}
```
