['This is quite a complex task and requires careful design and implementation. Here's a simplified version of what your function might look like in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    time_t timestamp;
    int isPrime;
} NumStruct;

NumStruct* readIntegers(int max, size_t batchSize) {
    NumStruct* nums = (NumStruct*)malloc(sizeof(NumStruct) * batchSize);

    if(nums == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    int counter = 0;
    while(counter < max && scanf("%d", &nums[counter].value) == 1) {
        nums[counter].timestamp = time(NULL);
        nums[counter].isPrime = isPrime(nums[counter].value) ? 1 : 0;

        counter++;
        if (counter == batchSize || counter % batchSize == 0) {
            batchSize *= 2;
            nums = (NumStruct*)realloc(nums, sizeof(NumStruct) * batchSize);

            if(nums == NULL) {
                perror("Memory reallocation failed");
                return NULL;
            }
        }
    }

    size_t finalSize = counter;
    nums = (NumStruct*)realloc(nums, sizeof(NumStruct) * finalSize);

    if(nums == NULL) {
        perror("Memory reallocation failed");
        return NULL;
    }

    return nums;
}
