```php
function handleUserAccount($postArray) {
    $response = ['success' => false, 'message' => ''];
    $mysqli = new mysqli('localhost', 'username', 'password', 'database');
    if (mysqli_connect_errno()) {
        $response['message'] = 'Failed to connect to MySQL: ' . mysqli_connect_error();
        return $jsonResponse($response);
    }

    $id = $postArray['id'];
    $name = $postArray['name'];
    $email = $postArray['email'];
    $password = $postArray['password'];
    $subAction = $postArray['sub_action'];

    if (empty($name) || empty($email) || empty($password)) {
        $response['message'] = 'Invalid input data';
        return $jsonResponse($response);
    }

    // transactional methods for saving and retrieving user account information.
    $mysqli->begin_transaction();
    if (isset($id)) {
        $query = "UPDATE users SET name=?, email=?, password=? WHERE id=?";
        $stmt = $mysqli->prepare($query);
        $stmt->bind_param('sssi', $name, $email, $password, $id);
    } else {
        $query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
        $stmt = $mysqli->prepare($query);
        $stmt->bind_param('sss', $name, $email, $password);
    }
    $stmt->execute();

    if ($subAction === 'delete') {
        if (!isset($id)) {
            $response['message'] = 'ID not provided for deletion';
            return $jsonResponse($response);
        }
        $query = "DELETE FROM users WHERE id=?";
        $stmt = $mysqli->prepare($query);
        $stmt->bind_param('i', $id);
        $stmt->execute();
    }
    $mysqli->commit();

    $response['success'] = true;
    $response['message'] = 'User account operation successful';
    return $jsonResponse($response);
}
```
