#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulate(int size, int minRNTI, int maxRNTI) {
    if (size <= 0 || minRNTI > maxRNTI) return NULL;

    srand(time(NULL)); //seed random function

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(size * sizeof(*array));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); //randomize
        array[i].RNTI = minRNTI + rand() % ((maxRNTI - minRNTI) + 1); //random RNTI within range
    }

    pthread_mutex_unlock(&lock);

    return array;
}
```

