```c
#include <stdlib.h>
#include <pthread.h>
#define MIN_RNTI 10
#define MAX_RNTI 5000
// Assuming the struct is defined as:
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

