int populate_indications(NFAPI_CRC_INDICATION_PDU_T** indications, int num_ues) {
    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety.
    *indications = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*indications == NULL) {
        fprintf(stderr, "Memory allocation failed.\n"); // Log the error.
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning to prevent a deadlock.
        return -1;
    } 

    for (int i = 0; i < num_ues; i++) {
        (*indications)[i].RX_UE_INFORMATION_TAG = rand(); // Assume random data from external source
        (*indications)[i].RNTI = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1); // Randomly set RNTI within the specified range.

        if ((*indications)[i].RNTI < MIN_RNTI || (*indications)[i].RNTI > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI value.\n"); // Log error for invalid RNTI.
            free(*indications); // Free allocated memory if an invalid RNTI is found.
            pthread_mutex_unlock(&lock); // Unlock the mutex before returning to prevent a deadlock.
            return -1;
        }

        (*indications)[i].CRC_INDICATION_REL8_TAG = rand();  // Randomly set CRCFLAG within the specified range.
    }

    pthread_mutex_unlock(&lock); // Unlock the mutex after memory allocation and population.
    return 0;
