    *maxWeightSum = 0;
    *maxWeightTxId = 0;
    time_t currentTime = time(NULL);
    int countInLast3Secs = 0;

    for (int i = 0; i < numTransactions; ++i) {
        Transaction_T tx = transactions[i];

        if (currentTime - tx.timestamp <= ageLimit) {  // transaction is within the specified age limit
            ++countInLast3Secs;
            *maxWeightSum += tx.weight;

            if (tx.weight > *maxWeightSum) {
                *maxWeightSum = tx.weight;
                *maxWeightTxId = tx.transactionID;
            }
        }
