    CRC_INDICATION_REL8_TAG CRC;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *indication[MAX_UE];
int validRangeStart = 0, validRangeEnd = 16384;
time_t lastUpdateTime[MAX_UE] = { 0 };
uint64_t crcCounter[MAX_CRC] = { 0 }, totalAge[MAX_AGE] = { 0 };
double weightedSum[MAX_AGE] = { 0.0 };
int maxWeightedSumTransactionID = 0;

void initialize() {
    srand(time(NULL));
}

int secureInitializeAES(const char *password, const unsigned char *salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, password, strlen(password), 1024, aesKey, iv) != 32) {
        fprintf(stderr, "Failed to derive key and IV using PBKDF2 with SHA-256\n");
        return -1;
    }
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int addIndication(uint16_t RNTI, uint8_t CRCFLAG) {
    if (RNTI < validRangeStart || RNTI > validRangeEnd) {
        fprintf(stderr, "Invalid RNTI value\n");
        return -EINVAL;
    }

    pthread_mutex_lock(&lock);

    // Allocate memory for new indication
    NFAPI_CRC_INDICATION_PDU_T *newIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newIndication == NULL) {
        fprintf(stderr, "Failed to allocate memory for indication\n");
        pthread_mutex_unlock(&lock);
        return -ENOMEM;
    }

    // Set RNTI and CRCFLAG in new indication
    newIndication->UE.RNTI = RNTI;
    newIndication->CRC.CRCFLAG = rand() % 256;

    // Add new indication to indications array
    indication[RNTI] = newIndication;

    pthread_mutex_unlock(&lock);
    return 0;
}

double filterTransactions(int transactionID, double weight) {
    if (transactionID < 0 || transactionID >= MAX_AGE) {
        fprintf(stderr, "Invalid transaction ID\n");
        return -EINVAL;
    }

    time_t currentTime = time(NULL);

    pthread_mutex_lock(&lock);

    // Update counters and weights
    for (int i = 0; i < transactionID; i++) {
        totalAge[i] += currentTime - lastUpdateTime[transactionID];
        crcCounter[i]++;
        weightedSum[i] += weight;
    }

    // Check if new maximum weighted sum
    if (weightedSum[transactionID] > weightedSum[maxWeightedSumTransactionID]) {
        maxWeightedSumTransactionID = transactionID;
    }

    pthread_mutex_unlock(&lock);

    return weightedSum[transactionID];
}
```
