using System;
using System.Collections.Concurrent;
using System.Threading;

public class DATA_OBJECT
{
    public string OBJECT_ID { get; set; }
    public long FILE_SIZE { get; set; }
    public DateTime LAST_ACCESS_TIME { get; set; }
}

public class DataManager
{
    private ConcurrentDictionary<string, DATA_OBJECT> _dataObjects = new ConcurrentDictionary<string, DATA_OBJECT>();
    private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public bool AddOrUpdate(DATA_OBJECT dataObject)
    {
        try
        {
            _lock.EnterWriteLock();

            if (_dataObjects.ContainsKey(dataObject.OBJECT_ID))
                _dataObjects[dataObject.OBJECT_ID] = dataObject;
            else
                _dataObjects.TryAdd(dataObject.OBJECT_ID, dataObject);
        }
        catch (OutOfMemoryException ex)
        {
            // log error message and return appropriate error code
            Console.WriteLine("Error: " + ex.Message);
            return false;
        }
        finally
        {
            _lock.ExitWriteLock();
        }

        return true;
    }

    public DATA_OBJECT Get(string objectId)
    {
        try
        {
            _lock.EnterReadLock();
            if (_dataObjects.TryGetValue(objectId, out var dataObject))
                return dataObject;
            else
                return null;
        }
        finally
        {
            _lock.ExitReadLock();
        }
    }
}
