['```javascript
function processData(filename, N, dataChunks) {
    if (N <= 0 || N > 255 - filename.length - 10) {
        throw new Error("Invalid value for N");
    }

    let extension = '';
    const firstChar = filename[0];
    if (isNaN(parseInt(firstChar))) {
        extension = '.txt';
    } else if (!isNaN(parseFloat(firstChar))) {
        extension = '.csv';
    } else {
        extension = '.log';
    }

    let newFilename;
    do {
        const randomNumbers = Date.now() % 1000000;
        newFilename = `${filename}_${randomNumbers}${extension}`;
    } while (newFilename.length > 255);

    let copiedDataSize = 0;
    const copiedData = Buffer.allocUnsafe(N);

    for (let i = 0; i < dataChunks.length && copiedDataSize < N; i++) {
        const chunk = Buffer.from(dataChunks[i]);

        if (copiedDataSize + chunk.byteLength > N) {
            break;
        }

        chunk.copy(copiedData, copiedDataSize);
        copiedDataSize += chunk.byteLength;
    }

    return [newFilename, copiedData];
}
```
