['Here is a JavaScript function that implements your requirements using Promises and an async/await pattern for concurrent operations:

```javascript
const fs = require('fs');
const sprintf = require("sprintf-js").sprintf;
const { performance } = require('perf_hooks');

let cache = new Map();
setInterval(() => {
    const now = Math.floor(performance.now() / 1000);
    for (let [key, value] of cache) {
        if (value.time < now - 5) cache.delete(key);
    }
}, 60 * 1000);

async function copyDataAndModifyFilename(filename, N, dataChunks) {
    if (!Number.isInteger(N) || N <= 0 || N > 255 - filename.length - 10) throw new Error('Invalid N');

    let buffer = Buffer.allocUnsafe(N);
    let offset = 0;
    for (let chunk of dataChunks) {
        if (offset + chunk.length > N) break;

        chunk.copy(buffer, offset, 0, Math.min(chunk.length, N - offset));
        offset += chunk.length;
        if (offset >= N) break;
    }

    const ext = filename[0].match(/[a-zA-Z]/) ? '.txt' : filename[0].match(/[0-9]/) ? '.csv' : '.log';
    const newFilename = sprintf(`%s_%d%s`, filename.slice(0, Math.min(100, filename.length)), Math.floor(performance.now() / 100), ext);

    if (cache.has(N) && cache.get(N).ext === ext) {
        return [buffer, newFilename];
    } else {
        const data = await fs.promises.readFile(__filename);
        cache.set(N, { time: Math.floor(performance.now() / 1000), ext, data });

        return [data, newFilename];
    }
}
```

Please note that the above code requires Node.js version >= 8 and fs-extra package for async file operations. Also, please replace `__filename` with your desired filename in readFile operation as I couldn't find a suitable replacement for it in this context. 

