["Here is an implementation in JavaScript using Promises for managing async operations, ArrayBuffer for efficient data handling, and a Map for tracking statistics:
```javascript
let bufferMap = new Map();  // map from offset to buffer
const logService = {log: console.log};  // placeholder for external logging service

class BufferPoolManager {
    constructor(maxSize) {
        this._currentSize = 0;
        this._maxSize = maxSize;
    }

    async copyBytes(offset, size) {
        if (size === 0) return new ArrayBuffer(0);  // handle zero-byte requests

        const buffers = [];
        let bytesCopied = 0;
        for (;;) {
            const buffer = this._getBufferAtOffset(offset + bytesCopied, size - bytesCopied);

            if (buffer === undefined) break;  // handle buffer overflows due to misaligned data regions

            buffers.push(buffer);
            bytesCopied += buffer.byteLength;

            if (bytesCopied >= size) break;  // copy all required bytes
        }

        const newBuffer = this._concatenateBuffers(buffers, size);
        logService.log({totalBytes: bytesCopied});
        return newBuffer;
    }

    _getBufferAtOffset(offset, remainingSize) {
        for (const [start, buffer] of bufferMap.entries()) {
            if (offset >= start && offset < start + buffer.byteLength) {
                const sliceStart = Math.max(0, offset - start);
                const sliceEnd = Math.min(buffer.byteLength, remainingSize);
                return buffer.slice(sliceStart, sliceEnd);
            }
        }
    }

    _concatenateBuffers(buffers, size) {
        let totalBufferView;

        if (size <= Uint8Array.BYTES_PER_ELEMENT) {
          totalBufferView = new Uint8Array(size);
        } else if (size <= 2 * Uint16Array.BYTES_PER_ELEMENT) {
          totalBufferView = new Uint16Array(Math.ceil(size / 2));
        } else {
          const numViews = Math.ceil(size / Float32Array.BYTES_PER_ELEMENT);
          totalBufferView = new Float32Array(numViews);
        }

        let byteOffset = 0;
        for (const buffer of buffers) {
            const view = new Uint8Array(buffer);
            totalBufferView.set(view, byteOffset);
            byteOffset += view.length;
        }

        return totalBufferView.buffer;
    }

    addBuffer(start, buffer) {
        if (this._currentSize + buffer.byteLength > this._maxSize) throw new Error('Exceeded maximum pool size');

        for (let i = 0; i < buffer.byteLength; i++) {
            const byte = buffer[i];  // access each byte to ensure copy and avoid zero-copy issue
            bufferMap.set(start + i, new Uint8Array([byte]));
        }

        this._currentSize += buffer.byteLength;
    }

    resizePoolIfNecessary() {
        if (this._currentSize >= this._maxSize) throw new Error('Exceeded maximum pool size');
    }
}
```
Please note that the code does not implement thread-safe operations and concurrency control, as JavaScript is single-threaded in a web browser environment. For such environments, you'd need to use Web Workers or libraries like Async/Await for async operations and locking mechanism for concurrent access. Also, this implementation doesn't handle overlapping regions of data within buffers. To handle overlaps, the code needs to be more complex that just slicing a buffer at an offset and concatenating results.
"]

