// Data structure for stream management
typedef struct {
    pthread_mutex_t lock; // Lock for thread safety
    FILE* file; // File pointer to the stream's file
} StreamData;

StreamData* streams = NULL; // Array of streams
int num_streams = 0; // Number of streams currently managed
pthread_mutex_t streamMutex; // Mutex for thread-safe access to the streams array

void flexible_io_and_stream_processor(char* filePath, int dataLength, int appendFlag, char* deviceID, char* streamType, int dataRate) {
    pthread_mutex_lock(&streamMutex); // Acquire lock on the streams array

    // Check if the stream already exists in our list of managed streams
    StreamData* existingStream = NULL;
    for(int i = 0; i < num_streams; ++i) {
        if(strcmp(streams[i].filePath, filePath) == 0) {
            existingStream = &streams[i];
            break;
        }
    }

    // If the stream does not exist, create it and add it to our list of streams
    if(!existingStream) {
        FILE* file = fopen(filePath, appendFlag ? "a" : "w"); // Open file in either read or write mode

        if(file == NULL) {
            printf("Failed to open file: %s\n", strerror(errno));
            pthread_mutex_unlock(&streamMutex); // Release lock on the streams array
            return;
        }

        // Add new stream data to our list of managed streams
        ++num_streams;
        streams = realloc(streams, num_streams * sizeof(StreamData)); 
        StreamData* newStream = &streams[num_streams-1];
        pthread_mutex_init(&newStream->lock, NULL); // Initialize lock for the stream
        newStream->file = file; // Store file pointer to the opened file
    } else {
        existingStream = streams; // Retrieve the existing stream
    }

    pthread_mutex_unlock(&streamMutex); // Release lock on the streams array

    // Now, `existingStream` is guaranteed to point to an open and valid file stream
    // You can perform further operations with it
}
