    pthread_mutex_lock(&allocationMutex);

    int cacheIndex = rnti % CACHE_SIZE;
    CacheEntry* entry = &cache[cacheIndex];

    if (entry->valid && entry->pdu.RNTI == rnti) {
        sem_wait(&numEntriesSemaphore);
        pthread_mutex_unlock(&allocationMutex);
        return &entry->pdu;
    }

    pthread_mutex_lock(&cacheMutex);
    if (entry->valid && entry->pdu.RNTI == rnti) { // Double check after locking cache mutex
        sem_wait(&numEntriesSemaphore);
        pthread_mutex_unlock(&allocationMutex);
        return &entry->pdu;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
