    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcFlag;

    entry->pdu = *pdu;
    entry->valid = 1;
    sem_post(&numEntriesSemaphore);

    pthread_mutex_unlock(&cacheMutex);
    pthread_mutex_unlock(&allocationMutex);

    return pdu;
}
