// Log levels enum
typedef enum {
    LOG_LEVEL_CRITICAL,
    LOG_LEVEL_NORMAL,
} log_level;

void dynamic_log(FILE *fp, int isLoggingEnabled, char *conditionMessage, log_level level, const char *format, ...) {
    // Dynamically allocate buffer size based on the complexity of the message and the presence of timestamps.
    char *buffer = NULL;
    va_list args, copy;

    va_start(args, format);
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, format, args) + 1; // +1 for null terminator
    va_end(copy);

    buffer = malloc(length * sizeof(*buffer));

    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for log message\n");
        return;
    }

    // Format the log message into a buffer.
    int n = vsnprintf(buffer, length, format, args);
    va_end(args);

    if (isLoggingEnabled) {
        // Determine optimal timing for writing formatted message to the log file.
        if (level == LOG_LEVEL_CRITICAL) {
            // Immediate logging for critical errors to minimize delay between error occurrence and its logging.
            fprintf(fp, "%s", buffer);
        } else {
            // Batching messages for non-critical events to reduce disk I/O operations. 
            // You might want to implement a more complex batching strategy here based on your needs.
            if (fflush(fp) != 0 || ferror(fp)) {
                fprintf(stderr, "Failed to write log message: %s\n", strerror(errno));
            } else {
                fprintf(fp, "%s", buffer);
            }
        }
    } // If logging is disabled, skip writing to the file and free the buffer. 

    free(buffer);
}
