#include <openssl/evp.h>
#include <jansson.h>

typedef struct {
    // add necessary fields for custom data chunk formatting
} CustomFormatConfig;

// Prototype of the function that you requested
bool copy_buffered_data(const unsigned char** chunks, size_t* chunkSizes, 
                        size_t numChunks, unsigned char* destBuffer, 
                        size_t maxDestBufferSize, CustomFormatConfig* formatConfig, 
                        const unsigned char* checksum, 
                        void (*loggingCallback)(const char*, int), 
                        bool* isValid) {

    // Initialize variables for copied data and remaining space in destBuffer
    size_t totalCopied = 0;
    size_t remainingSpace = maxDestBufferSize;

    EVP_MD_CTX* mdctx = NULL; 
    unsigned int checksumLen;

    // Initialize logging mechanism
    char logMessage[1024];
    sprintf(logMessage, "Starting copying process...");
    loggingCallback(logMessage, LOG_INFO);

    // Copy data from chunks to destBuffer
    for (size_t i = 0; i < numChunks && totalCopied < maxDestBufferSize; ++i) {
        size_t chunkSize = chunkSizes[i];

        if (chunkSize > remainingSpace) {
            // Handle edge case of partial read by logging and continuing with next chunk
            sprintf(logMessage, "Partial read in chunk %zu", i);
            loggingCallback(logMessage, LOG_WARNING);
            continue;
        }

        // Copy data from current chunk to destBuffer
        memcpy(destBuffer + totalCopied, chunks[i], chunkSize);

        // Update copied size and remaining space in destBuffer
        totalCopied += chunkSize;
        remainingSpace -= chunkSize;
    }

    // Verify integrity of copied data using checksum algorithm
    EVP_DigestInit(&mdctx, EVP_sha256()); 
    EVP_DigestUpdate(mdctx, destBuffer, totalCopied);
    unsigned char calculatedChecksum[EVP_MAX_MD_SIZE];
    EVP_DigestFinal(&mdctx, calculatedChecksum, &checksumLen);

    if (memcmp(calculatedChecksum, checksum, checksumLen) != 0) {
        // Log checksum mismatch and return false to indicate invalid data
        sprintf(logMessage, "Checksum mismatch");
        loggingCallback(logMessage, LOG_ERROR);
        *isValid = false;
    } else {
        *isValid = true;
    }

    // Log total copied size and duration of copying operation
    clock_t startTime = clock();
    sprintf(logMessage, "Copied %zu bytes in %.3fs", totalCopied, (double)(clock() - startTime) / CLOCKS_PER_SEC);
    loggingCallback(logMessage, LOG_INFO);

    // Cleanup and return true to indicate successful copying operation
    EVP_MD_CTX_free(mdctx);
    return true;
}
```

Please note that the actual implementation might require more intricate handling of edge cases, concurrency issues, cryptographic operations and JSON validation. This is just a simplified example. 

