void conditional_log(Logger *logger, const char *format, ...) {
    va_list args;
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    pthread_mutex_lock(&mutex); // Lock before accessing shared data to avoid race conditions.

    if (logger->logging_mode) {
        va_start(args, format);
        fprintf(logger->log_file, "[%02d:%02d:%02d] ", timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        vfprintf(logger->log_file, format, args);
        fflush(logger->log_file); // Flush to ensure log is written immediately.
        va_end(args);
    } else {
        va_start(args, format);
        va_end(args); // Discard the arguments if logging is disabled
    }

    pthread_mutex_unlock(&mutex); // Unlock after accessing shared data.
}
