    arr->array = newArray;
    arr->capacity = newCapacity;
}

void insertConcurrentArray(ConcurrentArray* arr, NFIX_RX_MESSAGE_T message) {
    pthread_spin_lock(&arr->spinlock);

    if (arr->length >= arr->capacity) {
        resizeConcurrentArray(arr, arr->capacity * 2); // Double the capacity when full
    }

    arr->array[arr->length++] = message;

    pthread_spin_unlock(&arr->spinlock);
}

void removeConcurrentArray(ConcurrentArray* arr, size_t index) {
    pthread_spin_lock(&arr->spinlock);

    if (index < arr->length - 1) { // Move the last element to fill the gap
        arr->array[index] = arr->array[arr->length - 1];
    }

    --(arr->length);

    pthread_spin_unlock(&arr->spinlock);
}
