typedef struct SESSION_INFO {
    // Add session info fields here
} SESSION_INFO;

typedef struct USER_SESSION {
    char *userId;
    int connectivityStatus;
    double bandwidthRequest;
    time_t timestamp;
    SESSION_INFO* sessionInfo;
    pthread_mutex_t lock; // Thread-safe lock for concurrent access.
} USER_SESSION;

// Global Variables
USER_SESSION **sessions = NULL;
size_t numSessions = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER; // Lock for session array access.

// Function to allocate a USER_SESSION dynamically
void* allocateSession(void *userId) {
    pthread_mutex_lock(&globalLock);
    numSessions++;
    sessions = realloc(sessions, numSessions * sizeof(USER_SESSION*));
    if (sessions == NULL) {
        // Handle memory allocation failure
        numSessions--;
        pthread_mutex_unlock(&globalLock);
        return NULL;
    }

    USER_SESSION* session = malloc(sizeof(USER_SESSION));
    if (session == NULL) {
        // Handle memory allocation failure
        numSessions--;
        pthread_mutex_unlock(&globalLock);
        return NULL;
    }

    session->userId = strdup((char*)userId);
    session->connectivityStatus = 0;
    session->bandwidthRequest = 0.0;
    time(&session->timestamp);
    pthread_mutex_init(&session->lock, NULL); // Initialize session lock

    sessions[numSessions - 1] = session;
    pthread_mutex_unlock(&globalLock);

    return (void*)session;
}

// Function to deallocate a USER_SESSION
void deallocateSession(USER_SESSION *session) {
    if (session == NULL)
        return;

    pthread_mutex_lock(&globalLock);

    for (size_t i = 0; i < numSessions; i++) {
        if (sessions[i] == session) {
            free(session->userId);

            // Handle sessionInfo deallocation if required.

            pthread_mutex_destroy(&session->lock); // Destroy session lock
            free(session);

            memmove(sessions + i, sessions + (i + 1), (numSessions - i - 1) * sizeof(USER_SESSION*));
            numSessions--;

            if (numSessions == 0) {
                free(sessions);
                sessions = NULL;
            } else {
                sessions = realloc(sessions, numSessions * sizeof(USER_SESSION*));
            }

            break;
        }
    }

    pthread_mutex_unlock(&globalLock);
}
```
