["```javascript
const { PassThrough } = require('stream');
const StreamArray = require('stream-array');
const mergeStreams = require('merge-streams');

function bufferedMerge(inputStreams, outputStream, maxBuffer) {
    const streams = inputStreams.map((inputStream) => new PassThrough());
    const mergedStream = new PassThrough();
    let totalBuffered = 0;

    function processChunk(chunk, sourceIndex) {
        mergedStream.write(chunk);

        if (totalBuffered >= maxBuffer && sourceIndex !== null) {
            streams[sourceIndex].pause();
        }
    }

    for (let i = 0; i < inputStreams.length; ++i) {
        const currentStream = streams[i];

        currentStream.on('data', (chunk) => processChunk(chunk, i));

        currentStream.on('end', () => {
            if (--streams.length === 0 && mergedStream.writable) {
                mergedStream.end();
            }
        });

        inputStreams[i].pipe(currentStream);
    }

    mergedStream.on('drain', () => {
        streams.forEach((stream, i) => stream.resume());
        totalBuffered = 0;
    });

    mergedStream.pipe(outputStream);
}

// Usage:
const input1 = new StreamArray([1, 2, 3]);
const input2 = new StreamArray(['a', 'b', 'c']);
const output = new PassThrough();
bufferedMerge([input1, input2], output, 5); // maxBuffer of 5 chunks
```
