    int RECEPTION_QUALITY;
} NodeData;

typedef struct QNode {
    struct QNode *prev, *next;
    NodeData data;
} QNode;

QNode* newNode(NodeData k)
{
    QNode* temp = (QNode*)malloc(sizeof(QNode));
    temp->data = k;
    temp->prev = temp->next = NULL;
    return temp;
}

typedef struct Queue {
    unsigned count;
    pthread_mutex_t lock;
    QNode *front, *rear;
} Queue;

Queue* createQueue()
{
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->count = 0;
    q->front = q->rear = NULL;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enQueue(Queue* q, NodeData k) 
{
    pthread_mutex_lock(&q->lock);

    QNode* temp = newNode(k);

    if (q->rear == NULL) {
        q->front = q->rear = temp;
        return;
    }

    temp->next = q->rear;
    q->rear->prev = temp;
    q->rear = temp;

    if (q->count == MAX_QUEUE_SIZE) {
        q->front = q->front->prev;
        free(q->front->next);
        q->front->next = NULL;
    } else {
        ++q->count;
    }

    pthread_mutex_unlock(&q->lock);
}

// and so on for other functions like deQueue, isEmpty, etc. 
