#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define ENTRY_SIZE 256

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    void *CRC_INDICATION_REL8_TAG;
} UEInformationTag;

static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
static UEInformationTag *list = NULL;
static size_t count = 0, capacity = 0;

int configure_lte_ue_traffic_monitor() {
    pthread_mutex_lock(&listMutex);

    if(count >= MAX_ENTRIES) {
        // Resize the list when the current capacity is exceeded.
        size_t newCapacity = (capacity == 0) ? 1 : capacity * 2;
        if(newCapacity > MAX_ENTRIES || newCapacity < capacity) {
            pthread_mutex_unlock(&listMutex);
            return -1; // Error: Integer overflow or exceeded the maximum number of entries.
        }

        UEInformationTag *newList = (UEInformationTag *)realloc(list, newCapacity * ENTRY_SIZE);
        if(!newList) {
            pthread_mutex_unlock(&listMutex);
            return -2; // Error: Failed to allocate memory.
        }

        list = newList;
        capacity = newCapacity;
    }

    // Initialize the new entry at the next position and increment the count.
    memset(&list[count], 0, sizeof(UEInformationTag));
    count++;

    pthread_mutex_unlock(&listMutex);

    return 0; // Success
}
```
