["```c
#include <stdlib.h>
#include <stdatomic.h>
#include <assert.h>

typedef struct {
    int CONNECTION_ID;
    char SOURCE_IP[32];
    char DESTINATION_IP[32];
    atomic_int BYTES_SENT;
    atomic_int BYTES_RECEIVED;
} connection_info_t;

typedef struct {
    connection_info_t** connections;
    _Atomic(size_t) size;
    _Atomic(size_t) capacity;
} network_traffic_logger_t;

network_traffic_logger_t logger = {0};
int resize_factor = 2;  // Increase the list's capacity by this factor when resizing.

enum error_code {
    SUCCESS,
    ALLOCATION_FAILURE,
    INITIALIZATION_ERROR,
};

void log_operation(int operation_result) {
    if (operation_result == SUCCESS) {
        // Log successful operations.
    } else {
        // Log failed operations.
    }
}

enum error_code initialize_network_traffic_logger() {
    size_t initial_capacity = 1024;  // Start with a small capacity to reduce fragmentation during startup.
    logger.connections = malloc(initial_capacity * sizeof(connection_info_t*));

    if (logger.connections == NULL) {
        return ALLOCATION_FAILURE;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        logger.connections[i] = malloc(sizeof(connection_info_t));

        if (logger.connections[i] == NULL) {
            // Free previously allocated memory and return an error.
            for (--i; i >= 0; --i) {
                free(logger.connections[i]);
            }

            free(logger.connections);
            logger.connections = NULL;
            return ALLOCATION_FAILURE;
        }

        // Initialize the connection info struct with default values.
        *(logger.connections[i]) = (connection_info_t) {0};  
    }

    atomic_init(&logger.size, 0);
    atomic_init(&logger.capacity, initial_capacity);

    return SUCCESS;
}

void add_connection(int connection_id, char* source_ip, char* destination_ip) {
    size_t current_size = atomic_load(&logger.size);
    size_t current_capacity = atomic_load(&logger.capacity);

    if (current_size >= current_capacity) {
        // Resize the list.
        connection_info_t** new_connections = realloc(logger.connections, logger.capacity * resize_factor * sizeof(connection_info_t*));

        if (new_connections == NULL) {
            log_operation(ALLOCATION_FAILURE);
            return;
        }

        // Initialize the new connections with default values.
        for (size_t i = current_capacity; i < logger.capacity * resize_factor; ++i) {
            new_connections[i] = malloc(sizeof(connection_info_t));

            if (new_connections[i] == NULL) {
                log_operation(ALLOCATION_FAILURE);
                return;
            }

            *(new_connections[i]) = (connection_info_t) {0};  
        }

        logger.connections = new_connections;
        atomic_store(&logger.capacity, logger.capacity * resize_factor);
    }

    // Add the connection to the list.
    connection_info_t* connection = logger.connections[current_size];
    assert(connection != NULL);  // Assert that memory allocation was successful.

    // Initialize the connection info struct with provided values.
    *connection = (connection_info_t) {
        .CONNECTION_ID = connection_id,
        .SOURCE_IP = source_ip,
        .DESTINATION_IP = destination_ip,
        .BYTES_SENT = 0,
        .BYTES_RECEIVED = 0
    };  

    atomic_fetch_add(&logger.size, 1);
}
