typedef struct {
    DEVICE_INFO devices[MAX_DEVICES];
    int numDevices;
    SENSORS_DATA_T sensors[MAX_SENSORS];
    int numSensors;
} DeviceManager;

THREAD_SAFE_ACCESS
DeviceManager manager;

void init() {
    pthread_mutex_init(&manager.lock, NULL);
    atomic_init(&manager.numDevices, 0);
    atomic_init(&manager.numSensors, 0);
}

int addDevice(DEVICE_INFO *device) {
    if (atomic_load(&manager.numDevices) >= MAX_DEVICES) return -1;
    pthread_mutex_lock(&manager.lock);
    int index = atomic_fetch_add(&manager.numDevices, 1);
    manager.devices[index] = *device;
    pthread_mutex_unlock(&manager.lock);
    return 0;
}

int addSensorData(SENSORS_DATA_T *data) {
    if (atomic_load(&manager.numSensors) >= MAX_SENSORS) return -1;
    pthread_mutex_lock(&manager.lock);
    int index = atomic_fetch_add(&manager.numSensors, 1);
    manager.sensors[index] = *data;
    pthread_mutex_unlock(&manager.lock);
    return 0;
}
