```c
#include <stdio.h>
#include <pthread.h>

// Global mutex for locking shared resource 
pthread_mutex_t lock; 

// Shared resource
int shared_resource = 0;

void* doSomeWork(void *arg) { 
    pthread_mutex_lock(&lock); 

    // Critical section (shared resources accessed here)
    printf("\nInside thread\n");
    shared_resource++;

    // Unlocks mutex after critical section 
    pthread_mutex_unlock(&lock); 
} 

int main() {
    pthread_t tid[2]; 

    if (pthread_mutex_init(&lock, NULL) != 0) { 
        printf("\nMutex initialization failed\n"); 
        return 1; 
    } 

    for(int i=0;i<2;i++){
      pthread_create(&(tid[i]), NULL, &doSomeWork, NULL); 
    }

    // Joining threads with main thread
    for(int i=0;i<2;i++) {
      pthread_join(tid[i], NULL); 
    }

    printf("Shared resource value: %d\n", shared_resource); 

    // Destroying mutex
    pthread_mutex_destroy(&lock); 
}
```
In the above example, `doSomeWork` is a function that gets executed in different threads. It's critical section (the area where shared resources are accessed) is protected by lock using `pthread_mutex_lock()` and `pthread_mutex_unlock()`. This ensures that only one thread can access the shared resource at any given time, preventing race conditions. 

