typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    struct Node *prev;
    struct Node *next;
    NFAPI_CRC_INDICATION_PDU_T data;
} Node;

Node* head = NULL;
pthread_mutex_t mutexHead = PTHREAD_MUTEX_INITIALIZER;

void addEntry(NFAPI_CRC_INDICATION_PDU_T data) {
    Node * newNode = (Node *) malloc(sizeof(Node));
    if(newNode == NULL) exit(-1); // handle error here

    pthread_mutex_lock(&mutexHead);

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = head;

    if (head != NULL) {
        head->prev = newNode;
    }

    head = newNode;

    pthread_mutex_unlock(&mutexHead);
}

void removeEntry(int RNTI) {
    pthread_mutex_lock(&mutexHead);

    Node *tmp = head;
    while (tmp != NULL) {
        if (tmp->data.RNTI == RNTI) {
            if (tmp->prev != NULL) {
                tmp->prev->next = tmp->next;
            } else {
                head = tmp->next;
            }

            free(tmp);
        }

        tmp = tmp->next;
    }

    pthread_mutex_unlock(&mutexHead);
}

void updateCRCFLAG(int RNTI, char newFlag) {
    pthread_mutex_lock(&mutexHead);

    Node *tmp = head;
    while (tmp != NULL) {
        if (tmp->data.RNTI == RNTI) {
            tmp->data.CRCFLAG = newFlag;
        }

        tmp = tmp->next;
    }

    pthread_mutex_unlock(&mutexHead);
}
```

