```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import java.io.IOException;

public class JsonMerger {
    private ObjectMapper mapper = new ObjectMapper();

    public String merge(String... jsonStrings) throws IOException {
        List<JsonNode> nodes = new ArrayList<>();

        // Parse all JSON strings into JsonNodes and add to list
        for (String json : jsonStrings) {
            if (!json.isEmpty()) {  // Ignore empty or null JSONs
                JsonNode node = mapper.readTree(json);
                nodes.add(node);
            }
        }

        return mergeNodes(nodes).toString();
    }

    private JsonNode mergeNodes(List<JsonNode> nodes) {
        Iterator<Map.Entry<String, JsonNode>> iter = null;
        Map<String, JsonNode> mergedMap = new HashMap<>();

        // For each node in the list...
        for (JsonNode node : nodes) {
            if (node == null || node.size() == 0) continue;  // Skip empty or null nodes

            if (!node.isObject()) {
                throw new IllegalArgumentException("All JSON objects must be objects.");
            }

            iter = node.fields();

            while (iter.hasNext()) {
                Map.Entry<String, JsonNode> entry = iter.next();

                if (!mergedMap.containsKey(entry.getKey())) {
                    mergedMap.put(entry.getKey(), entry.getValue());  // Add new key-value pair to map
                } else {
                    JsonNode existingValue = mergedMap.get(entry.getKey());

                    if (existingValue.isArray()) {
                        ((ArrayNode)existingValue).add(entry.getValue());  // Append value to array in map
                    } else if (existingValue.equals(entry.getValue())){
                        continue;  // Ignore identical values
                    } else {
                        ArrayNode newValue = mapper.createArrayNode();

                        newValue.add(existingValue);
                        newValue.add(entry.getValue());

                        mergedMap.put(entry.getKey(), newValue);  // Create array with existing and new values in map
                    }
                }
            }
        }

        return mapper.valueToTree(mergedMap);  // Convert map back to JsonNode
    }
}
```

This code first parses all input JSON strings into `JsonNode` objects, which represent the data in a way that Jackson can easily manipulate and analyze. It then iterates over each key-value pair in these nodes, merging them according to your specified rules (i.e., values for overlapping keys are turned into arrays). The merged data is stored in a `HashMap` before being converted back into a single `JsonNode` that can be returned as a JSON string.
