    if (pipeline->configs == NULL) {
        pthread_mutex_unlock(&pipeline->lock);
        return;
    }

    pipeline->configs[pipeline->count] = config;
    pipeline->count++;

    pthread_mutex_unlock(&pipeline->lock);
}
