        printf("Failed to allocate memory for new cache node!\n");
        return;
    }

    *newNode = (CacheNode){.config = newConfig, .next = NULL};

    pthread_mutex_lock(&listLock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&listLock);
}
```

