const crypto = require('crypto');

async function copyData(chunks, limit, algorithm='md5', bufferSize=1024) {
    let total = 0;
    const newBuffer = [];

    for (let chunk of chunks) {
        if (!chunk.length) continue; // handle empty data chunks

        let offset = 0;

        while(offset < chunk.length && total <= limit) {
            let size = Math.min(bufferSize, chunk.length - offset);

            const clonedChunk = Buffer.from(chunk.slice(offset, offset + size)); // deep clone
            newBuffer.push(clonedChunk); 

            total += size;
            offset += size;
        }

        if (total > limit) {
            throw new Error('Exceeded memory limit');
        }
    }

    const result = Buffer.concat(newBuffer);

    // checksum verification placeholder, replace with actual logic
    const hash = crypto.createHash(algorithm);
    hash.update(result);
    let digest = hash.digest('hex');

    return {buffer: result, checksum: digest};
}
