["Here is a basic implementation of such function in Node.js environment. Please adjust it according to your needs.

```javascript
const crypto = require('crypto');
const { Readable } = require('stream');
const cloneDeep = require('lodash/cloneDeep');

async function copyData(dataChunks, limit, checksumAlgorithm, bufferSize) {
    let copiedBytes = 0;
    let newBuffer = Buffer.allocUnsafe(bufferSize);

    for (let chunk of dataChunks) {
        // Deep clone to avoid modifying the original chunks.
        const dataChunkCopy = cloneDeep(chunk); 

        if (!dataChunkCopy || !dataChunkCopy.length) continue; // Handle empty input data.

        let bufferPosition = 0;

        while (copiedBytes < limit && bufferPosition < chunk.length) {
            const bytesToWrite = Math.min(chunk.length - bufferPosition, limit - copiedBytes);

            if (!bytesToWrite) break; // Handle incomplete data chunks.

            newBuffer.fill(chunk.slice(bufferPosition, bufferPosition + bytesToWrite), copiedBytes);

            copiedBytes += bytesToWrite;
            bufferPosition += bytesToWrite;
        }
    }

    if (copiedBytes > limit) {
        throw new Error('Copied data size exceeded the specified limit.');
    }

    const checksum = crypto.createHash(checksumAlgorithm);
    checksum.update(newBuffer);
    const digest = checksum.digest('hex');

    return { newBuffer, digest };
}
```
The function `copyData` copies data from the list of buffered chunks to a new buffer while adhering to constraints mentioned in the problem statement. It verifies the integrity of copied data using checksum algorithm and throws an error if size limit is exceeded. 

Please note that this implementation assumes that input chunks are array-like objects with a length property, which is not necessarily true for all JavaScript values. Also it does not handle edge cases where multiple asynchronous operations might compete for resources but the problem statement doesn't provide specifics about such scenarios.
