typedef struct RrcMessage {
    char* messageType;
    time_t timestamp;
    void* payload;
    size_t payloadSize;
} RrcMessage;

void freeRrcMessages(RrcMessage* messages, int numMessages) {
    for (int i = 0; i < numMessages; ++i) {
        if (messages[i].payload != NULL) {
            free(messages[i].payload);
        }
        if (messages[i].messageType != NULL) {
            free(messages[i].messageType);
        }
    }
}

typedef struct UeSessionState {
    int UEIdentifier;
    time_t sessionEstablishmentTime;
    RrcMessage* messages;
    size_t numMessages;
} UeSessionState;

void freeUeSessions(UeSessionState* sessions, int numSessions) {
    for (int i = 0; i < numSessions; ++i) {
        freeRrcMessages(sessions[i].messages, sessions[i].numMessages);
        free(sessions[i].messages);
    }
    free(sessions);
}

void addMessageToSession(UeSessionState* session, char* messageType, void* payload, size_t payloadSize) {
    session->messages = realloc(session->messages, (session->numMessages + 1) * sizeof(RrcMessage));
    RrcMessage newMessage;
    newMessage.messageType = malloc((strlen(messageType)+1)*sizeof(char));
    strcpy(newMessage.messageType, messageType);
    newMessage.payload = malloc(payloadSize);
    memcpy(newMessage.payload, payload, payloadSize);
    newMessage.timestamp = time(NULL);
    session->messages[session->numMessages] = newMessage;
    ++session->numMessages;
}

UeSessionState* initSessionsArray(int numSessions) {
    UeSessionState* sessions = malloc(sizeof(UeSessionState) * numSessions);
    for (int i = 0; i < numSessions; ++i) {
        sessions[i].UEIdentifier = i + 1;
        sessions[i].sessionEstablishmentTime = time(NULL);
        sessions[i].messages = NULL;
        sessions[i].numMessages = 0;
    }
