    pthread_mutex_init(&session->mutex, NULL);
    session->id = id;
    time(&session->establishmentTime);
    session->messageCount = 0;
    session->maxMessages = 16; // initial capacity
    session->messages = malloc(sizeof(RrcMessage*) * session->maxMessages);
}

// Add a message to the UE session state
void addMessage(UeSessionState* session, RrcMessage* msg) {
    pthread_mutex_lock(&session->mutex);

    if (session->messageCount == session->maxMessages) {
        // Resize messages array
        session->maxMessages *= 2;
        session->messages = realloc(session->messages, sizeof(RrcMessage*) * session->maxMessages);
    }

    session->messages[session->messageCount++] = msg;

    pthread_mutex_unlock(&session->mutex);
}

