        for (int j = 0; j < 4; ++j) {
            ip_addr[j] = rand() % 256;
        }
        nicps[i].ip.saddr = *(unsigned int*)ip_addr;

        // Set random sequence and acknowledgment numbers for TCP
        unsigned short seq_num = rand() % USHRT_MAX;
        unsigned short ack_num = rand() % USHRT_MAX;
