void load_config_from_json(const char* filename) {
    FILE* fp = fopen(filename, "r"); // open the json file.
    if (fp == NULL) {
        printf("Failed to open config file.\n");
        return;
    }

    fseek(fp, 0L, SEEK_END);
    size_t fileSize = ftell(fp); // get the file size.
    rewind(fp);

    char* jsonStr = malloc(fileSize + 1); // allocate memory for the json string.
    fread(jsonStr, fileSize, 1, fp); // read the entire file into a buffer.
    jsonStr[fileSize] = 0; // null-terminated string.

    cJSON* json = cJSON_Parse(jsonStr); // parse the json string.
    if (json == NULL) {
        printf("Failed to parse JSON.\n");
        free(jsonStr);
        fclose(fp);
        return;
    }

