['Here is a C function that implements some of these requirements using the `res_query` function from c-ares library for DNS resolution:

```C
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <ares.h>

typedef struct {
    ares_channel channel;
} DnsResolver;

int initDnsResolver(DnsResolver *resolver) {
    int status = ares_init(&(resolver->channel));
    if (status != ARES_SUCCESS) {
        printf("ares_init failed: %s\n", ares_strerror(status));
        return 1;
    }
    return 0;
}

u_char *resolveHostname(DnsResolver *resolver, char *hostname) {
    static u_char ip[INET6_ADDRSTRLEN]; // Static buffer to hold IP address string
    struct in6_addr addr6;
    int status = ares_gethostbyname(resolver->channel, hostname, AF_UNSPEC, &addr6);
    if (status != ARES_SUCCESS) {
        printf("ares_gethostbyname failed: %s\n", ares_strerror(status));
        return NULL;
    }

    // Convert IP address to string representation for logging purposes
    const char *addrStr = inet_ntop(AF_INET6, &addr6, ip, INET6_ADDRSTRLEN);
    if (addrStr == NULL) {
        printf("inet_ntop failed: %s\n", strerror(errno));
        return NULL;
    }

    // If successful, log the IP address and return it
    printf("Resolved hostname '%s' to IP '%s'\n", hostname, ip);
    return inet_pton(AF_INET6, addrStr, &ip) > 0 ? ip : NULL;
}

void destroyDnsResolver(DnsResolver *resolver) {
    ares_destroy(resolver->channel);
}
```

This code snippet provides a basic implementation of DNS resolution using c-ares. The `resolveHostname` function takes a DnsResolver object and a hostname as input, performs the DNS resolution, converts the resulting IP address to string format for logging purposes, and then returns it. If any errors occur during the DNS resolution process, they are printed to stderr and NULL is returned. 

