    if (n < 0 || n > maxArraySize) {
        printf("Invalid input. Please enter a value between 0 and %d\n", maxArraySize);
        return;
    }

    pthread_mutex_lock(&mutex);
    // Reallocate array if needed
    while (arraySize < n) {
        dynamicArray = realloc(dynamicArray, sizeof(*dynamicArray) * ++arraySize);
        if (dynamicArray == NULL) {
            printf("Memory allocation failed. Aborting.\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        // Initialize new element here
    }

    while (arraySize > n) {
        // Deallocate unused elements if needed
        --arraySize;
    }
    pthread_mutex_unlock(&mutex);
}
