NFAPI_CRC_INDICATION_PDU_T* allocateAndProcessNFABatches(int N) {
    if (N > 2048 || N <= 0) { // Check bounds
        return NULL;
    }

    ProcessingContext context = { PTHREAD_MUTEX_INITIALIZER, 0, calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T)), N };

    if (context.array == NULL) { // Handle memory allocation failure
        return NULL;
    }

    for (int i = 0; i < N; ++i) { // Populate with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        context.array[i].RX_UE_INFORMATION_TAG = generateRandomTag();
        context.array[i].RNTI = generateRandomRNTI();
        context.array[i].CRC_INDICATION_REL8_TAG = generateRandomRel8Tag();
    }

    int systemLoad = getSystemLoad();
    int availableMemory = getAvailableMemory();

    // Adjust batch size based on system load and available memory, with a minimum of 10% of total and maximum of N.
    context.batchSize = (systemLoad * 0.1 + availableMemory * 0.1) / 2;
    if(context.batchSize > N) {
        context.batchSize = N;
    } else if(context.batchSize < 10){
        context.batchSize = 10; // Minimum batch size should be 10 as per task description
    }

    sem_init(&context.batchSemaphore, 0, context.arraySize / context.batchSize);

    pthread_t thread[context.arraySize / context.batchSize];
    for (int i = 0; i < context.arraySize / context.batchSize; ++i) { // Start multiple threads to process each batch in parallel
        int result = pthread_create(&thread[i], NULL, processBatch, &context);

        if (result != 0) { // Handle thread creation failure
            return NULL;
        }
    }

    for (int i = 0; i < context.arraySize / context.batchSize; ++i) { // Wait for all threads to complete their tasks
        pthread_join(thread[i], NULL);
    }

    sem_destroy(&context.batchSemaphore);

    return context.array;
}

void* processBatch(void* ctx) {
    ProcessingContext *context = (ProcessingContext*)ctx;
    pthread_mutex_lock(&context->mutex); // Lock the mutex to protect shared resource access

    sem_wait(&context->batchSemaphore); // Wait until it's our turn to process a batch

    int start = context->arraySize - context->batchSize; // Calculate the starting index for this batch
    for (int i = start; i < start + context->batchSize; ++i) {
        if(start < 0 || start >= context->arraySize){ 
            break;
        }

        processNFAPI_CRC_INDICATION_PDU(&context->array[i]); // Assume this function is implemented to process each structure in the batch
    }

    pthread_mutex_unlock(&context->mutex); // Unlock the mutex after we're done with the shared resource access
}
