["Here is a basic outline of how you might approach implementing such a function in JavaScript. Note that this is a simplified version and does not include all aspects discussed above, such as handling custom buffer size or deep cloning for performance optimization. It also doesn't include error handling or edge case scenarios. Also, please remember to adapt the implementation according to your specific requirements:

```javascript
const crypto = require('crypto');
const stream = require('stream').PassThrough;

async function copyData(dataChunks, limitSize, checksumAlgorithm) {
  let totalSize = 0;

  // Stream for memory management and asynchronous processing
  const dataStream = new stream();

  for (let chunk of dataChunks) {
    if (totalSize + chunk.length > limitSize) {
      throw new Error('Data size exceeded limit');
    }

    totalSize += chunk.length;

    // Piping the chunks to the stream for memory management and asynchronous processing
    dataStream.write(chunk);
  }

  let buffer = Buffer.concat([], totalSize);
  let pos = 0;

  return new Promise((resolve, reject) => {
    dataStream.on('data', (chunk) => {
      for (let i = 0; i < chunk.length; i++) {
        buffer[pos] = chunk[i];
        pos += 1;

        // If the buffer is full, resolve it and start a new one
        if (pos === limitSize) {
          dataStream.destroy();

          const checksum = crypto.createHash(checksumAlgorithm);
          checksum.update(buffer);

          resolve({
            buffer: Buffer.from(buffer),
            checksum: checksum.digest('hex')
          });
        }
      }
    });

    dataStream.on('error', reject);
  });
}
```
Remember that this is a simplified version and does not include all aspects discussed above such as handling custom buffer size or deep cloning for performance optimization. It also doesn't include error handling or edge case scenarios. Also, please remember to adapt the implementation according to your specific requirements. For high-load applications, consider using Web Workers for offloading heavy computations to avoid blocking the main thread.
