#include <stdio.h>
#include <pthread.h>
#include <netdb.h> 
#define MAX_URL_LEN 256

typedef struct {
    char url[MAX_URL_LEN];
} URL;

struct addrinfo* resolveDNS(const char* hostname) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;  // Use IPv4 or IPv6, whichever is available
    hints.ai_socktype = SOCK_STREAM;

    int status;
    if ((status = getaddrinfo(hostname, "80", &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    return res;
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
URL* urls[MAX_URL_LEN];
int urlCount = 0;

void readAndResolveUrls() {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    char url[MAX_URL_LEN];
    while(fgets(url, MAX_URL_LEN, stdin) != NULL) {
        struct addrinfo *res = resolveDNS(url);
        if (res == NULL) continue; // Error resolving DNS

        URL* newUrl = malloc(sizeof(URL));
        strncpy(newUrl->url, url, MAX_URL_LEN - 1);
        urls[urlCount++] = newUrl;
    }

    pthread_mutex_unlock(&lock); // Unlock after modifying shared data
}
```
This code reads URLs from standard input and performs a DNS resolution for each. It also ensures thread safety by locking the mutex before accessing and modifying shared data. Error handling is done via simple error messages printed to stderr. 

