Below is a basic outline of how you might write this function in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "processing_library.h" // Replace with actual processing library header

typedef struct {
    int* array;
    size_t used;
    size_t size;
} Array;

void initArray(Array* a, size_t initialSize) {
    a->array = (int*)malloc(initialSize * sizeof(int));
    if(a->array == NULL) exit(-1); // Handle memory allocation failure gracefully

    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array* a, int element) {
    // a->used is the number of used entries, because a->array[a->used++] updates a->used only *after* the array has been accessed.
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (int*)realloc(a->array, a->size * sizeof(int));
        if(a->array == NULL) exit(-1); // Handle memory allocation failure gracefully
    }
    a->array[a->used++] = element;
}

void freeArray(Array* a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}

int findLargestIndex(Array* a) {
    int largest_index = 0;
    for (int i = 1; i < a->used; i++) {
        if (a->array[i] >= a->array[largest_index]) {
            largest_index = i;
        }
    }
    return largest_index;
}

