["```javascript
class BufferManager {
  constructor(chunks) {
    this.chunks = chunks;
    this.totalSize = 0;

    for (const chunk of chunks) {
      if (!Buffer.isBuffer(chunk)) throw new TypeError('Expected a buffer');
      this.totalSize += chunk.length;
    }
  }

  copyData(buffer, offset, bytesToCopy) {
    let bytesCopied = 0;

    if (offset < 0 || bytesToCopy <= 0) return 0;
    if (!Buffer.isBuffer(buffer)) throw new TypeError('Expected a buffer');
    if (bytesToCopy > buffer.length - offset) bytesToCopy = buffer.length - offset;

    let chunkIndex = 0;
    while (chunkIndex < this.chunks.length && bytesToCopy > 0) {
      const chunkSize = this.chunks[chunkIndex].length;

      if (bytesToCopy >= chunkSize) {
        this.chunks[chunkIndex].copy(buffer, offset);

        bytesCopied += chunkSize;
        offset += chunkSize;
        bytesToCopy -= chunkSize;

        chunkIndex++;
      } else {
        let sourceOffset = 0;

        while (bytesToCopy > 0) {
          buffer.set(this.chunks[chunkIndex].slice(sourceOffset, sourceOffset + bytesToCopy), offset);

          bytesCopied += bytesToCopy;
          offset += bytesToCopy;
          bytesToCopy = 0;
        }
      }
    }

    return bytesCopied;
  }
}
```
The `BufferManager` class has a constructor that takes an array of buffers and calculates the total size. The `copyData()` method is used to copy data from these buffers into another buffer, with the number of bytes successfully copied being returned. It handles edge cases like invalid input parameters or out-of-range access.
"]

