List* list_create() {
    List* list = malloc(sizeof(*list));
    if (list == NULL) return NULL;

    list->capacity = 16;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    list->elements = malloc(sizeof(TCP_CONNECTION_RECORD_T*) * list->capacity);
    if (list->elements == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

void list_destroy(List* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int list_insert(List* list, TCP_CONNECTION_RECORD_T* element) {
    int result = 0;

    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        TCP_CONNECTION_RECORD_T** newElements = realloc(list->elements, sizeof(TCP_CONNECTION_RECORD_T*) * newCapacity);
        if (newElements == NULL) {
            result = -1;
        } else {
            list->capacity = newCapacity;
            list->elements = newElements;
        }
    }

    if (result == 0) {
        list->elements[list->count++] = element;
    } else {
        free(element);
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

