#include <stdio.h>
#include <pthread.h>
#include <unordered_map>
#include <string>
#include <fstream>

// Define a hashtable to store transformation rules
std::unordered_map<std::string, std::string> transformations;

// Function to load configuration from the file
void loadConfig(const char* filename) {
    std::ifstream configFile(filename);
    if (!configFile.is_open()) {
        printf("Failed to open config file\n");
        return;
    }

    std::string line;
    while (std::getline(configFile, line)) {
        size_t pos = line.find("=>");
        if (pos != std::string::npos) {
            std::string binaryData = line.substr(0, pos);
            std::string transformation = line.substr(pos + 2);
            transformations[binaryData] = transformation;
        }
    }
}

// Function to process a binary file
void* processFile(void *arg) {
    char* filename = (char*) arg;

    FILE* fp = fopen(filename, "rb");  // Open the file in binary mode
    if (!fp) {
        printf("Failed to open file: %s\n", filename);
        pthread_exit(NULL);
    }

