```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// For simplicity, let's say payload is a string of 100 characters max length
#define PAYLOAD_MAX_LENGTH 100
typedef struct {
    time_t timestamp;
    char messageType[25];
    char payload[PAYLOAD_MAX_LENGTH];
} RrcMessage;

// Define a linked list for messages, it's better if we often add to the end of list and memory usage is efficient
typedef struct MessageNode {
    RrcMessage message;
    struct MessageNode *next;
} MessageNode;

typedef struct {
    int ueId;
    time_t sessionEstablishmentTime;
    pthread_mutex_t mutex; // for thread safety
    MessageNode *messagesHead;
} UeSessionState;

UeSessionState* initializeArrayOfUeSessions(int numberOfSessions) {
    UeSessionState *sessions = (UeSessionState*)malloc(numberOfSessions * sizeof(UeSessionState));
    for (int i = 0; i < numberOfSessions; i++){
        sessions[i].ueId = i+1; // assigning unique ids from 1 to N
        sessions[i].sessionEstablishmentTime = time(NULL);
        pthread_mutex_init(&(sessions[i].mutex), NULL);
        sessions[i].messagesHead = NULL;
    }
    return sessions;
}

void addMessageToSession(UeSessionState *session, RrcMessage message) {
    MessageNode *newNode = (MessageNode*)malloc(sizeof(MessageNode));
    newNode->message = message; // Assuming deep copy is needed, otherwise shallow copy would suffice.
    newNode->next = NULL;

    pthread_mutex_lock(&(session->mutex));
    if (session->messagesHead == NULL) {
        session->messagesHead = newNode;
    } else {
        MessageNode *current = session->messagesHead;
        while (current->next != NULL) current = current->next;
        current->next = newNode;
    }
    pthread_mutex_unlock(&(session->mutex));
}

void printSessionDetails(UeSessionState *sessions, int numberOfSessions) {
    for (int i = 0; i < numberOfSessions; ++i){
        printf("UE ID: %d, Session Establishment Time: %s", sessions[i].ueId, ctime(&(sessions[i].sessionEstablishmentTime)));

        MessageNode *current = sessions[i].messagesHead;
        while (current != NULL) {
            printf("\tMessage Type: %s, Timestamp: %s, Payload: %s\n", 
                   current->message.messageType, ctime(&(current->message.timestamp)), current->message.payload);

            current = current->next;
        }
    }
}
```
