void print_help() {
    printf("Usage: program [OPTION]... [FILE]...\n");
    printf("\t--help\t display this help and exit\n");
    printf("\t-c\t count the characters in each line\n");
    printf("\t-o\t output to file\n");
}

void process_file(char *filename, int characterCountFlag) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening the file.\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int count = 0;

        // If characterCountFlag is set, count characters in the line
        if (characterCountFlag) {
            for (int i = 0; line[i] != '\0'; i++) {
                if (!isspace(line[i])) {
                    count += 1;
                }
            }
        } else {
            // Count lines
            count += 1;
        }

        printf("Count: %d\n", count);
    }

    fclose(file);
}

void process_directory(char *dirname, int characterCountFlag) {
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        printf("Error opening the directory.\n");
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char path[1024];

        snprintf(path, sizeof(path), "%s/%s", dirname, ent->d_name);

        struct stat st;
        if (stat(path, &st) == 0) {
            if (S_ISDIR(st.st_mode)) {
                // If it is a directory, recursively process the contents
                process_directory(path, characterCountFlag);
            } else if (S_ISREG(st.st_mode)) {
                // Else, process as file
                process_file(path, characterCountFlag);
            }
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    int characterCountFlag = 0;
    FILE *outputFile = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0) {
            characterCountFlag = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i+1 < argc) {
            outputFile = fopen(argv[++i], "w");
            if (outputFile == NULL) {
                printf("Error opening the output file.\n");
                return 1;
            }
        } else {
            struct stat st;
            // Check if it is a directory or a regular file.
            if (stat(argv[i], &st) == 0) {
                if (S_ISDIR(st.st_mode)) {
                    process_directory(argv[i], characterCountFlag);
                } else if (S_ISREG(st.st_mode)) {
                    process_file(argv[i], characterCountFlag);
                }
            } else {
                printf("Invalid argument.\n");
                print_help();
                return 1;
            }
        }
    }

    if (outputFile != NULL) {
        fclose(outputFile);
    }

    return 0;
}
