void usage() {
    printf("Usage: ./program -d directory [-o outputfile] [-c charcount]\n");
}

int getFiles(char *dir, int c) {
    DIR *dp;
    struct dirent *entry;
    struct stat statbuf;
    if((dp = opendir(dir)) == NULL) {
        fprintf(stderr,"Cannot open directory: %s\n", dir);
        return -1;
    }
    chdir(dir);
    while((entry = readdir(dp)) != NULL) {
        lstat(entry->d_name,&statbuf);
        if(S_ISDIR(statbuf.st_mode)) {
            if (strcmp(".",entry->d_name) == 0 || strcmp("..",entry->d_name) == 0)
                continue;
            getFiles(entry->d_name, c);
        } else {
            processFile(entry->d_name, c);
        }
    }
    chdir("..");
    closedir(dp);
}

void processFile(char *fname, int c) {
    FILE *fp;
    char buf[c+1]; // buffer size adjusted based on -c option
    fp = fopen(fname,"r");
    if (fp == NULL) {
        printf("Cannot open file: %s\n", fname);
        return;
    }
    while (!feof(fp)) {  // read one line at a time
        if (fgets(buf, c+1, fp) != NULL){
            if (buf[strlen(buf)-1] != '\n')
                printf("Buffer size too small\n");
            printf("%s", buf);  // print to stdout or redirected file
        }
    }
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int c = 80;
    FILE *fp = NULL;
    if (argc < 3 || strncmp(argv[1],"-d",2)) {  // check usage
        usage();
        return -1;
    }
    for (int i=2;i<argc;i++) {
        if (!strcmp(argv[i],"-h") || !strcmp(argv[i],"--help")) {  // print usage info
            usage();
            return -1;
        } else if (!strcmp(argv[i],"-o")) {   // redirect output to specified file
            fp = freopen(argv[++i], "w", stdout);
        } else if (!strcmp(argv[i],"-c")) {  // custom line length
            sscanf(argv[++i], "%d", &c);
        }
    }
    getFiles(argv[2], c);
    if (fp != NULL) fclose(fp);
    return 0;
}
```
