['Here is an example solution using POSIX Threads (pthread) for thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int SRB_ID;
    int DL_CQI_REPORT_TAG;
} NR_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NR_PDU_T *pduList;
    size_t count;
    size_t maxCount;
} PDUManager;

void initPDUManager(PDUManager *manager, size_t initialCapacity) {
    manager->count = 0;
    manager->maxCount = initialCapacity;
    manager->pduList = (NR_PDU_T*) malloc(initialCapacity * sizeof(NR_PDU_T));
    if (manager->pduList == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }
    pthread_mutex_init(&(manager->lock), NULL);
}

void addPDUToManager(PDUManager *manager, int srbId, int cqiReportTag) {
    pthread_mutex_lock(&(manager->lock));

    if (manager->count == manager->maxCount) {
        // If capacity is reached, double it.
        manager->maxCount *= 2;
        manager->pduList = realloc(manager->pduList, manager->maxCount * sizeof(NR_PDU_T));
    }

    if (manager->pduList == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    NR_PDU_T newPdu = { .SRB_ID = srbId, .DL_CQI_REPORT_TAG = cqiReportTag };
    manager->pduList[manager->count] = newPdu;
    (manager->count)++;

    pthread_mutex_unlock(&(manager->lock));
}

size_t getTotalPDUs(const PDUManager *manager) {
    size_t count;
    pthread_mutex_lock(&(manager->lock));
    count = manager->count;
    pthread_mutex_unlock(&(manager->lock));
    return count;
}

void resetPDUs(PDUManager *manager) {
    pthread_mutex_lock(&(manager->lock));
    manager->count = 0; // Reset the list, but keep allocated memory.
    pthread_mutex_unlock(&(manager->lock));
}

void destroyPDUManager(PDUManager *manager) {
    free(manager->pduList);
    manager->count = 0;
    manager->maxCount = 0;
    pthread_mutex_destroy(&(manager->lock));
}

void serializePDUManager(const PDUManager *manager, const char *fileName) {
    FILE *file = fopen(fileName, "wb");

    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    pthread_mutex_lock(&(manager->lock));
    size_t count = manager->count;
    fwrite(&count, sizeof(size_t), 1, file); // Write the total number of entries.
    fwrite(manager->pduList, sizeof(NR_PDU_T), manager->count, file); // Write each PDU.
    pthread_mutex_unlock(&(manager->lock));

    fclose(file);
}

void deserializePDUManager(PDUManager *manager, const char *fileName) {
    FILE *file = fopen(fileName, "rb");

    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file); // Read the total number of entries.

    pthread_mutex_lock(&(manager->lock));
    manager->pduList = realloc(manager->pduList, count * sizeof(NR_PDU_T));
    if (manager->pduList == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    fread(manager->pduList, sizeof(NR_PDU_T), count, file); // Read each PDU.
    manager->count = count;
    pthread_mutex_unlock(&(manager->lock));

    fclose(file);
}
``` 

This solution provides a thread-safe dynamic list of `NR_PDU_T` structures that can be serialized and deserialized to/from a binary file. The performance could be improved by using memory-mapped files, but the implementation would need to handle more complex synchronization issues. This version is simpler and works well for small datasets and single-threaded scenarios.
']

