#include <stdlib.h>
#include <pthread.h>

typedef struct Connection {
    char *source_ip;
    char *destination_ip;
    int source_port;
    int destination_port;
    enum state {ACTIVE, INACTIVE} connection_state; 
    // Other connection details...
} Connection;

typedef struct ConnectionListNode {
    Connection *connection;
    struct ConnectionListNode *next;
} ConnectionListNode;

ConnectionListNode *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int connectionCount = 0;
const int MAX_CONNECTIONS = 10000;

void addConnection(Connection *connection) {
    pthread_mutex_lock(&lock);
    if (connectionCount < MAX_CONNECTIONS) {
        ConnectionListNode *newNode = malloc(sizeof(ConnectionListNode));
        newNode->connection = connection;
        newNode->next = head;
        head = newNode;
        connectionCount++;
    } else {
        // Handle case where maximum connections are reached.
    }
    pthread_mutex_unlock(&lock);
}

void removeConnection(Connection *connection) {
    pthread_mutex_lock(&lock);
    ConnectionListNode **indirect = &head;
    while ((*indirect) != NULL) {
        if ((*indirect)->connection == connection) {
            ConnectionListNode *toRemove = *indirect;
            *indirect = toRemove->next;
            free(toRemove);
            connectionCount--;
            break;
        }
        indirect = &(*indirect)->next;
    }
    pthread_mutex_unlock(&lock);
}
``` 
This is a simple example of adding and removing connections in thread-safe manner. To handle the callback mechanism, you can use function pointers as parameters to your functions. For memory usage reporting, you could periodically check the amount of available memory using system calls such as `getrusage()` or `procps` API on Linux (e.g., read from "/proc/meminfo"). 

