    pthread_mutex_lock(&mutex); // lock mutex before memory allocation to prevent other threads from modifying the structure

    MAC_Transmission_Time_Request* arr = (MAC_Transmission_Time_Request*)malloc(M * sizeof(MAC_Transmission_Time_Request));
    if (arr == NULL) {
        pthread_mutex_unlock(&mutex); // unlock mutex before returning to prevent other threads from modifying the structure
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
