        arr[i].CellIdentity = rand();
        arr[i].TimeOffset = (double)rand() / RAND_MAX;
        arr[i].TimingAdvanceValue = rand();
    }

    pthread_mutex_unlock(&mutex); // unlock mutex after memory allocation to allow other threads to modify the structure

