```c
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    // Fields of MAC_Transmission_Time_Request
} MAC_Transmission_Time_Request;

struct dynamicArray {
    _Atomic size_t count;  // using atomic counter for thread safety
    pthread_rwlock_t rwlock; // lock to ensure safe access across threads
    MAC_Transmission_Time_Request *data;
};

int init(struct dynamicArray *array) {
    array->count = 0;

    if (pthread_rwlock_init(&array->rwlock, NULL) != 0) {
        perror("RW lock initialization failed");
        return -1;
    }

    // Allocating initial memory for the array elements. 
    array->data = calloc(4096, sizeof(MAC_Transmission_Time_Request));
    if (array->data == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    return 0;
}

void add(struct dynamicArray *array, MAC_Transmission_Time_Request data) {
    pthread_rwlock_wrlock(&array->rwlock); // acquire write lock to ensure exclusive access

    size_t index = atomic_fetch_add(&array->count, 1); // increment counter and get the old value
    if (index >= 4096) {
        fprintf(stderr, "Array is full\n");
    } else {
        array->data[index] = data;
    }

    pthread_rwlock_unlock(&array->rwlock); // release lock
}

void serialize(FILE *file, struct dynamicArray *array) {
    pthread_rwlock_rdlock(&array->rwlock); // acquire read lock to ensure data consistency

    size_t count = array->count;
    fwrite(&count, sizeof(size_t), 1, file); // write number of elements
    fwrite(array->data, sizeof(MAC_Transmission_Time_Request), count, file); // write data to the file

    pthread_rwlock_unlock(&array->rwlock); // release lock
}
```
This is just a starting point. You would need to expand on this example and add more functionality as per your needs. Also, please note that there are many ways you could potentially approach this problem, so the solution may not perfectly fit your needs. It's always crucial to consider trade-offs and requirements while designing software.
