#define MAX_PAYLOAD 1024

typedef struct {
    time_t timestamp; // Timestamp of message creation
    int userID;       // ID of user who created the message
    char* payload;    // Dynamic payload data
} Message;

// Function to initialize a message structure with timestamp, user ID and payload. 
Message* init_message(int userID, const void* payloadData, size_t payloadSize) {
    if (payloadSize == 0 || payloadSize > MAX_PAYLOAD) return NULL;

    Message* msg = malloc(sizeof(Message));
    if (!msg) return NULL; // Handle memory allocation failure

    msg->timestamp = time(NULL);
    msg->userID = userID;
    msg->payload = malloc(payloadSize);
    if (!msg->payload) { // If payload memory allocation fails, free the entire message.
        free(msg);
        return NULL;
    }

    memcpy(msg->payload, payloadData, payloadSize); // Copy payload data into allocated memory.
    return msg;
}

// Function to initialize a list of messages with specified size and payload data
Message** init_message_list(int userID, const void* payloadData, size_t payloadSize, int N) {
    if (payloadSize == 0 || payloadSize > MAX_PAYLOAD || N <= 0) return NULL;

    Message** list = malloc(N * sizeof(Message*)); // Allocate memory for the list of message pointers.
    if (!list) return NULL; // Handle memory allocation failure

    for (int i = 0; i < N; ++i) { 
        list[i] = init_message(userID, payloadData, payloadSize);

        if (!list[i]) { // If initialization of any message fails, free all previously allocated messages and return NULL.
            for (int j = 0; j < i; ++j) free(list[j]); 
            free(list); // Free list pointer array
            return NULL;
        }
    }

    return list;
}
