    int id;
    atomic_bool available;
} Buffer;

typedef struct {
    Buffer buffers[MAX_BUFFERS];
    pthread_mutex_t mutex;
    atomic_int bufferCount;
} BufferPool;

BufferPool pool;

void init(BufferPool* pool, int N) {
    for (int i = 0; i < N; ++i) {
        pool->buffers[i].id = i;
        atomic_init(&pool->buffers[i].available, true);
    }

    pthread_mutex_init(&pool->mutex, NULL);
    atomic_init(&pool->bufferCount, N);
}

Buffer* allocate(BufferPool* pool) {
    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (atomic_load(&pool->buffers[i].available)) {
            if (atomic_fetch_sub(&pool->bufferCount, 1) > 0) {
                atomic_store(&pool->buffers[i].available, false);
                return &pool->buffers[i];
            } else {
                atomic_fetch_add(&pool->bufferCount, 1);
            }
        }
    }

    return NULL; // No available buffers
}

void deallocate(BufferPool* pool, Buffer* buffer) {
    pthread_mutex_lock(&pool->mutex);
    atomic_store(&buffer->available, true);
    atomic_fetch_add(&pool->bufferCount, 1);
    pthread_mutex_unlock(&pool->mutex);
}

