["Here is a JavaScript function implementing this requirement:

```javascript
async function copyBytes(dataChunks, byteSize, mode = 'sync') {
  const outputBuffer = Buffer.alloc(byteSize);
  let bytesCopied = 0;

  for (let chunk of dataChunks) {
    if (mode === 'sync' && chunk instanceof Buffer) {
      bytesCopied += chunk.copy(outputBuffer, bytesCopied);
    } else if (mode === 'async') {
      const buffer = await toBufferAsync(chunk);
      bytesCopied += buffer.copy(outputBuffer, bytesCopied);
    }

    if (bytesCopied >= byteSize) break;
  }

  return outputBuffer;
}

function toBufferAsync(streamOrBuffer) {
  if (streamOrBuffer instanceof Buffer) {
    return Promise.resolve(streamOrBuffer);
  } else {
    return streamToBuffer(streamOrBuffer);
  }
}

function streamToBuffer(stream) {
  return new Promise((resolve, reject) => {
    const chunks = [];

    stream.on('data', chunk => chunks.push(chunk));
    stream.on('error', reject);
    stream.on('end', () => resolve(Buffer.concat(chunks)));
  });
}
```
This function accepts an array of data chunks (either Buffers or Readable streams), the total number of bytes to copy, and a mode for handling asynchronous operations ('sync' or 'async'). It creates a new buffer with the specified size and then sequentially copies data from each chunk into this buffer. If an incomplete chunk is encountered and padding zeros are still required, it will continue to pad with zeros until the total byte size has been met. For synchronous input streams, it uses the Node.js Buffer's copy() method for efficient copying. In case of asynchronous inputs, it first converts the stream into a Promise that resolves to a Buffer. This approach is suitable for low-latency and high-throughput data processing in performance-critical applications.
"]

