void conditional_log(int enableFlag, const char *format, ...) {
    static FILE *fp = NULL;
    va_list args;

    if (enableFlag && logLevel > 0) { // Check the log level and if logging is enabled
        if (!fp) fp = fopen(LOG_FILE, "a");

