                va_start(args, format);

                time_t now = time(NULL);
                struct tm *nowLocal = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", nowLocal);

                int size = snprintf(buffer, MAX_BUFFER_SIZE, "[%s] ", timestamp);

                // Ensure buffer isn't exceeded before adding formatted message.
                if (size < MAX_BUFFER_SIZE) {
                    vsnprintf(buffer + size, MAX_BUFFER_SIZE - size, format, args);
                } else {
                    fprintf(stderr, "Log message exceeds maximum buffer size\n");
                    return;
                }

                va_end(args);

                // Try to write log entry.
                if (flockfile(fp) == 0 && fwrite(buffer, sizeof(char), strlen(buffer), fp) > 0) {
