typedef struct tcp_connection {
    char* src_ip; 
    int src_port;
    char* dest_ip;
    int dest_port;
    connection_state state;
    struct tcp_connection *prev, *next; // For linked list operations.
} tcp_connection;

// Global variables for linked list and lock to manage multithreading access.
tcp_connection* conn_list = NULL;
pthread_mutex_t conn_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new connection.
tcp_connection* tcp_create(char* src_ip, int src_port, char* dest_ip, int dest_port) {
    pthread_mutex_lock(&conn_lock); // Lock for thread-safe operations...

    tcp_connection* conn = (tcp_connection*)malloc(sizeof(tcp_connection));
    if (!conn) return NULL;

    conn->src_ip = strdup(src_ip); // Duplicate strings to avoid data corruption.
    conn->dest_ip = strdup(dest_ip);
    conn->src_port = src_port;
    conn->dest_port = dest_port;
    conn->state = ESTABLISHED; // Start connection in ESTABLISHED state.

    conn->prev = NULL;
    conn->next = conn_list; // Add at the head of list...
    if (conn_list) conn_list->prev = conn; 
    conn_list = conn;

    pthread_mutex_unlock(&conn_lock); // Unlock for other operations.

    return conn;
}
