// Global counters for successful and failed allocations
unsigned long successAlloc = 0, failAlloc = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocateArray(int numUe) {
    // Ensure the allocation size is within reasonable bounds
    assert(numUe > 0 && numUe < 10000); 

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    while (numUe > 0) {
        array = realloc(array, sizeof(*array) * numUe);

        if (!array) {
            pthread_mutex_lock(&mutex);
            ++failAlloc;
            printf("Failed allocation attempt: %lu\n", failAlloc);
            pthread_mutex_unlock(&mutex);
            return NULL; // Failed to allocate memory, exit the loop and function
        } else {
            for (int i = 0; i < numUe; ++i) {
                array[i].RX_UE_INFORMATION_TAG = rand() % 100;
                array[i].RNTI = rand() % 10000;
                array[i].CRC_INDICATION_REL8_TAG = rand() % 5000;
                array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG between 0 and 1
            }

            pthread_mutex_lock(&mutex);
            successAlloc += numUe;
            printf("Successful allocation: %lu\n", successAlloc);
            pthread_mutex_unlock(&mutex);
        }

        // Reduce the number of UEs to allocate for each successful loop iteration
        numUe -= 1000; 
    }

    return array;
}
```
