#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct UENode {
    char* identifier;
    // more fields as required...
    struct UENode *prev, *next;
} UENode;

typedef struct UEList {
    UENode* head;
    UENode* tail;
    int size;
} UEList;

// For hashmap implementation
#define MAX_HASH 50000
UENode *hashMap[MAX_HASH];

void insert(UEList* list, char* identifier) {
    UENode* newNode = (UENode*)malloc(sizeof(UENode));
    newNode->identifier = strdup(identifier);

    int hashIndex = abs((int)strtol(newNode->identifier, NULL, 10)) % MAX_HASH;
    while (hashMap[hashIndex] != NULL && strcmp(hashMap[hashIndex]->identifier, identifier) != 0) {
        hashIndex = (hashIndex + 1) % MAX_HASH;
    }

    if (hashMap[hashIndex] == NULL) {  // not a duplicate
        newNode->prev = list->tail;
        newNode->next = NULL;

        if(list->tail != NULL) {
            list->tail->next = newNode;
        } else {
            list->head = newNode;
        }
        list->tail = newNode;
        hashMap[hashIndex] = newNode;
        (list->size)++;
    } else {
        printf("Duplicate insertion attempted: %s\n", identifier);
    }
}

void remove(UEList* list, char* identifier) {
    int hashIndex = abs((int)strtol(identifier, NULL, 10)) % MAX_HASH;

    while (hashMap[hashIndex] != NULL) {
        if (strcmp(hashMap[hashIndex]->identifier, identifier) == 0) {
            UENode* toRemove = hashMap[hashIndex];

            if(toRemove->prev != NULL){
                toRemove->prev->next = toRemove->next;
            } else{
                list->head = toRemove->next;
            }

            if(toRemove->next != NULL){
                toRemove->next->prev = toRemove->prev;
            } else{
                list->tail = toRemove->prev;
            }

            free(toRemove);
            hashMap[hashIndex] = NULL;
            (list->size)--;
            return;
        }

        hashIndex = (hashIndex + 1) % MAX_HASH;
    }

    printf("Removal attempted for non-existing identifier: %s\n", identifier);
}

void cleanup(UEList* list) {
    UENode *node = list->head, *nextNode;

    while (node != NULL){
        nextNode = node->next;
        free(node);
        node = nextNode;
    }

    for(int i = 0; i < MAX_HASH; ++i) {
      hashMap[i] = NULL;
    }
}
```

Please note, this code is a simplified example. A real-world solution would require a more complex network interface handling and UE information tracking mechanisms, logging, error handling, and so on. The performance of the list depends on many factors (CPU cache, memory allocation strategy, etc.). It also doesn't cover the integration with a existing management framework as it would be very specific to each system.
