int parameterized_sql_logging(DBConnection *conn, int value_count, int values[], 
                             const char* format, FILE* logfile, int enable_log, 
                             const char* condition, va_list args) {
    /* Allocate buffers for SQL command and log message */
    size_t maxlen = value_count * 20 + 1; // Change this to appropriate length
    char sql[maxlen];
    char logmsg[maxlen];

    /* Format the SQL command with values */
    snprintf(sql, maxlen, format, (const int*)values);

    if (enable_log) {
        time_t rawtime;
        struct tm * timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        /* Format the log message */
        snprintf(logmsg, maxlen, "[%s]: ", asctime(timeinfo)); // Start with timestamp
        vsnprintf(logmsg + strlen(logmsg), maxlen - strlen(logmsg), condition, args); // Append condition message

        /* Execute the SQL command and capture result */
        DBResult res = execute_sql(conn, sql);

        /* Write log message to file */
        fprintf(logfile, "%s\n", logmsg);

        return res.status; // Return status of execution
    } else {
        /* Format the log message */
        vsnprintf(logmsg, maxlen, condition, args);

        /* Write log message to file */
        fprintf(logfile, "%s\n", logmsg);
    }

    return 0; // If logging is disabled, just write the log message and assume status of 0
}
