typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define DEFAULT_CAPACITY 1024

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
} DynamicBuffer;

void DynamicBufferInit(DynamicBuffer* buf) {
    assert(buf != NULL);

    pthread_mutex_init(&buf->lock, NULL);
    buf->capacity = DEFAULT_CAPACITY;
    buf->size = 0;
    buf->buffer = malloc(DEFAULT_CAPACITY * sizeof(*buf->buffer));
}

void DynamicBufferAppend(DynamicBuffer* buf, NFAPI_CRC_INDICATION_PDU_T pdu) {
    assert(buf != NULL);

    pthread_mutex_lock(&buf->lock);

    if (buf->size == buf->capacity) {
        buf->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* newBuffer = realloc(buf->buffer, 
                                                        buf->capacity * sizeof(*newBuffer));
        if (newBuffer == NULL) {
            // Handle error here. You may need to free old buffer and return an error code or something similar.
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&buf->lock);
            return;
        } else {
            buf->buffer = newBuffer;
        }
    }

    memcpy(&buf->buffer[buf->size], &pdu, sizeof(pdu));
    ++buf->size;

    pthread_mutex_unlock(&buf->lock);
}

// Other functions for sorting and cleaning up the buffer would go here. Also, code to handle validation of RNTI values,
// prevention of duplicates in PDUs, and integration with existing components could be added. 
