['Here's a basic implementation for your requirements. Note that this is a very simplistic approach and does not cover all possible edge cases or security considerations. It is also assumed that you have implemented an ILogger interface for logging purposes. 

```csharp
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly TripleDESCryptoServiceProvider _tripleDes = new TripleDESCryptoServiceProvider();
    private readonly HMACSHA256 _hmacsha256 = new HMACSHA256(Encoding.UTF8.GetBytes("YourSecretKey"));
    private readonly ILogger _logger;

    public DecryptionService(ILogger logger)
    {
        _tripleDes.Key = Encoding.UTF8.GetBytes("YourTripleDESKey");
        _tripleDes.IV = Encoding.UTF8.GetBytes("YourInitializationVector");
        _logger = logger;
    }

    public async Task<IEnumerable<string>> DecryptAndVerifyMessagesAsync(IEnumerable<string> messages)
    {
        var decryptedMessages = new ConcurrentBag<string>();

        await Parallel.ForEachAsync(messages, async (message, token) =>
        {
            try
            {
                byte[] encryptedBytes = Convert.FromBase64String(message);
                using (var decryptor = _tripleDes.CreateDecryptor())
                {
                    byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                    string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

                    if (VerifyMac(_hmacsha256, message, decryptedMessage))
                    {
                        decryptedMessages.Add(decryptedMessage);
                        _logger.Log("Successful decryption and verification", LogLevel.Info);
                    }
                    else
                    {
                        throw new Exception("MAC Verification failed");
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Log($"Decryption or verification error: {ex.Message}", LogLevel.Error);
            }
        });

        return decryptedMessages;
    }

    private bool VerifyMac(HMACSHA256 hmac, string originalMessage, string decryptedMessage)
    {
        byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(originalMessage));
        return hash.SequenceEqual(_hmacsha256.Hash);
    }
}
```
This code uses Parallel.ForEachAsync to efficiently process all messages in parallel, which should be beneficial for large-scale processing. It also logs each operation and handles exceptions to prevent the entire process from failing due to one bad message. The decrypted messages are stored in a ConcurrentBag, which supports concurrent read and write operations.
']

