import json
from ctypes import Structure, c_uint16, Union

class BSR_DATA_TAG(Structure):
    _fields_ = [("BIT_RATE_VALUE", c_uint16)]

class LTE_ENB_RRC_RECONFIGURATION_REQUEST_T(Structure):
    _fields_ = [("PDCP_SN", c_uint16), ("PDCP_SEQUENCE_NUMBER", c_uint16), ("BSR_DATA_TAG", BSR_DATA_TAG)]

def to_json(lte_rrc_structures):
    # Convert the LTE_ENB_RRC_RECONFIGURATION_REQUEST_T structures into a JSON string.
    json_string = "{"
    for i, rrc in enumerate(lte_rrc_structures):
        key = f"request_{i}"  # Generate unique keys
        value = {
            "PDCP_SN": rrc.PDCP_SN, 
            "PDCP_SEQUENCE_NUMBER": rrc.PDCP_SEQUENCE_NUMBER,
            "BIT_RATE_VALUE": rrc.BSR_DATA_TAG.BIT_RATE_VALUE
        }
        json_string += f"'{key}': {json.dumps(value)},"  # Convert value to JSON string and add it to the main string.
    json_string = json_string.rstrip(',') + "}"

    return json_string
```

